/* === /static/composables/useTableSort.js === */
/**
 * useTableSort.js
 * Vue composable for table sorting functionality
 * 
 * Migrated from web_static/app.js sortTable() function
 * Provides sorting capabilities with asc/desc toggle, numeric/string support,
 * and visual indicators via data attributes
 */

/**
 * Composable for table sorting functionality
 * 
 * @returns {Object} Sorting state and methods
 */
window.useTableSort = function(initialData = [], defaultSort = null) {
	// Use Vue globals (scoped to function to avoid redeclaration)
	const { ref, computed, watch, unref } = Vue;

	// Support passing a ref/computed as the data source
	const isRefSource = initialData && typeof initialData === 'object' && 'value' in initialData;
	const dataSource = isRefSource ? initialData : ref(initialData || []);

    // Sorting state
    const sortColumn = ref(null);
    const sortDirection = ref('asc');
    const sortNumeric = ref(false);
    const sortedData = ref([]);

	/**
	 * Sort table data by column
	 * 
	 * @param {Array} data - Array of objects to sort
	 * @param {String} columnKey - Key to sort by
	 * @param {Boolean} isNumeric - Whether to sort as numbers (default: false)
	 * @returns {Array} Sorted array
	 */
    const sortData = (data = unref(dataSource), columnKey = null, isNumeric) => {
        if (!data || !Array.isArray(data)) {
            console.warn('[useTableSort] Invalid data provided');
            return [];
        }

        // If columnKey not provided, use currently selected column
        const key = columnKey || sortColumn.value;
        if (!key) {
            // Nothing to sort by; just return original
            sortedData.value = [...data];
            return sortedData.value;
        }

        let numeric;
        if (columnKey == null) {
            numeric = sortNumeric.value;
        } else if (isNumeric === undefined || isNumeric === null) {
            numeric = false;
        } else {
            numeric = !!isNumeric;
        }

        // Toggle direction if same column, otherwise default to ascending
        if (sortColumn.value === key && columnKey) {
            // If explicit column requested and it's the same, toggle
            sortDirection.value = sortDirection.value === 'asc' ? 'desc' : 'asc';
        } else if (columnKey) {
            sortColumn.value = key;
            sortDirection.value = 'asc';
        }

        if (columnKey) {
            sortNumeric.value = numeric;
        }

        // Create shallow copy to avoid mutating original
        const sorted = [...data].sort((a, b) => {
            let valA = a[columnKey];
            let valB = b[columnKey];

            // If using inferred key variable, fall back
            if (columnKey == null) {
                valA = a[key];
                valB = b[key];
            }

			// Handle null/undefined values
			if (valA == null && valB == null) return 0;
			if (valA == null) return 1;
			if (valB == null) return -1;

			// Numeric comparison
            if (numeric) {
                valA = parseFloat(valA);
                valB = parseFloat(valB);

				// Handle NaN
				if (isNaN(valA) && isNaN(valB)) return 0;
				if (isNaN(valA)) return 1;
				if (isNaN(valB)) return -1;

				const diff = valA - valB;
				return sortDirection.value === 'asc' ? diff : -diff;
			}

			// String comparison (case-insensitive)
			const strA = String(valA).toLowerCase();
			const strB = String(valB).toLowerCase();

			if (strA < strB) return sortDirection.value === 'asc' ? -1 : 1;
			if (strA > strB) return sortDirection.value === 'asc' ? 1 : -1;
			return 0;
		});

		sortedData.value = sorted;
        return sorted;
    };

	/**
	 * Reset sorting state
	 */
    const resetSort = () => {
        sortColumn.value = null;
        sortDirection.value = 'asc';
        sortNumeric.value = false;
        sortedData.value = [];
    };

	/**
	 * Get sort attributes for <th> elements
	 * Used with data-sortable, data-sort-dir attributes for CSS styling
	 * 
	 * @param {String} columnKey - Column key
	 * @returns {Object} Attributes object { 'data-sortable': true, 'data-sort-dir': 'asc'|'desc'|null }
	 */
	const getSortAttributes = (columnKey) => {
		const attrs = {
			'data-sortable': true,
			'data-sort-dir': sortColumn.value === columnKey ? sortDirection.value : null
		};
		return attrs;
	};

	/**
	 * Check if column is currently sorted
	 * 
	 * @param {String} columnKey - Column key
	 * @returns {Boolean}
	 */
	const isSorted = (columnKey) => {
		return sortColumn.value === columnKey;
	};

	/**
	 * Get sort indicator for UI (arrows)
	 * 
	 * @param {String} columnKey - Column key
	 * @returns {String} Sort indicator: '⇅' (sortable), '↑' (asc), '↓' (desc)
	 */
	const getSortIndicator = (columnKey) => {
		if (sortColumn.value !== columnKey) {
			return '⇅'; // Sortable but not currently sorted
		}
		return sortDirection.value === 'asc' ? '↑' : '↓';
	};

	/**
	 * Apply default sort to data (e.g., on component mount)
	 * 
	 * @param {Array} data - Data to sort
	 * @param {String} columnKey - Default sort column
	 * @param {Boolean} isNumeric - Whether to sort as numbers
	 * @param {String} direction - Default direction ('asc' or 'desc')
	 * @returns {Array} Sorted data
	 */
    const applyDefaultSort = (data, columnKey, isNumeric = false, direction = 'asc') => {
        sortColumn.value = columnKey;
        sortDirection.value = direction;
        sortNumeric.value = !!isNumeric;
        return sortData(data);
    };

	// Computed properties
	const currentColumn = computed(() => sortColumn.value);
	const currentDirection = computed(() => sortDirection.value);
	const hasSortedData = computed(() => sortedData.value.length > 0);

	// Compose a currentSort object for compatibility with the component
    const currentSort = computed(() => ({ column: sortColumn.value, order: sortDirection.value, numeric: sortNumeric.value }));

	// Toggle sort (component-friendly API)
    const toggleSort = (columnKey, isNumeric = false) => {
        // Call sortData with explicit columnKey to toggle or set
        return sortData(unref(dataSource), columnKey, isNumeric);
    };

    // If defaultSort provided, apply it initially
    if (defaultSort && defaultSort.column) {
        try {
            applyDefaultSort(unref(dataSource), defaultSort.column, defaultSort.numeric || false, defaultSort.order || 'asc');
        } catch (e) {
            // ignore
        }
    }

    // Watch the provided input data (initialData) and reapply current sort when it changes.
    // This is more reliable when the caller passes a reactive prop (e.g., props.data).
    watch(
        () => unref(dataSource),
        (newVal) => {
            if (!newVal) {
                sortedData.value = [];
                return;
            }
            if (sortColumn.value) {
                sortData(newVal);
            } else if (defaultSort && defaultSort.column) {
                applyDefaultSort(newVal, defaultSort.column, defaultSort.numeric || false, defaultSort.order || 'asc');
            } else {
                sortedData.value = Array.isArray(newVal) ? [...newVal] : [];
            }
        },
        { deep: true, immediate: true }
    );

	return {
		// State
		sortColumn,
		sortDirection,
		sortedData,
		// Computed
		currentColumn,
		currentDirection,
		hasSortedData,
		currentSort,

		// Methods
		sortData,
		toggleSort,
		resetSort,
		getSortAttributes,
		isSorted,
		getSortIndicator,
		applyDefaultSort
	};
}

/**
 * Usage Example:
 * 
 * <script setup>
 * import { ref, onMounted } from 'vue';
 * import { useTableSort } from './composables/useTableSort.js';
 * 
 * const rawData = ref([
 *   { name: 'Team A', wins: 10, losses: 5 },
 *   { name: 'Team B', wins: 8, losses: 7 }
 * ]);
 * 
 * const { sortData, getSortAttributes, getSortIndicator, applyDefaultSort } = useTableSort();
 * 
 * // Apply default sort on mount
 * onMounted(() => {
 *   const sorted = applyDefaultSort(rawData.value, 'wins', true, 'desc');
 *   displayData.value = sorted;
 * });
 * 
 * // Handle column click
 * const handleSort = (columnKey, isNumeric) => {
 *   const sorted = sortData(rawData.value, columnKey, isNumeric);
 *   displayData.value = sorted;
 * };
 * </script>
 * 
 * <template>
 *   <table>
 *     <thead>
 *       <tr>
 *         <th v-bind="getSortAttributes('name')" @click="handleSort('name', false)">
 *           Team {{ getSortIndicator('name') }}
 *         </th>
 *         <th v-bind="getSortAttributes('wins')" @click="handleSort('wins', true)">
 *           Wins {{ getSortIndicator('wins') }}
 *         </th>
 *       </tr>
 *     </thead>
 *     <tbody>
 *       <tr v-for="row in displayData" :key="row.name">
 *         <td>{{ row.name }}</td>
 *         <td>{{ row.wins }}</td>
 *       </tr>
 *     </tbody>
 *   </table>
 * </template>
 */


/* === /static/composables/useCellColorization.js === */
/**
 * useCellColorization.js
 * Vue composable for continuous cell colorization based on quartile distribution
 * 
 * Migrated from web_static/app.js colorizeContinuous() function
 * Applies gradient background colors to table cells based on value distribution
 */

/**
 * Composable for continuous cell colorization
 * 
 * @returns {Object} Colorization methods
 */
window.useCellColorization = function() {
	// Use Vue globals (scoped to function to avoid redeclaration)
	const { computed } = Vue;

	/**
	 * Interpolate between two colors
	 * 
	 * @param {String} color1 - Start color (hex)
	 * @param {String} color2 - End color (hex)
	 * @param {Number} factor - Interpolation factor (0-1)
	 * @returns {String} Interpolated hex color
	 */
	const interpolateColor = (color1, color2, factor) => {
		const c1 = parseInt(color1.slice(1), 16);
		const c2 = parseInt(color2.slice(1), 16);
		
		const r1 = (c1 >> 16) & 0xff;
		const g1 = (c1 >> 8) & 0xff;
		const b1 = c1 & 0xff;
		
		const r2 = (c2 >> 16) & 0xff;
		const g2 = (c2 >> 8) & 0xff;
		const b2 = c2 & 0xff;
		
		const r = Math.round(r1 + (r2 - r1) * factor);
		const g = Math.round(g1 + (g2 - g1) * factor);
		const b = Math.round(b1 + (b2 - b1) * factor);
		
		return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
	};

	/**
	 * Calculate quartiles from data array
	 * 
	 * @param {Array} values - Array of numeric values
	 * @returns {Object} { p25, p50, p75 } Quartile values
	 */
	const calculateQuartiles = (values) => {
		if (!values || values.length === 0) {
			return { p25: 0, p50: 0, p75: 0 };
		}

		const sorted = [...values].sort((a, b) => a - b);
		const len = sorted.length;

		const getPercentile = (p) => {
			const index = (p / 100) * (len - 1);
			const lower = Math.floor(index);
			const upper = Math.ceil(index);
			const weight = index % 1;
			
			if (lower === upper) return sorted[lower];
			return sorted[lower] * (1 - weight) + sorted[upper] * weight;
		};

		return {
			p25: getPercentile(25),
			p50: getPercentile(50),
			p75: getPercentile(75)
		};
	};

	/**
	 * Get cell background color based on value and quartiles
	 * 
	 * @param {Number} value - Cell value
	 * @param {Object} quartiles - { p25, p50, p75 }
	 * @param {Boolean} inverse - Invert color scale (lower = better)
	 * @returns {String} CSS color value (rgba)
	 */
	const getCellColor = (value, quartiles, inverse = false) => {
		const { p25, p50, p75 } = quartiles;
		const val = parseFloat(value);

		if (isNaN(val)) {
			return 'transparent';
		}

		// Define color scale (green = good, red = bad)
		const colors = {
			excellent: 'rgba(34, 197, 94, 0.25)',  // Green
			good: 'rgba(58, 163, 255, 0.18)',       // Blue
			moderate: 'rgba(244, 191, 79, 0.18)',   // Yellow
			poor: 'rgba(239, 68, 68, 0.22)'         // Red
		};

		let color;
		
		if (inverse) {
			// Lower values are better (e.g., deaths, loss%)
			if (val <= p25) {
				color = colors.excellent;
			} else if (val <= p50) {
				color = colors.good;
			} else if (val <= p75) {
				color = colors.moderate;
			} else {
				color = colors.poor;
			}
		} else {
			// Higher values are better (e.g., kills, win%)
			if (val >= p75) {
				color = colors.excellent;
			} else if (val >= p50) {
				color = colors.good;
			} else if (val >= p25) {
				color = colors.moderate;
			} else {
				color = colors.poor;
			}
		}

		return color;
	};

	/**
	 * Get gradient background style for cell
	 * 
	 * @param {Number} value - Cell value
	 * @param {Object} quartiles - { p25, p50, p75 }
	 * @param {Boolean} inverse - Invert color scale
	 * @returns {Object} Style object for Vue binding
	 */
	const getCellStyle = (value, quartiles, inverse = false) => {
		const color = getCellColor(value, quartiles, inverse);
		
		return {
			background: `linear-gradient(90deg, ${color}, transparent)`,
			transition: 'background 0.3s ease'
		};
	};

	/**
	 * Colorize entire column of data
	 * 
	 * @param {Array} data - Array of row objects
	 * @param {String} columnKey - Key to extract values
	 * @param {Boolean} inverse - Invert color scale
	 * @returns {Array} Array of style objects for each row
	 */
	const colorizeColumn = (data, columnKey, inverse = false) => {
		if (!data || !Array.isArray(data)) {
			return [];
		}

		// Extract values and calculate quartiles
		const values = data
			.map(row => parseFloat(row[columnKey]))
			.filter(val => !isNaN(val));

		if (values.length === 0) {
			return data.map(() => ({ background: 'transparent' }));
		}

		const quartiles = calculateQuartiles(values);

		// Generate styles for each row
		return data.map(row => {
			const value = parseFloat(row[columnKey]);
			return isNaN(value) 
				? { background: 'transparent' }
				: getCellStyle(value, quartiles, inverse);
		});
	};

	/**
	 * Process multiple columns for colorization
	 * 
	 * @param {Array} data - Array of row objects
	 * @param {Object} columnConfig - { columnKey: { inverse: boolean } }
	 * @returns {Object} { [columnKey]: Array<StyleObject> }
	 */
	const colorizeMultipleColumns = (data, columnConfig) => {
		const result = {};

		for (const [columnKey, config] of Object.entries(columnConfig)) {
			const inverse = config.inverse || false;
			result[columnKey] = colorizeColumn(data, columnKey, inverse);
		}

		return result;
	};

	/**
	 * Get text color class based on value comparison to median
	 * 
	 * @param {Number} value - Cell value
	 * @param {Number} median - Median value (p50)
	 * @param {Boolean} inverse - Invert color logic
	 * @returns {String} CSS class name
	 */
	const getTextColorClass = (value, median, inverse = false) => {
		const val = parseFloat(value);
		if (isNaN(val)) return 'cell-muted';

		if (inverse) {
			return val < median ? 'stat-positive' : 'stat-negative';
		} else {
			return val > median ? 'stat-positive' : 'stat-negative';
		}
	};

	/**
	 * Create color scale legend data
	 * 
	 * @param {Object} quartiles - { p25, p50, p75 }
	 * @param {Boolean} inverse - Invert scale
	 * @returns {Array} Legend items [{ label, color, value }]
	 */
	const createLegend = (quartiles, inverse = false) => {
		const { p25, p50, p75 } = quartiles;

		const items = [
			{ label: 'Excellent', color: 'rgba(34, 197, 94, 0.25)', value: inverse ? `≤ ${p25.toFixed(1)}` : `≥ ${p75.toFixed(1)}` },
			{ label: 'Good', color: 'rgba(58, 163, 255, 0.18)', value: inverse ? `≤ ${p50.toFixed(1)}` : `≥ ${p50.toFixed(1)}` },
			{ label: 'Moderate', color: 'rgba(244, 191, 79, 0.18)', value: inverse ? `≤ ${p75.toFixed(1)}` : `≥ ${p25.toFixed(1)}` },
			{ label: 'Poor', color: 'rgba(239, 68, 68, 0.22)', value: inverse ? `> ${p75.toFixed(1)}` : `< ${p25.toFixed(1)}` }
		];

		return items;
	};

	return {
		// Core colorization
		getCellColor,
		getCellStyle,
		colorizeColumn,
		colorizeMultipleColumns,

		// Utilities
		calculateQuartiles,
		interpolateColor,
		getTextColorClass,
		createLegend
	};
};

/**
 * Usage Example:
 * 
 * <script setup>
 * import { ref, computed } from 'vue';
 * import { useCellColorization } from './composables/useCellColorization.js';
 * 
 * const { colorizeColumn, calculateQuartiles, getCellStyle } = useCellColorization();
 * 
 * const playerData = ref([
 *   { name: 'Player 1', kd: 1.25, deaths: 45 },
 *   { name: 'Player 2', kd: 0.95, deaths: 52 },
 *   { name: 'Player 3', kd: 1.42, deaths: 38 }
 * ]);
 * 
 * // Colorize K/D column (higher is better)
 * const kdStyles = computed(() => colorizeColumn(playerData.value, 'kd', false));
 * 
 * // Colorize deaths column (lower is better)
 * const deathStyles = computed(() => colorizeColumn(playerData.value, 'deaths', true));
 * </script>
 * 
 * <template>
 *   <table>
 *     <thead>
 *       <tr>
 *         <th>Player</th>
 *         <th>K/D Ratio</th>
 *         <th>Deaths</th>
 *       </tr>
 *     </thead>
 *     <tbody>
 *       <tr v-for="(player, idx) in playerData" :key="player.name">
 *         <td>{{ player.name }}</td>
 *         <td :style="kdStyles[idx]">{{ player.kd.toFixed(2) }}</td>
 *         <td :style="deathStyles[idx]">{{ player.deaths }}</td>
 *       </tr>
 *     </tbody>
 *   </table>
 * </template>
 */


/* === /static/utils/divisionNormalizer.js === */
(function () {
    'use strict';

    const TIER_RANGES = [
        { id: 1, label: 'Tier 1 (Div 1-5)', range: 'Div 1-5', min: 1, max: 5 },
        { id: 2, label: 'Tier 2 (Div 6-10)', range: 'Div 6-10', min: 6, max: 10 },
        { id: 3, label: 'Tier 3 (Div 11-15)', range: 'Div 11-15', min: 11, max: 15 },
        { id: 4, label: 'Tier 4 (Div 16-20)', range: 'Div 16-20', min: 16, max: 20 },
        { id: 5, label: 'Tier 5 (Div 21-25)', range: 'Div 21-25', min: 21, max: 25 }
    ];

    const DEFAULT_PLAYOFFS = Object.freeze({
        teams: 0,
        matchesPlayed: 0,
        matchesTotal: 0,
        status: 'waiting',
        winner: null
    });

    function toNumber(value, fallback = 0) {
        if (value === null || value === undefined) {
            return fallback;
        }
        const direct = Number(value);
        if (Number.isFinite(direct)) {
            return direct;
        }
        const parsed = Number(String(value).replace(',', '.'));
        return Number.isFinite(parsed) ? parsed : fallback;
    }

    function clamp(value, min, max) {
        const numeric = toNumber(value, min);
        if (!Number.isFinite(numeric)) {
            return min;
        }
        return Math.max(min, Math.min(max, numeric));
    }

    function inferTier(divisionId) {
        const numeric = toNumber(divisionId, 0);
        const match = TIER_RANGES.find(entry => numeric >= entry.min && numeric <= entry.max);
        return match ? match.id : 5;
    }

    function cleanDivisionName(rawName) {
        if (!rawName) return '';
        // Remove season suffix like "S11", "S12", etc.
        return String(rawName).replace(/\s+S\d+$/i, '').trim();
    }

    function formatSeasonLabel(value) {
        if (value === null || value === undefined) return '';
        const text = String(value).trim();
        if (!text) return '';
        if (/^kausi\s+/i.test(text)) return text;
        if (/^s\d+/i.test(text)) return text.toUpperCase();
        return `Kausi ${text}`;
    }

    function normalizeDivisionName({ name, divisionNum }) {
        const rawName = cleanDivisionName(name);
        if (rawName && !isLikelyId(rawName)) return rawName;
        const numericDivision = toNumber(divisionNum, null);
        if (numericDivision === 0) return 'Mestaruussarja';
        if (numericDivision != null) return `${numericDivision} Divisioona`;
        return 'Divisioona';
    }

    function buildDivisionBreadcrumbMeta(input = {}) {
        const normalizedName = normalizeDivisionName({
            name: input.name,
            divisionNum: input.divisionNum
        });
        const seasonLabel = formatSeasonLabel(input.season);
        let label = seasonLabel ? `${normalizedName} (${seasonLabel})` : normalizedName;
        if (input.isPlayoffs && !/playoffs?/i.test(label)) {
            label = `${label} (Playoffs)`;
        }
        return {
            name: normalizedName,
            label
        };
    }

    function isLikelyId(value) {
        if (value === null || value === undefined) return false;
        const text = String(value).trim();
        if (!text) return false;
        if (/^\d+$/.test(text)) return true;
        return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
    }

    function slugifyDivisionName(value) {
        if (!value) return '';
        const base = String(value);
        const normalized = typeof base.normalize === 'function' ? base.normalize('NFD') : base;
        return normalized
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9]+/g, '-')
            .replace(/^-+|-+$/g, '')
            .toLowerCase();
    }

    function getDivisionSlug(division) {
        if (!division || typeof division !== 'object') {
            return null;
        }
        const raw = division.raw && typeof division.raw === 'object' ? division.raw : division;
        const rawSlug = raw.slug || division.slug || null;
        const name = cleanDivisionName(raw.name || division.name || '');
        const derived = slugifyDivisionName(name);

        if (rawSlug && !isLikelyId(rawSlug)) {
            return String(rawSlug);
        }
        if (derived) {
            return derived;
        }
        return rawSlug || raw.division_id || raw.divisionId || raw.id || division.id || null;
    }

    function getDivisionHrefId(division) {
        if (!division || typeof division !== 'object') {
            return null;
        }
        return getDivisionSlug(division);
    }

    function getPlayoffsHrefId(division) {
        if (!division || typeof division !== 'object') {
            return null;
        }
        const raw = division.raw && typeof division.raw === 'object' ? division.raw : division;
        const playoffs = raw.playoffs && typeof raw.playoffs === 'object' ? raw.playoffs : division.playoffs || {};
        return (
            playoffs.playoff_championship_id ||
            playoffs.playoffChampionshipId ||
            playoffs.championship_id ||
            playoffs.championshipId ||
            null
        );
    }

    function hasPlayoffsStarted(division) {
        if (!division || typeof division !== 'object') {
            return false;
        }
        const raw = division.raw && typeof division.raw === 'object' ? division.raw : division;
        const playoffs = raw.playoffs && typeof raw.playoffs === 'object' ? raw.playoffs : division.playoffs || {};
        const matchesPlayed = toNumber(playoffs.matches_played ?? playoffs.matchesPlayed, 0);
        const status = String(playoffs.status || '').toLowerCase();
        return matchesPlayed > 0 || status === 'active' || status === 'finished';
    }

    function clampMatches(block) {
        const matchesTotal = Math.max(0, toNumber(block.matches_played_total ?? block.matches_total, 0));
        const rawPlayed = toNumber(block.matches_played, 0);
        const playedCap = matchesTotal > 0 ? matchesTotal : Math.max(rawPlayed, 0);
        const matchesPlayed = clamp(rawPlayed, 0, playedCap);
        return {
            ...block,
            matchesPlayed,
            matchesTotal
        };
    }

    function normalizeDivision(raw) {
        const warnings = [];
        if (!raw || typeof raw !== 'object') {
            return { ok: false, error: 'Division payload missing', warnings };
        }
        const divisionId =
            raw.division_id ??
            raw.divisionId ??
            raw.id ??
            raw.championship_id ??
            raw.championshipId;
        if (divisionId === undefined || divisionId === null) {
            warnings.push('division_id missing');
            return { ok: false, error: 'division_id missing', warnings };
        }
        const resolvedId = String(divisionId);
        const name = raw.name || `Division ${divisionId}`;
        const tierValue = toNumber(raw.tier, null);
        const tier = Number.isFinite(tierValue) ? tierValue : inferTier(divisionId);
        const seasonRaw = raw.season && typeof raw.season === 'object' ? raw.season : {};
        const playoffsRaw =
            raw.playoffs && typeof raw.playoffs === 'object'
                ? raw.playoffs
                : raw.playoff && typeof raw.playoff === 'object'
                    ? raw.playoff
                    : DEFAULT_PLAYOFFS;

        const normalizeStatus = (value, fallback = 'waiting') => {
            const normalized = String(value || '').toLowerCase();
            return ['waiting', 'active', 'finished'].includes(normalized) ? normalized : fallback;
        };

        const seasonStatus = normalizeStatus(seasonRaw.status || seasonRaw.state || raw.status, 'waiting');
        const playoffsStatus = normalizeStatus(playoffsRaw.status || raw.playoff_status, DEFAULT_PLAYOFFS.status);

        const normalizedSeason = clampMatches({
            teams: toNumber(seasonRaw.teams, 0),
            matches_played: toNumber(seasonRaw.matches_played ?? seasonRaw.matchesPlayed, 0),
            matches_total: toNumber(seasonRaw.matches_total ?? seasonRaw.matchesTotal, 0),
            status: seasonStatus,
            winner: seasonRaw.winner_team ? String(seasonRaw.winner_team) : null
        });

        const normalizedPlayoffs = clampMatches({
            teams: toNumber(playoffsRaw.teams, DEFAULT_PLAYOFFS.teams) || DEFAULT_PLAYOFFS.teams,
            matches_played: toNumber(
                playoffsRaw.matches_played ?? playoffsRaw.matchesPlayed,
                DEFAULT_PLAYOFFS.matchesPlayed
            ),
            matches_total:
                toNumber(playoffsRaw.matches_total ?? playoffsRaw.matchesTotal, DEFAULT_PLAYOFFS.matchesTotal) ||
                DEFAULT_PLAYOFFS.matchesTotal,
            status: playoffsStatus,
            winner: playoffsRaw.winner_team ? String(playoffsRaw.winner_team) : null
        });

        const metaData = raw.meta ?? {};
        const bestPlayer = metaData.best_player;
        const mvpTeam = metaData.winner_team;
        const winners = Array.isArray(raw.winners) ? raw.winners : [];

        // Calculate overall division status based on season and playoff status
        let overallStatus = raw.status ?? seasonStatus;
        if (overallStatus === 'finished' && playoffsStatus === 'active') {
            overallStatus = 'active'; // Season finished but playoffs ongoing
        }

        return {
            ok: true,
            warnings,
            division: {
                id: resolvedId,
                divisionId: toNumber(raw.division_id, null),
                name: String(name),
                tier,
                tierMeta: TIER_RANGES.find(entry => entry.id === tier) || TIER_RANGES[TIER_RANGES.length - 1],
                status: overallStatus,
                season: normalizedSeason,
                playoffs: normalizedPlayoffs,
                bestPlayer: bestPlayer ? {
                    name: bestPlayer.name,
                    kd: toNumber(bestPlayer.kd, 0)
                } : null,
                mvpTeam: mvpTeam ? String(mvpTeam) : null,
                winners: winners,
                slug: getDivisionSlug(raw),
                seasonNumber: raw.season_number ?? null,
                raw
            }
        };
    }

    window.divisionNormalizer = Object.freeze({
        normalizeDivision,
        inferTier,
        cleanDivisionName,
        formatSeasonLabel,
        normalizeDivisionName,
        buildDivisionBreadcrumbMeta,
        slugifyDivisionName,
        getDivisionSlug,
        getDivisionHrefId,
        getPlayoffsHrefId,
        hasPlayoffsStarted
    });
})();


/* === /static/utils/mapImages.js === */
(function () {
    const MapImageUtils = {
        mapKey(name) {
            if (!name) return null;
            return String(name).trim().toLowerCase();
        },
        mapKeys(...values) {
            const keys = new Set();
            values.forEach(value => {
                const key = this.mapKey(value);
                if (!key) return;
                keys.add(key);
                if (key.startsWith('de_')) {
                    const shortKey = key.slice(3);
                    if (shortKey) keys.add(shortKey);
                } else {
                    keys.add(`de_${key}`);
                }
            });
            return Array.from(keys);
        },
        extractMapImage(entry) {
            if (!entry) return null;
            const curr = entry.curr || {};
            return (
                entry.image_sm || entry.imageSm ||
                entry.image_lg || entry.imageLg ||
                entry.image_sm_url || entry.image_url || entry.image ||
                curr.image_sm || curr.image_lg || curr.image || curr.logo ||
                entry.logo || entry.thumbnail || null
            );
        },
        buildMapImageLookup(stats, existing = {}) {
            const lookup = { ...(existing || {}) };
            if (!Array.isArray(stats)) return lookup;
            stats.forEach(item => {
                const img = this.extractMapImage(item);
                if (!img) return;
                const keys = this.mapKeys(
                    item?.map_id,
                    item?.mapId,
                    item?.pretty_name,
                    item?.prettyName,
                    item?.map_name,
                    item?.mapName,
                    item?.name,
                    item?.map
                );
                keys.forEach(key => {
                    if (!lookup[key]) lookup[key] = img;
                });
            });
            return lookup;
        },
        resolveMapImage(entry, options = {}) {
            if (!entry) return null;
            const direct = this.extractMapImage(entry);
            const keys = this.mapKeys(
                entry.map_id,
                entry.mapId,
                entry.pretty_name,
                entry.prettyName,
                entry.map_name,
                entry.mapName,
                entry.name,
                entry.map
            );
            const lookup = options.mapImageLookup || null;
            const catalog = options.mapCatalog || null;
            let resolved = direct;

            if (!resolved && lookup && keys.length) {
                const lookupHit = keys.find(key => lookup[key]);
                if (lookupHit) {
                    resolved = lookup[lookupHit];
                }
            }

            if (!resolved && keys.length && Array.isArray(catalog)) {
                const match = catalog.find(item => {
                    const itemKeys = this.mapKeys(
                        item?.map_id,
                        item?.mapId,
                        item?.pretty_name,
                        item?.prettyName,
                        item?.map_name,
                        item?.mapName,
                        item?.name,
                        item?.map
                    );
                    return itemKeys.some(key => keys.includes(key));
                });
                resolved = this.extractMapImage(match);
            }

            if (!resolved) return null;

            try {
                const apiClient = options.apiClient || window.apiClient;
                return apiClient && typeof apiClient.proxyAvatar === 'function'
                    ? apiClient.proxyAvatar(resolved)
                    : resolved;
            } catch (error) {
                return resolved;
            }
        },
        shouldFetchCatalog(stats) {
            if (!Array.isArray(stats) || !stats.length) return false;
            return stats.some(item => {
                if (this.extractMapImage(item)) return false;
                return this.mapKeys(
                    item?.map_id,
                    item?.mapId,
                    item?.pretty_name,
                    item?.prettyName,
                    item?.map_name,
                    item?.mapName,
                    item?.name,
                    item?.map
                ).length > 0;
            });
        }
    };

    window.MapImageUtils = MapImageUtils;
})();


/* === /static/utils/mobile-utils.js === */
/**
 * Mobile utilities for Pappaliiga Stats
 * Handles scroll indicators, touch interactions, and responsive behavior
 */

window.MobileUtils = {
    /**
     * Detect if device is mobile/touch
     */
    isMobile() {
        return window.innerWidth <= 768;
    },

    isTouchDevice() {
        return ('ontouchstart' in window) || 
               (navigator.maxTouchPoints > 0) ||
               (navigator.msMaxTouchPoints > 0);
    },

    /**
     * Setup horizontal scroll indicators for table wrappers
     */
    setupScrollIndicators(container = document) {
        const wrappers = container.querySelectorAll('.table-wrapper');
        
        wrappers.forEach(wrapper => {
            // Check if table is scrollable
            const isScrollable = wrapper.scrollWidth > wrapper.clientWidth;
            
            if (isScrollable) {
                wrapper.setAttribute('data-scrollable', 'true');
                
                // Update shadow classes on scroll
                const updateScrollState = () => {
                    const scrollLeft = wrapper.scrollLeft;
                    const maxScroll = wrapper.scrollWidth - wrapper.clientWidth;
                    
                    // Remove scroll hint after first scroll
                    if (scrollLeft > 10) {
                        wrapper.classList.add('scrolled');
                    }
                    
                    // Update left/right shadow indicators
                    if (scrollLeft > 10) {
                        wrapper.classList.add('scrolled-left');
                    } else {
                        wrapper.classList.remove('scrolled-left');
                    }
                    
                    if (scrollLeft < maxScroll - 10) {
                        wrapper.classList.add('scrolled-right');
                    } else {
                        wrapper.classList.remove('scrolled-right');
                    }
                };
                
                // Initial state
                updateScrollState();
                
                // Listen to scroll events (throttled)
                let scrollTimeout;
                wrapper.addEventListener('scroll', () => {
                    if (scrollTimeout) {
                        window.cancelAnimationFrame(scrollTimeout);
                    }
                    scrollTimeout = window.requestAnimationFrame(updateScrollState);
                }, { passive: true });
                
                // Update on resize
                const resizeObserver = new ResizeObserver(updateScrollState);
                resizeObserver.observe(wrapper);
            } else {
                wrapper.removeAttribute('data-scrollable');
            }
        });
    },

    /**
     * Get visible columns based on screen size
     * Used by Vue components to filter columns
     */
    getVisibleColumns(allColumns, priority = 'default') {
        const width = window.innerWidth;
        
        if (width >= 1025) {
            // Desktop: show all
            return allColumns;
        } else if (width >= 641) {
            // Tablet: show important columns
            const importantGroups = ['map', 'combat', 'kills', 'rounds', 'usage', 'results', 'performance'];
            return allColumns.filter(col => 
                importantGroups.includes(col.group) || 
                col.key === 'mapName' ||
                col.key === 'nickname'
            );
        } else if (width >= 481) {
            // Small mobile: show essential columns
            const essentialKeys = ['mapName', 'nickname', 'kd', 'adr', 'kills', 'deaths', 'played', 'winrate'];
            return allColumns.filter(col => essentialKeys.includes(col.key));
        } else {
            // Extra small: minimal columns
            const minimalKeys = ['mapName', 'nickname', 'kd', 'adr', 'kills'];
            return allColumns.filter(col => minimalKeys.includes(col.key));
        }
    },

    /**
     * Setup responsive table behavior
     */
    makeTableResponsive(tableElement) {
        if (!tableElement) return;
        
        const wrapper = tableElement.closest('.table-wrapper');
        if (!wrapper) return;
        
        // Add data attributes to cells for mobile card view (future enhancement)
        const headers = Array.from(tableElement.querySelectorAll('thead th'));
        const rows = tableElement.querySelectorAll('tbody tr');
        
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            cells.forEach((cell, index) => {
                if (headers[index]) {
                    const label = headers[index].textContent.trim();
                    cell.setAttribute('data-label', label);
                }
            });
        });
    },

    /**
     * Lazy load images with Intersection Observer
     */
    setupLazyLoading(container = document) {
        if (!('IntersectionObserver' in window)) {
            // Fallback: load all images immediately
            const images = container.querySelectorAll('img[data-src]');
            images.forEach(img => {
                img.src = img.dataset.src;
                img.removeAttribute('data-src');
            });
            return;
        }

        const imageObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const img = entry.target;
                    if (img.dataset.src) {
                        img.src = img.dataset.src;
                        img.removeAttribute('data-src');
                    }
                    observer.unobserve(img);
                }
            });
        }, {
            rootMargin: '50px 0px',
            threshold: 0.01
        });

        const images = container.querySelectorAll('img[data-src]');
        images.forEach(img => imageObserver.observe(img));
    },

    /**
     * Add touch feedback to interactive elements
     */
    enhanceTouchFeedback(container = document) {
        const interactiveElements = container.querySelectorAll(
            '.clickable-row, .table-row, .btn-primary, .btn-secondary, .team-tab'
        );

        interactiveElements.forEach(element => {
            element.addEventListener('touchstart', function() {
                this.classList.add('touch-active');
            }, { passive: true });

            element.addEventListener('touchend', function() {
                this.classList.remove('touch-active');
            }, { passive: true });

            element.addEventListener('touchcancel', function() {
                this.classList.remove('touch-active');
            }, { passive: true });
        });
    },

    /**
     * Initialize all mobile utilities
     */
    init(container = document) {
        this.setupScrollIndicators(container);
        this.setupLazyLoading(container);
        
        if (this.isTouchDevice()) {
            this.enhanceTouchFeedback(container);
        }

        // Re-initialize on dynamic content changes
        const observer = new MutationObserver((mutations) => {
            let shouldReinit = false;
            mutations.forEach(mutation => {
                if (mutation.addedNodes.length > 0) {
                    shouldReinit = true;
                }
            });
            
            if (shouldReinit) {
                // Debounce reinit
                clearTimeout(this._reinitTimeout);
                this._reinitTimeout = setTimeout(() => {
                    this.setupScrollIndicators(container);
                }, 100);
            }
        });

        observer.observe(container, {
            childList: true,
            subtree: true
        });
    },

    /**
     * Get responsive grid columns count
     */
    getGridColumns(defaultCols) {
        const width = window.innerWidth;
        if (width < 481) return 1;
        if (width < 641) return Math.min(defaultCols, 2);
        if (width < 1025) return Math.min(defaultCols, 3);
        return defaultCols;
    }
};

// Auto-initialize when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        window.MobileUtils.init();
    });
} else {
    window.MobileUtils.init();
}


/* === /static/utils/matchLinks.js === */
(function () {
    function resolveMatchId(match) {
        if (!match || typeof match !== 'object') return null;
        const value = match.matchId ?? match.match_id ?? null;
        if (value === null || value === undefined || value === '') return null;
        return String(value);
    }

    function getFaceitRoomUrl(matchId) {
        if (matchId === null || matchId === undefined || matchId === '') return '';
        return `https://www.faceit.com/cs2/room/${matchId}`;
    }

    function collectInlineDemoUrls(match) {
        if (!match || typeof match !== 'object') return [];
        const urls = [];
        const addUrl = value => {
            if (value === null || value === undefined) return;
            const normalized = String(value).trim();
            if (!normalized) return;
            if (!/^https?:\/\//i.test(normalized)) return;
            urls.push(normalized);
        };

        const appendFromArray = items => {
            if (!Array.isArray(items)) return;
            items.forEach(item => {
                if (typeof item === 'string') {
                    addUrl(item);
                    return;
                }
                if (!item || typeof item !== 'object') return;
                addUrl(item.url || item.demo_url || item.demoUrl || item.download_url || item.downloadUrl || null);
            });
        };

        addUrl(match.demo_url || match.demoUrl || null);
        appendFromArray(match.demo_urls || match.demoUrls || match.demos || match.demo_links || match.demoLinks || []);

        const maps = Array.isArray(match.maps) ? match.maps : [];
        maps.forEach(map => {
            if (!map || typeof map !== 'object') return;
            addUrl(map.demo_url || map.demoUrl || map.download_url || map.downloadUrl || null);
            appendFromArray(map.demo_urls || map.demoUrls || map.demos || map.demo_links || map.demoLinks || []);
        });

        return Array.from(new Set(urls));
    }

    function extractInlineDemoLinks(match = null) {
        const urls = collectInlineDemoUrls(match);
        return urls.map((url, index) => ({
            demoIndex: index,
            exists: true,
            url
        }));
    }

    function extractAvailableDemoLinks(byMatch = {}, match = null) {
        const matchId = resolveMatchId(match);
        const hit = matchId ? (byMatch?.[matchId] || {}) : {};
        const resolved = Object.entries(hit)
            .map(([demoIndex, payload]) => ({
                demoIndex: Number(demoIndex),
                exists: !!payload?.exists,
                url: payload?.url || ''
            }))
            .filter(item => item.exists && item.url)
            .sort((a, b) => a.demoIndex - b.demoIndex);
        if (resolved.length > 0) {
            return resolved;
        }
        return extractInlineDemoLinks(match);
    }

    function buildDemoMatchRequests(matches = []) {
        if (!Array.isArray(matches)) return [];
        const out = [];
        matches.forEach(match => {
            if (!match || !match.played) return;
            const matchId = resolveMatchId(match);
            if (!matchId) return;
            const maps = Array.isArray(match.maps) ? match.maps : [];
            const mapsCount = maps.length;
            const bestOf = Number(match.bestOf ?? match.best_of ?? 0);
            const expectedCount = Math.max(mapsCount, Number.isFinite(bestOf) && bestOf > 0 ? bestOf : 0, 2);
            out.push({ matchId, expectedCount });
        });
        return out;
    }

    function mapDemoItemsToByIndex(items = []) {
        const byIndex = {};
        const sorted = [...(Array.isArray(items) ? items : [])]
            .map(item => ({
                sourceIndex: Number(item?.demo_index ?? item?.demoIndex ?? -1),
                url: String(item?.url || '')
            }))
            .filter(item => item.sourceIndex >= 0 && item.url)
            .sort((a, b) => a.sourceIndex - b.sourceIndex);

        sorted.forEach((item, visualIndex) => {
            byIndex[visualIndex] = {
                exists: true,
                url: item.url,
                sourceIndex: item.sourceIndex
            };
        });
        return byIndex;
    }

    async function fetchDemoLinksForMatch({
        apiClient,
        championshipId,
        matchId,
        expectedCount = null,
        forceRefresh = false,
        persistCache = false
    }) {
        if (!apiClient || typeof apiClient.getMatchDemos !== 'function') {
            return [];
        }
        if (!championshipId || !matchId) {
            return [];
        }

        try {
            const items = await apiClient.getMatchDemos({
                championshipId,
                matchId,
                expectedCount
            }, {
                persistCache,
                forceRefresh
            });
            return Array.isArray(items) ? items : [];
        } catch (_error) {
            return [];
        }
    }

    async function fetchDemoAvailabilityForMatch({
        apiClient,
        championshipId,
        matchId,
        mapsCount,
        existingByIndex = {},
        refreshFalse = false,
        forceRefresh = false,
        persistCache = false,
        onBackgroundResult = null
    }) {
        if (!apiClient) {
            return { ...(existingByIndex || {}) };
        }
        if (!championshipId || !matchId) {
            return { ...(existingByIndex || {}) };
        }

        const targetCount = Math.max(0, Number(mapsCount) || 0);
        const items = await fetchDemoLinksForMatch({
            apiClient,
            championshipId,
            matchId,
            expectedCount: targetCount || null,
            forceRefresh,
            persistCache
        });
        let mapped = mapDemoItemsToByIndex(items);

        const hasMapped = Object.keys(mapped).length > 0;
        if (hasMapped) {
            return mapped;
        }
        if (refreshFalse) {
            return { ...(existingByIndex || {}) };
        }
        return mapped;
    }

    window.MatchLinksUtils = {
        resolveMatchId,
        getFaceitRoomUrl,
        extractInlineDemoLinks,
        extractAvailableDemoLinks,
        buildDemoMatchRequests,
        fetchDemoLinksForMatch,
        fetchDemoAvailabilityForMatch
    };
})();


/* === /static/stores/useSeasonsStore.js === */
(function () {
    const { defineStore } = Pinia;

    const STATUS_ARCHIVE_PATTERN = /(archive|finished|complete|closed|done|past|ended|final)/i;
    const STATUS_ACTIVE_PATTERN = /(active|ongoing|current|live|running|progress)/i;

    function toNumber(value, fallback = null) {
        if (value === null || value === undefined) {
            return fallback;
        }
        const numeric = Number(value);
        if (Number.isFinite(numeric)) {
            return numeric;
        }
        const coerced = Number(String(value).replace(',', '.'));
        return Number.isFinite(coerced) ? coerced : fallback;
    }

    function normalizeSeason(raw, index) {
        if (!raw || typeof raw !== 'object') {
            return null;
        }

        const fallbackKey = `season-${index}`;
        const slug = raw.slug || raw.season_slug || raw.seasonSlug || raw.code;
        const identifier = raw.id ?? raw.championship_id ?? raw.championshipId ?? raw.season_id ?? raw.seasonId;
        const numberish = raw.season ?? raw.year ?? raw.number ?? raw.ordinal ?? raw.index;
        const label =
            raw.name ||
            raw.display_name ||
            raw.title ||
            (numberish != null ? `Season ${numberish}` : null) ||
            (slug ? `Season ${slug}` : `Season ${index + 1}`);

        const keySource = raw.key ?? raw.uid ?? slug ?? identifier ?? numberish ?? fallbackKey;
        const key = keySource != null ? String(keySource) : fallbackKey;

        const status = (raw.status || raw.state || '').toString().toLowerCase();
        const classification = (raw.classification || '').toString().toLowerCase();

        const isCurrent = Boolean(raw.is_current || raw.current || raw.isCurrent);
        const activeFlag = raw.is_active ?? raw.active ?? raw.isActive ?? null;
        const archivedFlag = raw.is_archived ?? raw.archived ?? raw.isArchived ?? null;

        const inferredArchived =
            archivedFlag != null ? Boolean(archivedFlag) : STATUS_ARCHIVE_PATTERN.test(status) || STATUS_ARCHIVE_PATTERN.test(classification);
        const inferredActive =
            activeFlag != null
                ? Boolean(activeFlag)
                : isCurrent || STATUS_ACTIVE_PATTERN.test(status) || STATUS_ACTIVE_PATTERN.test(classification);

        const isArchived = inferredArchived && !isCurrent;
        const isActive = inferredActive && !isArchived;
        const category = isArchived ? 'archived' : 'active';
        const isPlayoff = Boolean(raw.is_playoff || raw.phase === 'playoffs' || raw.stage === 'playoffs');

        const apiParam = raw.api_param ?? raw.apiParam ?? slug ?? identifier ?? numberish ?? key;
        const seasonId = toNumber(raw.id ?? identifier ?? numberish, null);
        const seasonNumber =
            typeof numberish === 'number'
                ? numberish
                : Number(numberish != null ? String(numberish).replace(',', '.') : Number.NaN);
        const shortLabelSource = raw.short_name || raw.abbreviation || raw.code;
        const derivedShort = Number.isFinite(seasonNumber) ? `S${seasonNumber}` : seasonId != null ? `S${seasonId}` : null;

        return {
            key,
            label,
            id: seasonId,
            shortLabel: shortLabelSource || derivedShort || label,
            seasonNumber: Number.isFinite(seasonNumber) ? seasonNumber : null,
            status,
            category,
            isActive,
            isArchived,
            isCurrent,
            isPlayoff,
            phase: raw.phase || raw.stage || (isPlayoff ? 'Playoffs' : null),
            startsAt: raw.starts_at || raw.start_at || raw.start_date || raw.startDate || null,
            endsAt: raw.ends_at || raw.end_at || raw.end_date || raw.endDate || null,
            apiParam: apiParam != null ? apiParam : key,
            raw
        };
    }

    window.useSeasonsStore = defineStore('seasons', {
        state: () => ({
            seasons: [],
            loading: false,
            error: null,
            fetchedAt: null,
            selectedSeasonKey: null
        }),
        getters: {
            sortedSeasons(state) {
                return [...state.seasons].sort((a, b) => {
                    const aId = Number.isFinite(a.id) ? a.id : Number.NEGATIVE_INFINITY;
                    const bId = Number.isFinite(b.id) ? b.id : Number.NEGATIVE_INFINITY;
                    if (aId !== bId) {
                        return bId - aId;
                    }
                    const aVal = a.seasonNumber ?? Number.NEGATIVE_INFINITY;
                    const bVal = b.seasonNumber ?? Number.NEGATIVE_INFINITY;
                    if (Number.isFinite(aVal) && Number.isFinite(bVal) && aVal !== bVal) {
                        return bVal - aVal;
                    }
                    return a.label.localeCompare(b.label, 'fi');
                });
            },
            currentSeason(state) {
                return state.seasons.find(season => season.isCurrent) || null;
            },
            newestSeason(state) {
                return state.seasons.reduce((latest, season) => {
                    if (!season) return latest;
                    if (!latest) return season;
                    const latestId = Number.isFinite(latest.id) ? latest.id : Number.NEGATIVE_INFINITY;
                    const currentId = Number.isFinite(season.id) ? season.id : Number.NEGATIVE_INFINITY;
                    if (currentId !== latestId) {
                        return currentId > latestId ? season : latest;
                    }
                    const latestNumber = Number.isFinite(latest.seasonNumber) ? latest.seasonNumber : Number.NEGATIVE_INFINITY;
                    const currentNumber = Number.isFinite(season.seasonNumber) ? season.seasonNumber : Number.NEGATIVE_INFINITY;
                    return currentNumber > latestNumber ? season : latest;
                }, null);
            },
            latestSeasonKey(state) {
                const newest = this.newestSeason;
                return newest ? newest.key : null;
            },
            selectedSeason(state) {
                return state.seasons.find(season => season.key === state.selectedSeasonKey) || null;
            },
            getSeasonByKey: state => key => state.seasons.find(season => season.key === key) || null,
            getSeasonById: state => id => {
                if (id === undefined || id === null) return null;
                const numeric = Number(id);
                const target = String(id);
                return (
                    state.seasons.find(season => {
                        if (!season) return false;
                        if (String(season.key) === target) return true;
                        if (season.apiParam != null && String(season.apiParam) === target) return true;
                        if (Number.isFinite(numeric) && Number.isFinite(season.id) && season.id === numeric) return true;
                        if (Number.isFinite(numeric) && Number.isFinite(season.seasonNumber) && season.seasonNumber === numeric) return true;
                        return false;
                    }) || null
                );
            },
            hasData(state) {
                return state.seasons.length > 0;
            }
        },
        actions: {
            async fetchSeasons(options = {}) {
                const { force = false } = options;

                if (this.loading) {
                    return this.seasons;
                }

                const isFresh = this.fetchedAt && Date.now() - this.fetchedAt < 5 * 60 * 1000;
                if (!force && this.seasons.length && isFresh) {
                    return this.seasons;
                }

                this.loading = true;
                this.error = null;

                try {
                    const payload = await window.apiClient.getSeasons();
                    const normalized = Array.isArray(payload)
                        ? payload.map((season, index) => normalizeSeason(season, index)).filter(Boolean)
                        : [];

                    normalized.sort((a, b) => {
                        const aId = Number.isFinite(a.id) ? a.id : Number.NEGATIVE_INFINITY;
                        const bId = Number.isFinite(b.id) ? b.id : Number.NEGATIVE_INFINITY;
                        if (aId !== bId) {
                            return bId - aId;
                        }
                        const aVal = a.seasonNumber ?? Number.NEGATIVE_INFINITY;
                        const bVal = b.seasonNumber ?? Number.NEGATIVE_INFINITY;
                        if (Number.isFinite(aVal) && Number.isFinite(bVal) && aVal !== bVal) {
                            return bVal - aVal;
                        }
                        return a.label.localeCompare(b.label, 'fi');
                    });

                    this.seasons = normalized;
                    this.fetchedAt = Date.now();

                    if (!this.selectedSeasonKey && normalized.length) {
                        this.selectedSeasonKey = normalized[0].key;
                    } else if (this.selectedSeasonKey) {
                        const found = normalized.some(season => season.key === this.selectedSeasonKey);
                        if (!found && normalized.length) {
                            this.selectedSeasonKey = normalized[0].key;
                        }
                    }
                    return this.seasons;
                } catch (error) {
                    console.error('[seasonsStore] fetchSeasons failed', error);
                    this.error = error?.message || 'Kausilistan lataus epäonnistui';
                    throw error;
                } finally {
                    this.loading = false;
                }
            },
            selectSeason(key) {
                if (!key) return;
                this.selectedSeasonKey = key;
            },
            ensureSelectedSeason() {
                if (this.selectedSeasonKey && this.seasons.some(entry => entry.key === this.selectedSeasonKey)) {
                    return this.selectedSeasonKey;
                }
                const fallback = this.seasons[0];
                if (fallback) {
                    this.selectedSeasonKey = fallback.key;
                    return fallback.key;
                }
                return null;
            },
            clear() {
                this.seasons = [];
                this.loading = false;
                this.error = null;
                this.fetchedAt = null;
                this.selectedSeasonKey = null;
            },
            seedSeasons(rawArray) {
                if (!Array.isArray(rawArray) || !rawArray.length || this.seasons.length) return;
                const normalized = rawArray
                    .map((season, index) => normalizeSeason(season, index))
                    .filter(Boolean);
                normalized.sort((a, b) => {
                    const aId = Number.isFinite(a.id) ? a.id : Number.NEGATIVE_INFINITY;
                    const bId = Number.isFinite(b.id) ? b.id : Number.NEGATIVE_INFINITY;
                    if (aId !== bId) return bId - aId;
                    const aVal = a.seasonNumber ?? Number.NEGATIVE_INFINITY;
                    const bVal = b.seasonNumber ?? Number.NEGATIVE_INFINITY;
                    if (Number.isFinite(aVal) && Number.isFinite(bVal) && aVal !== bVal) return bVal - aVal;
                    return a.label.localeCompare(b.label, 'fi');
                });
                this.seasons = normalized;
                this.fetchedAt = Date.now();
                if (!this.selectedSeasonKey && normalized.length) {
                    this.selectedSeasonKey = normalized[0].key;
                }
            }
        }
    });
})();



/* === /static/stores/useHomeStore.js === */
(function () {
    const { defineStore } = Pinia;
    const DEV_MODE = typeof window !== 'undefined' && ['localhost', '127.0.0.1'].includes(window.location.hostname);
    const DEV_MOCK_DATA = typeof window !== 'undefined' ? window.__PAPPALIIGA_DEV_DIVISIONS__ : null;

    function formatCacheBanner(timestamp) {
        if (!timestamp) {
            return 'Backend routes not found; showing cached data.';
        }
        try {
            const formatted = new Date(timestamp).toLocaleString('fi-FI', {
                hour: '2-digit',
                minute: '2-digit',
                day: 'numeric',
                month: 'numeric',
                year: 'numeric'
            });
            return `Backend routes not found; showing cached data from ${formatted}.`;
        } catch (error) {
            return `Backend routes not found; showing cached data (timestamp: ${timestamp}).`;
        }
    }

    function toNumber(value, fallback = 0) {
        if (value === null || value === undefined) {
            return fallback;
        }
        const direct = Number(value);
        if (Number.isFinite(direct)) {
            return direct;
        }
        const parsed = Number(String(value).replace(',', '.'));
        return Number.isFinite(parsed) ? parsed : fallback;
    }

    function pickValue(obj, candidates) {
        if (!obj) return undefined;
        const paths = Array.isArray(candidates) ? candidates : [candidates];
        for (const path of paths) {
            if (!path) continue;
            const segments = String(path).split('.');
            let current = obj;
            let found = true;
            for (const segment of segments) {
                if (current && Object.prototype.hasOwnProperty.call(current, segment)) {
                    current = current[segment];
                } else {
                    found = false;
                    break;
                }
            }
            if (found && current !== undefined) {
                return current;
            }
        }
        return undefined;
    }

    function pickNumeric(obj, candidates) {
        if (!obj) return null;
        const raw = pickValue(obj, candidates);
        const numeric = toNumber(raw, null);
        return Number.isFinite(numeric) ? numeric : null;
    }

    const PLAYOFF_SERIES_MATCH_TOTAL = 7;

    function normalizeMatchPair(playedInput, totalInput, options = {}) {
        const { fallbackTotal = null, forceTotal = null } = options;
        const providedTotal = Math.max(0, toNumber(totalInput, 0));
        let total = providedTotal;
        let estimated = false;
        if (Number.isFinite(forceTotal) && forceTotal >= 0) {
            total = forceTotal;
            estimated = true;
        } else {
            const fallbackNumeric = Math.max(0, toNumber(fallbackTotal, 0));
            if (total <= 0 && fallbackNumeric > 0) {
                total = fallbackNumeric;
                estimated = true;
            }
        }
        const playedRaw = Math.max(0, toNumber(playedInput, 0));
        const cap = total > 0 ? total : playedRaw;
        const played = cap > 0 ? Math.min(playedRaw, cap) : playedRaw;
        return {
            played,
            total,
            effectiveTotal: total > 0 ? total : played,
            estimated
        };
    }

    function aggregateDivisionMatches(divisions, blockKey, options = {}) {
        const { estimateTotal, forceTotal } = options;
        if (!Array.isArray(divisions) || !divisions.length) {
            return { played: 0, total: 0, effectiveTotal: 0, estimatedTotal: 0 };
        }
        return divisions.reduce(
            (acc, division) => {
                const block = division?.[blockKey];
                if (!block) {
                    return acc;
                }
                const matches = normalizeMatchPair(
                    block.matches_played ?? block.matchesPlayed,
                    block.matches_total ?? block.matchesTotal,
                    {
                        fallbackTotal:
                            typeof estimateTotal === 'function' ? estimateTotal(block, division) : null,
                        forceTotal: forceTotal
                    }
                );
                acc.played += matches.played;
                acc.total += matches.total;
                acc.effectiveTotal += matches.effectiveTotal;
                acc.estimatedTotal += matches.estimated ? matches.total : 0;
                return acc;
            },
            { played: 0, total: 0, effectiveTotal: 0, estimatedTotal: 0 }
        );
    }

    function computePercent(part, total) {
        const played = toNumber(part);
        const max = toNumber(total);
        if (!max || max <= 0) return 0;
        return Math.min(100, Math.round((played / max) * 1000) / 10);
    }

    function createProgressSection() {
        return { played: 0, total: 0, percent: 0, source: 'unknown' };
    }

    function defaultProgress() {
        return {
            overall: createProgressSection(),
            regular: createProgressSection(),
            playoffs: createProgressSection()
        };
    }

    function computeProgress(stats, divisions) {
        const source = stats || {};
        const regularAggregate = aggregateDivisionMatches(divisions, 'season');
        const playoffAggregate = aggregateDivisionMatches(divisions, 'playoffs', {
            forceTotal: PLAYOFF_SERIES_MATCH_TOTAL
        });
        const forcedPlayoffTotal = divisions.length * PLAYOFF_SERIES_MATCH_TOTAL;
        if (forcedPlayoffTotal > 0) {
            playoffAggregate.total = forcedPlayoffTotal;
            if (playoffAggregate.effectiveTotal < forcedPlayoffTotal) {
                playoffAggregate.effectiveTotal = forcedPlayoffTotal;
            }
            playoffAggregate.estimatedTotal = forcedPlayoffTotal;
        }

        const overallAggregate = {
            played: regularAggregate.played + playoffAggregate.played,
            total: regularAggregate.total + playoffAggregate.total,
            effectiveTotal: regularAggregate.effectiveTotal + playoffAggregate.effectiveTotal,
            estimatedTotal: (regularAggregate.estimatedTotal || 0) + (playoffAggregate.estimatedTotal || 0)
        };

        const statsRegular = {
            played: pickNumeric(source, [
                'progress.regular_matches_played',
                'progress.regular.played',
                'progress.runkosarja.played',
                'progress.regular_played'
            ]),
            total: pickNumeric(source, [
                'progress.regular_matches_total',
                'progress.regular.total',
                'progress.runkosarja.total',
                'progress.regular_total'
            ])
        };
        const statsPlayoffs = {
            played: pickNumeric(source, [
                'progress.playoff_matches_played',
                'progress.playoffs.played',
                'progress.playoff.played'
            ]),
            total: pickNumeric(source, [
                'progress.playoff_matches_total',
                'progress.playoffs.total',
                'progress.playoff.total'
            ])
        };
        if (forcedPlayoffTotal > 0) {
            statsPlayoffs.total = forcedPlayoffTotal;
        }
        const statsOverall = {
            played: pickNumeric(source, [
                'progress.overall_matches_played',
                'progress.overall.played',
                'matches_played',
                'played_matches'
            ]),
            total: pickNumeric(source, [
                'progress.overall_matches_total',
                'progress.overall.total',
                'matches_total',
                'scheduled_matches'
            ])
        };
        const regularTargetTotal = Number.isFinite(statsRegular.total)
            ? statsRegular.total
            : regularAggregate.total;
        const forcedOverallTotal = Math.max(0, regularTargetTotal) + Math.max(0, forcedPlayoffTotal);
        if (forcedOverallTotal > 0) {
            statsOverall.total = forcedOverallTotal;
        }

        function finalizeSection(statsSection, aggregateSection) {
            const hasStatsPlayed = Number.isFinite(statsSection.played);
            const hasStatsTotal = Number.isFinite(statsSection.total);
            const played = hasStatsPlayed ? statsSection.played : aggregateSection.played;
            const rawTotal = hasStatsTotal ? statsSection.total : aggregateSection.total;
            const fallbackTotal =
                rawTotal > 0
                    ? rawTotal
                    : hasStatsPlayed
                        ? played
                        : aggregateSection.effectiveTotal;
            const total = Math.max(0, fallbackTotal);
            const usedEstimate = aggregateSection.estimatedTotal > 0;
            let sourceLabel = 'derived';
            if (hasStatsPlayed && hasStatsTotal) {
                sourceLabel = 'stats';
            } else if (hasStatsPlayed || hasStatsTotal) {
                sourceLabel = 'mixed';
            } else if (usedEstimate) {
                sourceLabel = 'estimated';
            }
            return {
                played,
                total,
                percent: computePercent(played, total),
                source: sourceLabel
            };
        }

        return {
            regular: finalizeSection(statsRegular, regularAggregate),
            playoffs: finalizeSection(statsPlayoffs, playoffAggregate),
            overall: finalizeSection(statsOverall, overallAggregate)
        };
    }

    function inferTierValue(divisionId) {
        const numeric = toNumber(divisionId, 0);
        if (numeric >= 1 && numeric <= 5) return 1;
        if (numeric >= 6 && numeric <= 10) return 2;
        if (numeric >= 11 && numeric <= 15) return 3;
        if (numeric >= 16 && numeric <= 20) return 4;
        return 5;
    }

    const normalizerRef = typeof window !== 'undefined' ? window.divisionNormalizer : null;

    function getCacheDebugKeys() {
        if (typeof window === 'undefined' || !window.localStorage) {
            return [];
        }
        const keys = [];
        try {
            for (let i = 0; i < window.localStorage.length; i += 1) {
                const key = window.localStorage.key(i);
                if (key && key.startsWith('pl:cache')) {
                    keys.push(key);
                }
            }
        } catch (error) {
            // ignore cache key issues
        }
        return keys;
    }

    function normalizeDivisionEntry(raw, index) {
        const warnings = [];
        if (!normalizerRef || typeof normalizerRef.normalizeDivision !== 'function') {
            warnings.push('Division normalizer unavailable.');
            return { ok: false, division: null, warnings };
        }
        try {
            const result = normalizerRef.normalizeDivision(raw);
            if (Array.isArray(result?.warnings) && result.warnings.length) {
                warnings.push(...result.warnings);
            }
            if (result && result.division) {
                return { ok: result.ok !== false, division: result.division, warnings };
            }
            if (result?.error) {
                warnings.push(result.error);
            } else {
                warnings.push('Division normalizer returned no data.');
            }
        } catch (error) {
            warnings.push(error?.message || 'Normalization error');
        }
        warnings.push('Normalization failed');
        return { ok: false, division: null, warnings };
    }

    function normalizeDivisionCollection(source) {
        if (!Array.isArray(source) || !source.length) {
            return { divisions: [], warnings: [] };
        }
        const warnings = [];
        const mapped = source
            .map((entry, index) => {
                const result = normalizeDivisionEntry(entry, index);
                if (Array.isArray(result.warnings) && result.warnings.length) {
                    warnings.push(...result.warnings);
                }
                return result.division;
            })
            .filter(Boolean);
        return { divisions: mapped, warnings };
    }

    function metricsToTotals(metrics) {
        if (!Array.isArray(metrics) || !metrics.length) {
            return null;
        }
        return metrics.reduce((acc, metric) => {
            if (metric && metric.id) {
                acc[metric.id] = Number(metric.value) || 0;
            }
            return acc;
        }, {});
    }

    function normalizeSummary(raw) {
        if (!raw || typeof raw !== 'object') {
            return { raw: null, aggregates: {} };
        }
        const summaryTotals =
            raw.summary_totals ||
            raw.summaryTotals ||
            raw.totals ||
            metricsToTotals(raw.metrics);
        if (summaryTotals) {
            const aggregates = {
                ...raw,
                summary_totals: summaryTotals,
                summaryTotals,
                totals: raw.totals || summaryTotals
            };
            Object.entries(summaryTotals).forEach(([key, value]) => {
                if (aggregates[key] === undefined) {
                    aggregates[key] = value;
                }
            });
            return { raw, aggregates };
        }
        const aggregates =
            raw.aggregates ||
            raw.stats ||
            raw.summary ||
            raw.overview ||
            raw;
        return { raw, aggregates };
    }

    function defaultSeasonState() {
        return {
            loading: false,
            error: null,
            apiParam: null,
            fetchedAt: null,
            stats: {},
            rawStats: null,
            divisions: [],
            rawDivisions: [],
            divisionsMeta: null,
            progress: defaultProgress(),
            offline: false,
            cacheTimestamp: null,
            validationWarnings: [],
            warningMessage: '',
            usingCache: false,
            bannerMessage: '',
            dataBadge: '',
            health: { ok: true, probableRoute: false, route: null }
        };
    }

    window.useHomeStore = defineStore('home', {
        state: () => ({
            lifetimeSummary: null,
            summaryLoading: false,
            summaryError: null,
            summaryFetchedAt: null,
            seasonCache: {}
        }),
        getters: {
            hasSummary(state) {
                return Boolean(state.lifetimeSummary && Object.keys(state.lifetimeSummary).length);
            },
            getSeasonState: state => key => state.seasonCache[key] || defaultSeasonState()
        },
        actions: {
            async fetchLifetimeSummary(options = {}) {
                const { force = false } = options;
                if (this.summaryLoading) {
                    return this.lifetimeSummary;
                }

                const isFresh =
                    this.summaryFetchedAt && Date.now() - this.summaryFetchedAt < 10 * 60 * 1000;
                if (!force && this.lifetimeSummary && isFresh) {
                    return this.lifetimeSummary;
                }

                this.summaryLoading = true;
                this.summaryError = null;

                try {
                    const summaryResponse = await window.apiClient.fetchLifetimeSummary();
                    const summary = summaryResponse?.data ?? summaryResponse;
                    this.lifetimeSummary = normalizeSummary(summary);
                    this.summaryFetchedAt = Date.now();
                    return this.lifetimeSummary;
                } catch (error) {
                    this.summaryError =
                        error?.message || 'Yleistilastojen lataus epäonnistui';
                    throw error;
                } finally {
                    this.summaryLoading = false;
                }
            },
            async ensureSummary() {
                if (!this.hasSummary) {
                    try {
                        await this.fetchLifetimeSummary();
                    } catch (error) {
                        // Swallow here; caller may render error state via summaryError
                    }
                }
            },
            async fetchSeason(key, options = {}) {
                if (!key) {
                    return defaultSeasonState();
                }

                const { force = false, apiParam } = options;
                const existing = this.seasonCache[key];

                if (existing && existing.loading) {
                    return existing;
                }

                const isFresh =
                    existing && existing.fetchedAt && Date.now() - existing.fetchedAt < 2 * 60 * 1000;
                if (existing && !force && isFresh && !existing.error) {
                    return existing;
                }

                const identifier = apiParam ?? existing?.apiParam ?? key;

                this.seasonCache[key] = {
                    ...(existing || defaultSeasonState()),
                    loading: true,
                    error: null,
                    apiParam: identifier
                };

                try {
                    const homeResult = await window.apiClient.getHomePage(identifier);
                    const homeData = homeResult?.data ?? homeResult ?? {};

                    const healthOk = Boolean(homeData.ok !== false);

                    let summaryData = homeData.summary || {};
                    let summaryMeta = homeResult?.meta || {};
                    const normalizedSummary = normalizeSummary(summaryData);
                    const normalizedStats = normalizedSummary.aggregates || {};
                    const normalizedRaw = normalizedSummary.raw;

                    // Populate lifetime summary from bundle so ensureSummary() skips a separate fetch
                    if (homeData.lifetime_summary && !this.lifetimeSummary) {
                        this.lifetimeSummary = normalizeSummary(homeData.lifetime_summary);
                        this.summaryFetchedAt = Date.now();
                    }

                    let divisionsData = Array.isArray(homeData.divisions) ? homeData.divisions : [];
                    let divisionsMeta = homeResult?.meta || {};
                    let apiValidationWarnings = [];

                    if (divisionsData.length === 0 && DEV_MODE) {
                        console.warn('[homeStore] Divisions API returned 0 items', {
                            meta: divisionsMeta,
                            cacheKeys: getCacheDebugKeys()
                        });
                    }

                    const { divisions: normalizedDivisionsFromApi, warnings: normalizationWarningsRaw } = normalizeDivisionCollection(divisionsData);
                    const normalizationWarnings = [...apiValidationWarnings, ...normalizationWarningsRaw];
                    const rawCount = Array.isArray(divisionsData) ? divisionsData.length : 0;
                    const normalizedCount = normalizedDivisionsFromApi.length;

                    let finalDivisions = normalizedDivisionsFromApi;
                    let finalRawDivisions = divisionsData;
                    let dataBadge = '';
                    let bannerMessage = '';
                    let usingCache = Boolean(summaryMeta?.usedCacheDueToError || divisionsMeta?.usedCacheDueToError);
                    let cacheTimestamp = summaryMeta?.cacheTimestamp || divisionsMeta?.cacheTimestamp || null;
                    let resolvedPathLabel = divisionsMeta?.resolvedPath || 'unresolved';

                    const finalCount = finalDivisions.length;
                    const stats = normalizedStats;
                    const progress = computeProgress(stats, finalDivisions);
                    const offline = !healthOk || usingCache || Boolean(bannerMessage);
                    divisionsMeta = { ...(divisionsMeta || {}), resolvedPath: resolvedPathLabel };

                    const payload = {
                        loading: false,
                        error: null,
                        apiParam: identifier,
                        fetchedAt: Date.now(),
                        stats,
                        rawStats: normalizedRaw,
                        rawDivisions: finalRawDivisions,
                        divisionsMeta,
                        divisions: finalDivisions,
                        progress,
                        offline,
                        cacheTimestamp,
                        usingCache,
                        validationWarnings: normalizationWarnings,
                        warningMessage: finalDivisions.length ? '' : 'Division data missing or invalid.',
                        bannerMessage,
                        dataBadge,
                        health: { ok: healthOk, probableRoute: false, route: null }
                    };

                    this.seasonCache[key] = payload;
                    return payload;
                } catch (error) {
                    this.seasonCache[key] = {
                        ...(this.seasonCache[key] || defaultSeasonState()),
                        loading: false,
                        error: error?.message || 'Kausitietojen lataus epäonnistui',
                        fetchedAt: Date.now(),
                        apiParam: identifier
                    };
                    throw error;
                }
            },
            clearSeasonCache(keys) {
                if (!keys) {
                    this.seasonCache = {};
                    return;
                }
                const list = Array.isArray(keys) ? keys : [keys];
                list.forEach(key => {
                    delete this.seasonCache[key];
                });
            }
        }
    });
})();


/* === /static/stores/useDivisionStore.js === */
(function () {
    const { defineStore } = Pinia;

    const FRESH_MS = 5 * 60 * 1000;
    const DEFAULT_TEAM_LOGO = window.PAPPALIIGA_DEFAULT_LOGO;

    function now() {
        return Date.now();
    }

    function isFresh(entry) {
        return !!(entry && entry.fetchedAt && now() - entry.fetchedAt < FRESH_MS && !entry.error);
    }

    function createSegment() {
        return {
            data: null,
            loading: false,
            error: null,
            fetchedAt: null
        };
    }

    function createEntry() {
        return {
            details: createSegment(),
            standings: createSegment(),
            maps: createSegment(),
            highlights: createSegment(),
            rawMatches: createSegment()
        };
    }

    function ensureAvatar(url) {
        if (!url) return DEFAULT_TEAM_LOGO;
        try {
            const resolved = window.apiClient.proxyAvatar(url);
            return resolved || DEFAULT_TEAM_LOGO;
        } catch (error) {
            return DEFAULT_TEAM_LOGO;
        }
    }

    function toNumber(value, fallback = 0) {
        if (value === null || value === undefined) {
            return fallback;
        }
        const direct = Number(value);
        if (Number.isFinite(direct)) {
            return direct;
        }
        const parsed = Number(String(value).replace(',', '.'));
        return Number.isFinite(parsed) ? parsed : fallback;
    }

    function percent(part, total) {
        const played = toNumber(part);
        const max = toNumber(total);
        if (!max) return 0;
        return Math.round((played / max) * 1000) / 10;
    }

    function deriveStandingsFromMatches(matches, teams = [], championshipId = null) {
        if (!Array.isArray(matches) || !matches.length) {
            return [];
        }
        const filtered = matches.filter(match => {
            if (!championshipId) return true;
            const matchChampId = match.championship_id || match.championshipId;
            return String(matchChampId || '') === String(championshipId);
        });
        if (!filtered.length) return [];

        const teamMeta = (teams || []).reduce((acc, team) => {
            if (!team?.team_id) return acc;
            acc[String(team.team_id)] = team;
            return acc;
        }, {});

        const table = new Map();
        function ensureTeam(id, fallbackName = 'Joukkue') {
            const key = String(id);
            if (!table.has(key)) {
                const meta = teamMeta[key] || {};
                table.set(key, {
                    id: key,
                    team_id: key,
                    name: meta.display_name || meta.team_name || fallbackName,
                    logo: ensureAvatar(meta.avatar || meta.logo || meta.team_logo),
                    wins: 0,
                    losses: 0,
                    matchesPlayed: 0,
                    matches_played: 0,
                    matches: 0,
                    roundDiff: toNumber(meta.rounds_diff ?? (meta.rounds_won ?? 0) - (meta.rounds_lost ?? 0)),
                    roundsWon: toNumber(meta.rounds_won ?? 0),
                    roundsLost: toNumber(meta.rounds_lost ?? 0),
                    kd: toNumber(meta.kd ?? 0),
                    adr: toNumber(meta.adr ?? 0),
                    points: toNumber(meta.points ?? 0),
                    raw: meta
                });
            }
            return table.get(key);
        }

        filtered.forEach(match => {
            const team1 = match.team1_id || match.team1Id;
            const team2 = match.team2_id || match.team2Id;
            if (!team1 || !team2) return;
            const t1Score = toNumber(match.team1_score ?? match.team1Score ?? match.score_team1 ?? 0);
            const t2Score = toNumber(match.team2_score ?? match.team2Score ?? match.score_team2 ?? 0);

            const entry1 = ensureTeam(team1, match.team1_name || match.team1Name || 'Joukkue 1');
            const entry2 = ensureTeam(team2, match.team2_name || match.team2Name || 'Joukkue 2');

            entry1.matchesPlayed += 1;
            entry2.matchesPlayed += 1;
            entry1.matches_played += 1;
            entry2.matches_played += 1;
            entry1.matches += 1;
            entry2.matches += 1;
            entry1.wins += t1Score;
            entry1.losses += t2Score;
            entry2.wins += t2Score;
            entry2.losses += t1Score;
        });

        const standings = Array.from(table.values()).map(row => ({
            ...row,
            winRate: percent(row.wins, row.wins + row.losses),
            winPct: percent(row.wins, row.wins + row.losses)
        }));

        standings.sort((a, b) => {
            if (b.wins !== a.wins) return b.wins - a.wins;
            if (b.roundDiff !== a.roundDiff) return b.roundDiff - a.roundDiff;
            if (b.winRate !== a.winRate) return b.winRate - a.winRate;
            return (a.name || '').localeCompare(b.name || '', 'fi');
        });

        return standings.map((row, idx) => ({
            ...row,
            rank: idx + 1
        }));
    }

    function deriveHighlights(details, standings) {
        if (!details || !Array.isArray(standings) || !standings.length) {
            return [];
        }
        const topTeam = standings[0];
        const clutchTeam = [...standings].sort((a, b) => b.roundDiff - a.roundDiff)[0];
        const kdAce = [...standings].sort((a, b) => b.kd - a.kd)[0];

        const highlights = [];
        if (topTeam) {
            highlights.push({
                id: 'top-team',
                title: 'Kärkipaikka',
                description: `${topTeam.name} johtaa sarjaa`,
                metric: `${topTeam.wins}-${topTeam.losses}`,
                tooltip: `Voitto-% ${topTeam.winPct} | Round diff ${topTeam.roundDiff >= 0 ? '+' : ''}${topTeam.roundDiff}`,
                team: topTeam
            });
        }
        if (clutchTeam && clutchTeam.id !== topTeam?.id) {
            highlights.push({
                id: 'round-diff',
                title: 'Roundi-ylivoima',
                description: `${clutchTeam.name} dominoi erissä`,
                metric: `${clutchTeam.roundDiff >= 0 ? '+' : ''}${clutchTeam.roundDiff}`,
                tooltip: `${clutchTeam.roundsWon} voitettua erää`,
                team: clutchTeam
            });
        }
        if (kdAce && kdAce.id !== topTeam?.id && kdAce.id !== clutchTeam?.id) {
            highlights.push({
                id: 'kd-ace',
                title: 'KD-kunkku',
                description: `${kdAce.name} pitää tapposuhteen kurissa`,
                metric: kdAce.kd.toFixed(2),
                tooltip: `ADR ${kdAce.adr}`,
                team: kdAce
            });
        }
        return highlights;
    }

    window.useDivisionStore = defineStore('division', {
        state: () => ({
            divisions: {}
        }),
        getters: {
            getDivisionState(state) {
                return id => {
                    if (!id) {
                        return createEntry();
                    }
                    return state.divisions[id] || createEntry();
                };
            }
        },
        actions: {
            ensureEntry(id) {
                if (!id) return createEntry();
                if (!this.divisions[id]) {
                    this.divisions[id] = createEntry();
                }
                return this.divisions[id];
            },
            async fetchDivisionDetails(id, options = {}) {
                if (!id) return null;
                const { force = false } = options;
                const entry = this.ensureEntry(id);
                if (entry.details.loading) {
                    return entry.details.data;
                }
                if (!force && isFresh(entry.details)) {
                    return entry.details.data;
                }
                entry.details.loading = true;
                entry.details.error = null;
                try {
                    const data = await window.apiClient.getDivisionById(id);
                    entry.details.data = data;
                    entry.details.fetchedAt = now();
                    entry.highlights.data = [];
                    entry.highlights.fetchedAt = now();
                    if (Array.isArray(data?.map_stats) && data.map_stats.length) {
                        entry.maps.data = data.map_stats;
                        entry.maps.fetchedAt = now();
                    }
                    return data;
                } catch (error) {
                    entry.details.error = error?.message || 'Divisioonan lataus epäonnistui';
                    throw error;
                } finally {
                    entry.details.loading = false;
                }
            },
            async fetchDivisionBundle(id, options = {}) {
                if (!id || !window.apiClient || typeof window.apiClient.getDivisionPage !== 'function') {
                    return this.fetchDivisionDetails(id, options);
                }
                const { force = false } = options;
                const entry = this.ensureEntry(id);
                if (!force && isFresh(entry.details) && isFresh(entry.rawMatches)) {
                    return entry.details.data;
                }
                entry.details.loading = true;
                entry.rawMatches.loading = true;
                entry.details.error = null;
                entry.rawMatches.error = null;
                try {
                    const bundle = await window.apiClient.getDivisionPage(id);
                    const data = bundle.details || {};
                    if (bundle.bracket != null) {
                        data.bracket = bundle.bracket;
                    }
                    entry.details.data = data;
                    entry.details.fetchedAt = now();
                    entry.details.loading = false;
                    entry.highlights.data = [];
                    entry.highlights.fetchedAt = now();
                    if (Array.isArray(data?.map_stats) && data.map_stats.length) {
                        entry.maps.data = data.map_stats;
                        entry.maps.fetchedAt = now();
                    }
                    const matches = Array.isArray(bundle.matches) ? bundle.matches : [];
                    entry.rawMatches.data = matches;
                    entry.rawMatches.fetchedAt = now();
                    entry.rawMatches.loading = false;
                    return data;
                } catch (error) {
                    entry.details.error = error?.message || 'Divisioonan lataus epäonnistui';
                    entry.rawMatches.error = error?.message || 'Ottelijoiden lataus epäonnistui';
                    throw error;
                } finally {
                    entry.details.loading = false;
                    entry.rawMatches.loading = false;
                }
            },
            async fetchDivisionStandings(id, options = {}) {
                if (!id) return [];
                const { force = false } = options;
                const entry = this.ensureEntry(id);
                if (entry.standings.loading) {
                    return entry.standings.data || [];
                }
                if (!force && isFresh(entry.standings)) {
                    return entry.standings.data || [];
                }
                entry.standings.loading = true;
                entry.standings.error = null;
                try {
                    let standings = [];
                    // Use pre-fetched raw matches from bundle if available, else fetch separately
                    let matches;
                    if (isFresh(entry.rawMatches) && Array.isArray(entry.rawMatches.data)) {
                        matches = entry.rawMatches.data;
                    } else if (typeof window.apiClient.getDivisionMatches === 'function') {
                        matches = await window.apiClient.getDivisionMatches(id);
                        entry.rawMatches.data = Array.isArray(matches) ? matches : [];
                        entry.rawMatches.fetchedAt = now();
                    }
                    const scopedMatches = Array.isArray(matches)
                        ? matches.filter(match => String(match?.championship_id ?? match?.championshipId ?? '') === String(id))
                        : [];
                    if (scopedMatches.length) {
                        const details = entry.details.data || (await this.fetchDivisionDetails(id));
                        standings = deriveStandingsFromMatches(scopedMatches, details?.teams || [], id);
                    }
                    entry.standings.data = standings;
                    entry.standings.fetchedAt = now();
                    return standings;
                } catch (error) {
                    entry.standings.error = error?.message || 'Sarjataulukon lataus epäonnistui';
                    throw error;
                } finally {
                    entry.standings.loading = false;
                }
            },
            async fetchDivisionMaps(id, options = {}) {
                if (!id) return [];
                const { force = false } = options;
                const entry = this.ensureEntry(id);
                if (entry.maps.loading) {
                    return entry.maps.data || [];
                }
                if (!force && isFresh(entry.maps)) {
                    return entry.maps.data || [];
                }
                entry.maps.loading = true;
                entry.maps.error = null;
                try {
                    const maps = await window.apiClient.getDivisionMapStats(id);
                    entry.maps.data = Array.isArray(maps) ? maps : [];
                    entry.maps.fetchedAt = now();
                    return entry.maps.data;
                } catch (error) {
                    entry.maps.error = error?.message || 'Karttatilastojen lataus epäonnistui';
                    throw error;
                } finally {
                    entry.maps.loading = false;
                }
            },
            async fetchDivisionHighlights(id, options = {}) {
                if (!id) return [];
                const { force = false } = options;
                const entry = this.ensureEntry(id);
                if (entry.highlights.loading) {
                    return entry.highlights.data || [];
                }
                if (!force && isFresh(entry.highlights)) {
                    return entry.highlights.data || [];
                }
                entry.highlights.loading = true;
                entry.highlights.error = null;
                try {
                    const details = entry.details.data || (await this.fetchDivisionDetails(id));
                    const standings = entry.standings.data || [];
                    const highlights = deriveHighlights(details, standings);
                    entry.highlights.data = highlights;
                    entry.highlights.fetchedAt = now();
                    return highlights;
                } catch (error) {
                    entry.highlights.error = error?.message || 'Nostoja ei voitu hakea';
                    throw error;
                } finally {
                    entry.highlights.loading = false;
                }
            }
        }
    });
})();


/* === /static/stores/useUpcomingStore.js === */
(function () {
    const { defineStore } = Pinia;

    const FRESH_MS = 2 * 60 * 1000;

    function now() {
        return Date.now();
    }

    function createSegment() {
        return {
            data: [],
            meta: null,
            loading: false,
            error: null,
            fetchedAt: null,
            params: null
        };
    }

    function isFresh(segment) {
        return !!(segment && segment.fetchedAt && now() - segment.fetchedAt < FRESH_MS && !segment.error);
    }

    function normalizeKeyPart(value) {
        if (value === null || value === undefined || value === '') return '_';
        return String(value);
    }

    function buildKey(params) {
        if (!params || typeof params !== 'object') return 'upcoming::default';
        const parts = [
            normalizeKeyPart(params.championshipId ?? params.championship_id),
            normalizeKeyPart(params.teamId ?? params.team_id),
            normalizeKeyPart(params.season ?? params.seasonId ?? params.season_id),
            normalizeKeyPart(
                typeof params.includePlayoffs === 'boolean'
                    ? params.includePlayoffs
                    : (typeof params.include_playoffs === 'boolean' ? params.include_playoffs : 'default')
            ),
            normalizeKeyPart(params.limit),
            normalizeKeyPart(params.offset)
        ];
        return `upcoming::${parts.join(':')}`;
    }

    window.useUpcomingStore = defineStore('upcoming', {
        state: () => ({
            entries: {}
        }),
        getters: {
            getEntry(state) {
                return key => state.entries[key] || createSegment();
            },
            getEntryForParams(state) {
                return params => {
                    const key = buildKey(params);
                    return state.entries[key] || createSegment();
                };
            }
        },
        actions: {
            ensureEntry(key) {
                if (!this.entries[key]) {
                    this.entries[key] = createSegment();
                }
                return this.entries[key];
            },
            async fetchUpcomingMatches(params = {}, options = {}) {
                const { force = false } = options;
                const key = buildKey(params);
                const entry = this.ensureEntry(key);

                if (entry.loading) {
                    return entry.data || [];
                }
                if (!force && isFresh(entry)) {
                    return entry.data || [];
                }

                entry.loading = true;
                entry.error = null;
                entry.params = params;
                try {
                    const payload = await window.apiClient.getUpcomingMatches(params);
                    entry.data = Array.isArray(payload?.items) ? payload.items : [];
                    entry.meta = payload?.meta || null;
                    entry.fetchedAt = now();
                    return entry.data;
                } catch (error) {
                    entry.error = error?.message || 'Tulevien otteluiden haku epäonnistui';
                    throw error;
                } finally {
                    entry.loading = false;
                }
            },
            seedUpcoming(params, items, meta = null) {
                const key = buildKey(params);
                const entry = this.ensureEntry(key);
                if (isFresh(entry)) return;
                entry.data = Array.isArray(items) ? items : [];
                entry.meta = meta;
                entry.fetchedAt = now();
                entry.params = params;
            }
        }
    });
})();


/* === /static/stores/useTeamStore.js === */
(function () {
    const { defineStore } = Pinia;

    const FRESH_MS = 5 * 60 * 1000;

    function now() {
        return Date.now();
    }

    function createSegment() {
        return {
            data: null,
            loading: false,
            error: null,
            fetchedAt: null,
            promise: null
        };
    }

    function cacheKeyFor(teamId, championshipId) {
        const teamPart = String(teamId || '');
        const champPart = championshipId ? String(championshipId) : 'auto';
        return `${teamPart}::${champPart}`;
    }

    function isFresh(segment, championshipId) {
        if (!segment || !segment.fetchedAt || segment.error) {
            return false;
        }
        const fresh = now() - segment.fetchedAt < FRESH_MS;
        if (!fresh) return false;
        if (championshipId) {
            const resolvedChampionship =
                segment?.data?.currentChampionshipId
                || segment?.data?.current_championship_id
                || null;
            if (!resolvedChampionship) {
                return false;
            }
            return String(resolvedChampionship) === String(championshipId);
        }
        return fresh;
    }

    window.useTeamStore = defineStore('team', {
        state: () => ({
            teams: {}
        }),
        getters: {
            getTeamState(state) {
                return teamId => {
                    if (!teamId) return null;
                    return state.teams[teamId] || null;
                };
            },
            getTeamPageSegment(state) {
                return (teamId, championshipId = null) => {
                    if (!teamId) return null;
                    const entry = state.teams[teamId] || null;
                    if (!entry) return null;
                    const key = cacheKeyFor(teamId, championshipId);
                    return entry.pages?.[key] || entry.page || null;
                };
            }
        },
        actions: {
            ensureTeamEntry(teamId) {
                if (!teamId) return null;
                if (!this.teams[teamId]) {
                    this.teams[teamId] = {
                        pages: {},
                        page: createSegment(),
                        selectedChampionship: null
                    };
                }
                return this.teams[teamId];
            },
            async fetchTeamPage(teamId, championshipId, options = {}) {
                if (!teamId) return null;
                const entry = this.ensureTeamEntry(teamId);
                const { force = false } = options;
                const targetChampionship = championshipId || entry.selectedChampionship || null;
                const key = cacheKeyFor(teamId, targetChampionship);
                if (!entry.pages[key]) {
                    entry.pages[key] = createSegment();
                }
                const segment = entry.pages[key];
                entry.page = segment;

                if (segment.loading && segment.promise) {
                    try {
                        await segment.promise;
                    } catch (_error) {
                    }
                }
                if (!force && isFresh(segment, targetChampionship)) {
                    return segment.data;
                }

                segment.loading = true;
                segment.error = null;
                segment.promise = (async () => {
                    try {
                        const data = await window.apiClient.getTeamPage(teamId, targetChampionship);
                        segment.data = data || {};
                        segment.fetchedAt = now();
                        const resolvedChampionship =
                            data?.currentChampionshipId
                            || data?.current_championship_id
                            || targetChampionship
                            || null;
                        entry.selectedChampionship = resolvedChampionship;
                        if (resolvedChampionship) {
                            const resolvedKey = cacheKeyFor(teamId, resolvedChampionship);
                            entry.pages[resolvedKey] = segment;
                        }
                        entry.page = segment;
                        return segment.data;
                    } catch (error) {
                        segment.error = error?.message || 'Joukkuesivun lataus epäonnistui';
                        throw error;
                    } finally {
                        segment.loading = false;
                        segment.promise = null;
                    }
                })();

                return segment.promise;
            }
        }
    });
})();



/* === /static/stores/usePlayerStore.js === */
(function () {
    const { defineStore } = Pinia;

    const FRESH_MS = 5 * 60 * 1000;

    function now() {
        return Date.now();
    }

    function createSegment() {
        return {
            data: null,
            loading: false,
            error: null,
            fetchedAt: null
        };
    }

    function isFresh(segment) {
        return !!(segment && segment.fetchedAt && now() - segment.fetchedAt < FRESH_MS && !segment.error);
    }

    function ensurePlayerEntry(state, playerId) {
        if (!state[playerId]) {
            state[playerId] = {
                profile: createSegment(),
                seasons: createSegment(),
                maps: {},
                progression: {}
            };
        }
        return state[playerId];
    }

    function ensureMapEntry(entry, championshipId) {
        if (!entry.maps) {
            entry.maps = {};
        }
        if (!entry.maps[championshipId]) {
            entry.maps[championshipId] = createSegment();
        }
        return entry.maps[championshipId];
    }

    function ensureProgressionEntry(entry, championshipId) {
        if (!entry.progression) {
            entry.progression = {};
        }
        if (!entry.progression[championshipId]) {
            entry.progression[championshipId] = createSegment();
        }
        return entry.progression[championshipId];
    }

    function applyBundleToEntry(entry, bundle, championshipId = null) {
        const payload = (bundle && typeof bundle === 'object') ? bundle : {};
        const profile = payload.player || null;
        const seasons = Array.isArray(payload.seasons) ? payload.seasons : [];
        const selectedChampionshipId = String(
            payload.selected_championship_id
            || payload.selectedChampionshipId
            || championshipId
            || ''
        );
        const mapStats = Array.isArray(payload.map_stats || payload.mapStats) ? (payload.map_stats || payload.mapStats) : [];
        const progression = Array.isArray(payload.progression) ? payload.progression : [];

        if (profile) {
            entry.profile.data = profile;
            entry.profile.error = null;
            entry.profile.fetchedAt = now();
        }
        entry.seasons.data = seasons;
        entry.seasons.error = null;
        entry.seasons.fetchedAt = now();

        if (selectedChampionshipId) {
            const mapEntry = ensureMapEntry(entry, selectedChampionshipId);
            mapEntry.data = mapStats;
            mapEntry.error = null;
            mapEntry.fetchedAt = now();

            const progressionEntry = ensureProgressionEntry(entry, selectedChampionshipId);
            progressionEntry.data = progression;
            progressionEntry.error = null;
            progressionEntry.fetchedAt = now();
        }
    }

    window.usePlayerStore = defineStore('player', {
        state: () => ({
            players: {}
        }),
        getters: {
            getPlayerState(state) {
                return playerId => {
                    if (!playerId) return null;
                    return state.players[playerId] || null;
                };
            }
        },
        actions: {
            ensureEntry(playerId) {
                return ensurePlayerEntry(this.players, playerId);
            },
            async fetchBundle(playerId, championshipId = null, options = {}) {
                if (!playerId) return null;
                const entry = this.ensureEntry(playerId);
                const { force = false } = options;
                const bundleKey = championshipId ? String(championshipId) : '__default__';
                entry.bundle = entry.bundle || {};
                const segment = entry.bundle[bundleKey] || createSegment();
                entry.bundle[bundleKey] = segment;

                if (segment.loading) {
                    return segment.data;
                }
                if (!force && isFresh(segment)) {
                    return segment.data;
                }
                segment.loading = true;
                segment.error = null;
                try {
                    const data = await window.apiClient.getPlayerBundle(playerId, championshipId);
                    segment.data = data || {};
                    segment.fetchedAt = now();
                    applyBundleToEntry(entry, segment.data, championshipId);
                    return segment.data;
                } catch (error) {
                    segment.error = error?.message || 'Pelaajan tietojen lataus epäonnistui';
                    throw error;
                } finally {
                    segment.loading = false;
                }
            },
            async fetchProfile(playerId, options = {}) {
                if (!playerId) return null;
                const entry = this.ensureEntry(playerId);
                try {
                    await this.fetchBundle(playerId, null, options);
                    return entry.profile.data;
                } catch (error) {
                    entry.profile.error = error?.message || 'Pelaajan tietojen lataus epäonnistui';
                    throw error;
                }
            },
            async fetchSeasons(playerId, options = {}) {
                if (!playerId) return [];
                const entry = this.ensureEntry(playerId);
                try {
                    await this.fetchBundle(playerId, null, options);
                    return entry.seasons.data;
                } catch (error) {
                    entry.seasons.error = error?.message || 'Pelaajan kausitilastojen lataus epäonnistui';
                    throw error;
                }
            },
            async fetchMapStats(playerId, championshipId, options = {}) {
                if (!playerId || !championshipId) return [];
                try {
                    await this.fetchBundle(playerId, championshipId, options);
                    const entry = this.ensureEntry(playerId);
                    return ensureMapEntry(entry, championshipId).data || [];
                } catch (error) {
                    const entry = this.ensureEntry(playerId);
                    const mapEntry = ensureMapEntry(entry, championshipId);
                    mapEntry.error = error?.message || 'Pelaajan karttatilastojen lataus epäonnistui';
                    throw error;
                }
            },
            async fetchProgression(playerId, championshipId, season, division, options = {}) {
                if (!playerId || !championshipId || season == null || division == null) return [];
                try {
                    await this.fetchBundle(playerId, championshipId, options);
                    const entry = this.ensureEntry(playerId);
                    return ensureProgressionEntry(entry, championshipId).data || [];
                } catch (error) {
                    const entry = this.ensureEntry(playerId);
                    const progressionEntry = ensureProgressionEntry(entry, championshipId);
                    progressionEntry.error = error?.message || 'Pelaajan kehitystrendin lataus epäonnistui';
                    throw error;
                }
            }
        }
    });
})();



/* === /static/components/GlobalNav.js === */
// GlobalNav.js - Context-aware breadcrumb navigation
(function () {
    const { computed } = Vue;
    const { useRoute } = VueRouter;

    window.GlobalNav = {
        name: 'GlobalNav',
        template: `
            <div class="global-nav" v-if="breadcrumbs.length > 0">
                <div class="layout-boundary">
                    <div class="breadcrumbs">
                        <template v-for="(crumb, index) in breadcrumbs" :key="crumb.key">
                            <router-link 
                                v-if="!crumb.disabled"
                                :to="crumb.to" 
                                class="breadcrumb-link"
                                :class="{ 'breadcrumb-link--active': index === breadcrumbs.length - 1 }">
                                <span class="breadcrumb-icon" v-if="crumb.icon">{{ crumb.icon }}</span>
                                <span class="breadcrumb-text">{{ crumb.label }}</span>
                            </router-link>
                            <span v-else class="breadcrumb-current">
                                <span class="breadcrumb-icon" v-if="crumb.icon">{{ crumb.icon }}</span>
                                <span class="breadcrumb-text">{{ crumb.label }}</span>
                            </span>
                            <span v-if="index < breadcrumbs.length - 1" class="breadcrumb-separator">›</span>
                        </template>
                    </div>
                </div>
            </div>
        `,
        setup() {
            const route = useRoute();
            const divisionStore = typeof window.useDivisionStore === 'function' ? window.useDivisionStore() : null;
            const teamStore = typeof window.useTeamStore === 'function' ? window.useTeamStore() : null;
            const playerStore = typeof window.usePlayerStore === 'function' ? window.usePlayerStore() : null;
            const seasonsStore = typeof window.useSeasonsStore === 'function' ? window.useSeasonsStore() : null;

            function beautifyDivisionLabel(value) {
                if (!value) return '';
                const text = String(value).replace(/[-_]+/g, ' ').trim();
                if (!text) return '';
                return text.charAt(0).toUpperCase() + text.slice(1);
            }

            function looksLikeRawId(value) {
                const text = String(value || '').trim();
                if (!text) return false;
                // Championship IDs are UUID-like; do not surface them as breadcrumb labels.
                return /^[0-9a-f]{8}(?:[-\s]?[0-9a-f]{4}){3}[-\s]?[0-9a-f]{12}$/i.test(text)
                    || /^[0-9a-f-]{24,}$/i.test(text);
            }

            function formatSeasonLabel(value) {
                if (value === null || value === undefined) return '';
                const text = String(value).trim();
                if (!text) return '';
                if (/^kausi\s+/i.test(text)) return text;
                if (/^s\d+/i.test(text)) return text.toUpperCase();
                return `Kausi ${text}`;
            }

            function normalizeIdLike(value) {
                return String(value || '').replace(/[^a-z0-9]/gi, '').toLowerCase();
            }

            function looksLikeChampionshipIdLabel(label, championshipId) {
                const normalizedLabel = normalizeIdLike(label);
                const normalizedId = normalizeIdLike(championshipId);
                return Boolean(normalizedLabel) && Boolean(normalizedId) && normalizedLabel === normalizedId;
            }

            function formatDivisionBreadcrumbLabel(name, seasonValue, isPlayoffs = false, divisionNum = null) {
                const normalizer = typeof window !== 'undefined' ? window.divisionNormalizer : null;
                if (normalizer?.buildDivisionBreadcrumbMeta) {
                    return normalizer.buildDivisionBreadcrumbMeta({
                        name,
                        season: seasonValue,
                        isPlayoffs,
                        divisionNum
                    }).label;
                }
                const safeName = String(name || '').trim() || 'Divisioona';
                const seasonLabel = seasonValue ? formatSeasonLabel(seasonValue) : '';
                const base = seasonLabel ? `${safeName} (${seasonLabel})` : safeName;
                if (isPlayoffs && !/playoffs?/i.test(base)) return `${base} (Playoffs)`;
                return base;
            }

            function readTeamContext(params) {
                const teamId = params?.teamId;
                if (!teamStore || !teamId || typeof teamStore.getTeamState !== 'function') return null;
                const entry = teamStore.getTeamState(teamId);
                if (!entry) return null;
                const page = entry?.page?.data || null;
                const seasons = Array.isArray(page?.seasons) ? page.seasons : [];
                const selectedChampionshipId =
                    params?.championshipId
                    || entry?.selectedChampionship
                    || page?.currentChampionshipId
                    || null;
                const seasonRow = selectedChampionshipId
                    ? (seasons.find(season => String(season?.championshipId || '') === String(selectedChampionshipId)) || null)
                    : null;
                return {
                    page,
                    seasonRow,
                    selectedChampionshipId: selectedChampionshipId ? String(selectedChampionshipId) : null
                };
            }

            function resolveDivisionSeason(params) {
                const lookupKey = params?.championshipId;
                if (divisionStore && lookupKey && typeof divisionStore.getDivisionState === 'function') {
                    const entry = divisionStore.getDivisionState(lookupKey);
                    const season = entry?.details?.data?.season;
                    if (season != null) return String(season);
                }
                const teamContext = readTeamContext(params);
                if (teamContext?.seasonRow?.season != null) {
                    return String(teamContext.seasonRow.season);
                }
                return '';
            }

            function resolveDivisionName(params) {
                const lookupKey = params?.championshipId;
                if (divisionStore && lookupKey && typeof divisionStore.getDivisionState === 'function') {
                    const entry = divisionStore.getDivisionState(lookupKey);
                    const name = entry?.details?.data?.name;
                    if (name) return String(name);
                }
                const teamContext = readTeamContext(params);
                if (teamContext?.seasonRow) {
                    const row = teamContext.seasonRow;
                    if (row?.name) return String(row.name);
                    const divisionNum = row?.divisionNum;
                    if (divisionNum != null) {
                        const normalizer = typeof window !== 'undefined' ? window.divisionNormalizer : null;
                        if (normalizer?.buildDivisionBreadcrumbMeta) {
                            return normalizer.buildDivisionBreadcrumbMeta({
                                name: null,
                                divisionNum,
                                season: row?.season,
                                isPlayoffs: Boolean(row?.isPlayoffs)
                            }).name;
                        }
                        return `${divisionNum} Divisioona`;
                    }
                }
                if (lookupKey) {
                    if (looksLikeRawId(lookupKey)) {
                        return '';
                    }
                    return beautifyDivisionLabel(lookupKey);
                }
                return 'Divisioona';
            }

            function resolveTeamName(params) {
                const teamId = params?.teamId;
                if (teamStore && teamId && typeof teamStore.getTeamState === 'function') {
                    const entry = teamStore.getTeamState(teamId);
                    const team = entry?.page?.data?.team || null;
                    const name =
                        team?.displayName ||
                        team?.display_name ||
                        team?.teamName ||
                        team?.team_name ||
                        team?.name ||
                        null;
                    if (name) return String(name);
                }
                if (teamId) {
                    return `Joukkue ${teamId}`;
                }
                return 'Joukkue';
            }

            function resolveCurrentSeasonLabel() {
                if (!seasonsStore) return '';
                const current = seasonsStore.currentSeason || seasonsStore.seasons?.find(season => season?.isActive) || seasonsStore.newestSeason || null;
                if (!current) return '';
                const label = current.label || current.shortLabel || null;
                if (label) return label;
                const seasonId = current.id ?? current.seasonNumber ?? null;
                return seasonId != null ? `Kausi ${seasonId}` : '';
            }

            function readPlayerContext(playerId, preferredChampionshipId = null) {
                if (!playerStore || !playerId || typeof playerStore.getPlayerState !== 'function') return null;
                const entry = playerStore.getPlayerState(playerId);
                if (!entry) return null;
                const profile = entry?.profile?.data || null;
                const seasons = Array.isArray(entry?.seasons?.data) ? entry.seasons.data : [];
                const defaultBundle = entry?.bundle?.__default__?.data || null;
                const selectedChampionshipIdRaw =
                    preferredChampionshipId
                    || defaultBundle?.selected_championship_id
                    || defaultBundle?.selectedChampionshipId
                    || '';
                const selectedChampionshipId = String(selectedChampionshipIdRaw || '');
                const selectedSeason = selectedChampionshipId
                    ? (seasons.find(season =>
                        String(
                            season?.championship_id
                            || season?.championshipId
                            || season?.id
                            || ''
                        ) === selectedChampionshipId
                    ) || null)
                    : (seasons[0] || null);
                return { profile, selectedSeason, selectedChampionshipId };
            }

            function resolvePlayerName(params) {
                const playerId = params?.playerId;
                const context = readPlayerContext(playerId, params?.championshipId || null);
                const nickname =
                    context?.profile?.nickname
                    || context?.profile?.name
                    || context?.profile?.player_name
                    || null;
                return nickname ? String(nickname) : `Pelaaja ${playerId}`;
            }

            function resolvePlayerTeamContext(params) {
                const playerId = params?.playerId;
                const context = readPlayerContext(playerId, params?.championshipId || null);
                const seasonRow = context?.selectedSeason || null;
                const championshipId =
                    params?.championshipId
                    || seasonRow?.championship_id
                    || seasonRow?.championshipId
                    || seasonRow?.id
                    || context?.selectedChampionshipId
                    || null;
                const teamId =
                    seasonRow?.team_id
                    || seasonRow?.teamId
                    || null;
                const teamName =
                    seasonRow?.team_name
                    || seasonRow?.teamName
                    || seasonRow?.team
                    || null;
                const season = seasonRow?.season != null ? String(seasonRow.season) : null;
                const division = seasonRow?.division_num != null ? String(seasonRow.division_num) : null;
                const isPlayoffs = Boolean(
                    seasonRow?.is_playoffs
                    || seasonRow?.isPlayoffs
                    || seasonRow?.is_playoff
                );
                return {
                    championshipId: championshipId ? String(championshipId) : null,
                    teamId: teamId ? String(teamId) : null,
                    teamName: teamName ? String(teamName) : null,
                    season,
                    division,
                    isPlayoffs
                };
            }

            const breadcrumbs = computed(() => {
                const crumbs = [];
                const routeName = route.name;
                const params = route.params;
                const isPlayerRoute = routeName === 'player' || routeName === 'player-detail';

                // Always add home first
                crumbs.push({
                    key: 'home',
                    label: 'Etusivu',
                    icon: '🏠',
                    to: { name: 'home' },
                    disabled: routeName === 'home'
                });

                if (routeName === 'season-upcoming') {
                    const seasonLabel = resolveCurrentSeasonLabel();
                    crumbs.push({
                        key: 'season-upcoming',
                        label: seasonLabel ? `Tulevat ottelut (${seasonLabel})` : 'Tulevat ottelut',
                        icon: '📅',
                        to: { name: 'season-upcoming' },
                        disabled: true
                    });
                }

                // Division/Championship context
                if (params.championshipId && !isPlayerRoute) {
                    const teamContext = readTeamContext(params);
                    const teamSeason = teamContext?.seasonRow || null;
                    const championshipName = resolveDivisionName(params);
                    const seasonValue = resolveDivisionSeason(params);
                    const isPlayoffs = Boolean(teamSeason?.isPlayoffs);
                    const fullLabel = formatDivisionBreadcrumbLabel(
                        championshipName,
                        seasonValue,
                        isPlayoffs,
                        teamSeason?.divisionNum ?? null
                    );
                    
                    crumbs.push({
                        key: 'division',
                        label: fullLabel,
                        icon: '🏆',
                        to: { 
                            name: 'division', 
                            params: { championshipId: params.championshipId }
                        },
                        disabled: routeName === 'division'
                    });
                }

                // Team context
                if (params.teamId) {
                    const teamName = resolveTeamName(params);
                    
                    // If championship isn't in params, derive it from current team context.
                    const teamContext = readTeamContext(params);
                    if (!params.championshipId && teamContext?.selectedChampionshipId) {
                        const championshipIdFromQuery = teamContext.selectedChampionshipId;
                        const championshipName = resolveDivisionName({ championshipId: championshipIdFromQuery });
                        const seasonValue = resolveDivisionSeason({ championshipId: championshipIdFromQuery });
                        const isPlayoffs = Boolean(teamContext?.seasonRow?.isPlayoffs);
                        const fullLabel = formatDivisionBreadcrumbLabel(championshipName, seasonValue, isPlayoffs);
                        
                        crumbs.push({
                            key: 'division',
                            label: fullLabel,
                            icon: '🏆',
                            to: { 
                                name: 'division', 
                                params: { championshipId: championshipIdFromQuery }
                            },
                            disabled: false
                        });
                    }
                    
                    // Add team breadcrumb
                    crumbs.push({
                        key: 'team',
                        label: teamName,
                        icon: '👥',
                        to: params.championshipId 
                            ? { 
                                name: 'team-detail', 
                                params: { 
                                    championshipId: params.championshipId,
                                    teamId: params.teamId 
                                }
                            }
                            : { 
                                name: 'team', 
                                params: { teamId: params.teamId }
                            },
                        disabled: routeName === 'team' || routeName === 'team-detail'
                    });
                }

                // Player context
                if (params.playerId && isPlayerRoute) {
                    const playerName = resolvePlayerName(params);
                    const playerContext = resolvePlayerTeamContext(params);
                    const isPlayoffs = playerContext.isPlayoffs;

                    if (playerContext.championshipId) {
                        const championshipName = resolveDivisionName({ championshipId: playerContext.championshipId });
                        const championshipLooksLikeId = looksLikeChampionshipIdLabel(championshipName, playerContext.championshipId);
                        const seasonValue = resolveDivisionSeason({ championshipId: playerContext.championshipId }) || playerContext.season;
                        const fullLabel = formatDivisionBreadcrumbLabel(
                            championshipLooksLikeId ? null : championshipName,
                            seasonValue,
                            isPlayoffs,
                            playerContext.division
                        );
                        crumbs.push({
                            key: 'division',
                            label: fullLabel,
                            icon: '🏆',
                            to: {
                                name: 'division',
                                params: { championshipId: playerContext.championshipId }
                            },
                            disabled: false
                        });
                    }

                    if (playerContext.teamId || playerContext.teamName) {
                        const teamName = playerContext.teamName || `Joukkue ${playerContext.teamId || ''}`.trim();
                        const teamTo = playerContext.teamId
                            ? (playerContext.championshipId
                                ? {
                                    name: 'team-detail',
                                    params: {
                                        championshipId: playerContext.championshipId,
                                        teamId: playerContext.teamId
                                    }
                                }
                                : {
                                    name: 'team',
                                    params: { teamId: playerContext.teamId }
                                })
                            : null;
                        crumbs.push({
                            key: 'team',
                            label: teamName,
                            icon: '👥',
                            to: teamTo || { name: 'home' },
                            disabled: !teamTo
                        });
                    }

                    crumbs.push({
                        key: 'player',
                        label: playerName,
                        icon: '🎮',
                        to: playerContext.championshipId
                            ? {
                                name: 'player-detail',
                                params: {
                                    championshipId: playerContext.championshipId,
                                    playerId: params.playerId
                                }
                            }
                            : { 
                                name: 'player', 
                                params: { playerId: params.playerId }
                            },
                        disabled: true
                    });
                }

                // Seasons page
                if (routeName === 'seasons') {
                    crumbs.push({
                        key: 'seasons',
                        label: 'Kaudet',
                        icon: '📅',
                        to: { name: 'seasons' },
                        disabled: true
                    });
                }

                if (routeName === 'teams') {
                    crumbs.push({
                        key: 'teams',
                        label: 'Joukkueet',
                        icon: '👥',
                        to: { name: 'teams' },
                        disabled: true
                    });
                }

                if (routeName === 'players') {
                    crumbs.push({
                        key: 'players',
                        label: 'Pelaajat',
                        icon: '🎮',
                        to: { name: 'players' },
                        disabled: true
                    });
                }

                return crumbs;
            });

            return {
                breadcrumbs
            };
        }
    };
})();


