// SankariCard - reusable card for Divarin Sankarit rows
window.SankariCard = {
    name: 'SankariCard',
    props: {
        title: { type: String, required: true },
        description: { type: String, default: '' },
        entries: {
            type: Array,
            default: () => []
        },
        tooltip: { type: String, default: '' }
    },
    computed: {
        visibleEntries() {
            return Array.isArray(this.entries) ? this.entries.slice(0, 4) : [];
        }
    },
    methods: {
        championshipId() {
            return this.$route?.params?.championshipId || this.$route?.query?.championship || null;
        },
        playerRoute(entry) {
            const playerId = entry?.playerId || entry?.player_id || null;
            if (!playerId) return null;
            const championshipId = this.championshipId();
            return {
                name: 'player',
                params: { playerId: String(playerId) },
                query: championshipId ? { championship: String(championshipId) } : {}
            };
        },
        avatarUrl(src) {
            const fallback = window.PAPPALIIGA_DEFAULT_LOGO;
            if (!src) return fallback;
            try {
                const proxied = window.apiClient && window.apiClient.proxyAvatar
                    ? window.apiClient.proxyAvatar(src)
                    : src;
                return proxied || fallback;
            } catch (error) {
                return fallback;
            }
        },
        entryKey(entry, idx) {
            return entry?.id || entry?.playerId || entry?.nickname || `sankari-${idx}`;
        },
        infoLine(entry) {
            const maps = entry?.maps ?? entry?.mapsPlayed;
            const rounds = entry?.rounds ?? entry?.roundsPlayed;
            if (maps != null && rounds != null) {
                return `${maps} karttaa / ${rounds} kierrosta`;
            }
            if (rounds != null) {
                return `${rounds} kierrosta`;
            }
            return '';
        },
        displayValue(entry) {
            if (entry == null) return '–';
            if (entry.displayValue != null && entry.displayValue !== '') return entry.displayValue;
            if (entry.rawValue != null && entry.rawValue !== '') return entry.rawValue;
            return entry.value != null ? entry.value : '–';
        }
    },
    template: `
        <article class="sankari-card glass-card division-surface" :title="tooltip || null">
            <div class="sankari-card__content">
                <header class="sankari-card__head">
                    <h3 class="title-accent titleUnderlineCard">{{ title }}</h3>
                    <p v-if="description" class="sankari-card__desc" v-html="description"></p>
                </header>
                <ol class="sankari-card__list">
                    <li
                        v-for="(entry, idx) in visibleEntries"
                        :key="entryKey(entry, idx)"
                        class="sankari-card__row"
                        tabindex="0"
                    >
                        <span class="sankari-card__rank">#{{ idx + 1 }}</span>
                        <div class="sankari-card__meta">
                            <div class="sankari-card__player">
                                <img
                                    class="sankari-card__avatar"
                                    :src="avatarUrl(entry?.logo || entry?.avatar)"
                                    :alt="(entry?.teamName || entry?.nickname || 'Pelaaja') + ' logo'"
                                    loading="lazy"
                                />
                                <div>
                                    <router-link
                                        v-if="playerRoute(entry)"
                                        :to="playerRoute(entry)"
                                        class="sankari-card__name player-link"
                                    >{{ entry?.nickname || entry?.name || 'Tuntematon' }}</router-link>
                                    <div v-else class="sankari-card__name">{{ entry?.nickname || entry?.name || 'Tuntematon' }}</div>
                                    <div class="sankari-card__team muted">{{ entry?.teamName || entry?.team || '' }}</div>
                                </div>
                            </div>
                            <div v-if="infoLine(entry)" class="sankari-card__hint muted">{{ infoLine(entry) }}</div>
                        </div>
                        <div class="sankari-card__value">{{ displayValue(entry) }}</div>
                    </li>
                </ol>
            </div>
        </article>
    `
};


/* === /static/components/CircularProgress.js === */
(function () {
    'use strict';

    /**
     * CircularProgress - Ring-style circular progress indicator
     * 
     * Props:
     * - value: Number - Current value (played matches)
     * - max: Number - Maximum value (total matches)
     * - size: Number - Diameter of the circle in pixels (default: 120)
     * - strokeWidth: Number - Width of the ring stroke (default: 8)
     * - label: String - Text label below the circle
     * - sublabel: String - Secondary text below the label
     * - animationDelay: Number - Delay before animation starts in seconds
     * - color: String - Color variant: 'regular', 'playoff', 'overall' (default: 'regular')
     */
    
    window.CircularProgress = {
        name: 'CircularProgress',
        props: {
            value: { type: Number, default: 0 },
            max: { type: Number, default: 100 },
            size: { type: Number, default: 120 },
            strokeWidth: { type: Number, default: 8 },
            label: { type: String, default: '' },
            sublabel: { type: String, default: '' },
            animationDelay: { type: Number, default: 0 },
            color: { type: String, default: 'regular' }
        },
        computed: {
            percent() {
                const safeMax = Number.isFinite(this.max) ? this.max : 0;
                const safeValue = Number.isFinite(this.value) ? this.value : 0;
                if (safeMax <= 0) return 0;
                return Math.min(100, Math.max(0, Math.round((safeValue / safeMax) * 100)));
            },
            percentText() {
                return `${this.percent}%`;
            },
            radius() {
                return (this.size - this.strokeWidth) / 2;
            },
            circumference() {
                return 2 * Math.PI * this.radius;
            },
            strokeDashoffset() {
                const progress = this.percent / 100;
                return this.circumference * (1 - progress);
            },
            viewBox() {
                return `0 0 ${this.size} ${this.size}`;
            },
            center() {
                return this.size / 2;
            },
            colorClass() {
                return `circular-progress--${this.color}`;
            },
            containerStyle() {
                return {
                    '--animation-delay': `${this.animationDelay}s`,
                    '--circle-size': `${this.size}px`
                };
            },
            circleStyle() {
                return {
                    strokeDasharray: this.circumference,
                    strokeDashoffset: this.strokeDashoffset,
                    strokeWidth: this.strokeWidth
                };
            },
            playedText() {
                const safeMax = Number.isFinite(this.max) ? Math.round(this.max) : 0;
                const safeValue = Number.isFinite(this.value) ? Math.round(this.value) : 0;
                if (safeMax <= 0) {
                    return `${safeValue} Ottelut`;
                }
                const clamped = Math.min(safeValue, safeMax);
                return `${clamped} / ${safeMax} Ottelut`;
            },
            remainingValue() {
                const total = Number.isFinite(this.max) ? this.max : 0;
                const played = Number.isFinite(this.value) ? this.value : 0;
                const remaining = total - played;
                if (!Number.isFinite(remaining)) {
                    return 0;
                }
                return remaining > 0 ? Math.round(remaining) : 0;
            },
            remainingText() {
                return `${this.remainingValue} jäljellä`;
            }
        },
        template: `
            <div class="circular-progress" :class="colorClass" :style="containerStyle">
                <div class="circular-progress__circle-container">
                    <svg 
                        class="circular-progress__svg" 
                        :width="size" 
                        :height="size" 
                        :viewBox="viewBox"
                        role="img"
                        :aria-label="label + ': ' + percent + '%'"
                    >
                        <defs>
                            <linearGradient id="gradient-regular" x1="0%" y1="0%" x2="100%" y2="100%">
                                <stop offset="0%" stop-color="rgba(120, 180, 255, 1)" />
                                <stop offset="100%" stop-color="rgba(60, 120, 255, 1)" />
                            </linearGradient>
                            <linearGradient id="gradient-playoff" x1="0%" y1="0%" x2="100%" y2="100%">
                                <stop offset="0%" stop-color="rgba(180, 120, 255, 1)" />
                                <stop offset="100%" stop-color="rgba(120, 80, 255, 1)" />
                            </linearGradient>
                            <linearGradient id="gradient-overall" x1="0%" y1="0%" x2="100%" y2="100%">
                                <stop offset="0%" stop-color="rgba(120, 240, 190, 1)" />
                                <stop offset="100%" stop-color="rgba(80, 200, 150, 1)" />
                            </linearGradient>
                        </defs>
                        <!-- Background ring -->
                        <circle
                            class="circular-progress__ring circular-progress__ring--bg"
                            :cx="center"
                            :cy="center"
                            :r="radius"
                            :stroke-width="strokeWidth"
                            fill="none"
                        />
                        <!-- Progress ring -->
                        <circle
                            class="circular-progress__ring circular-progress__ring--progress"
                            :cx="center"
                            :cy="center"
                            :r="radius"
                            :style="circleStyle"
                            fill="none"
                            stroke-linecap="round"
                        />
                    </svg>
                    <div class="circular-progress__label">
                        <span class="circular-progress__percent">{{ percentText }}</span>
                        <span class="circular-progress__played">{{ playedText }}</span>
                        <span class="circular-progress__remaining">{{ remainingText }}</span>
                    </div>
                </div>
                <div class="circular-progress__text">
                    <div class="circular-progress__title title-accent titleUnderlineCard">{{ label }}</div>
                </div>
            </div>
        `
    };
})();


/* === /static/components/DivisionCardList.js === */
(function () {
    'use strict';

    const DivisionStatus = Object.freeze({
        NOT_STARTED: 'ei-alkanut',
        REGULAR_ACTIVE: 'runkosarja-kaynnissa',
        PLAYOFFS_ACTIVE: 'playoffit-kaynnissa',
        COMPLETE: 'taputeltu-loppuun'
    });
    const DEFAULT_STATUS_LABELS = Object.freeze({
        [DivisionStatus.NOT_STARTED]: 'Ei alkanut',
        [DivisionStatus.REGULAR_ACTIVE]: 'Runkosarja käynnissä',
        [DivisionStatus.PLAYOFFS_ACTIVE]: 'Playoffit käynnissä',
        [DivisionStatus.COMPLETE]: 'Taputeltu loppuun'
    });
    const STATUS_META =
        (typeof window !== 'undefined' && window.PAPPALIIGA_DIVISION_STATUS_META) || {};
    const STATUS_LABELS = Object.freeze({
        [DivisionStatus.NOT_STARTED]:
            STATUS_META[DivisionStatus.NOT_STARTED]?.label ||
            DEFAULT_STATUS_LABELS[DivisionStatus.NOT_STARTED],
        [DivisionStatus.REGULAR_ACTIVE]:
            STATUS_META[DivisionStatus.REGULAR_ACTIVE]?.label ||
            DEFAULT_STATUS_LABELS[DivisionStatus.REGULAR_ACTIVE],
        [DivisionStatus.PLAYOFFS_ACTIVE]:
            STATUS_META[DivisionStatus.PLAYOFFS_ACTIVE]?.label ||
            DEFAULT_STATUS_LABELS[DivisionStatus.PLAYOFFS_ACTIVE],
        [DivisionStatus.COMPLETE]:
            STATUS_META[DivisionStatus.COMPLETE]?.label ||
            DEFAULT_STATUS_LABELS[DivisionStatus.COMPLETE]
    });
    const STATUS_ICONS = Object.freeze({
        [DivisionStatus.NOT_STARTED]: STATUS_META[DivisionStatus.NOT_STARTED]?.icon || null,
        [DivisionStatus.REGULAR_ACTIVE]: STATUS_META[DivisionStatus.REGULAR_ACTIVE]?.icon || null,
        [DivisionStatus.PLAYOFFS_ACTIVE]: STATUS_META[DivisionStatus.PLAYOFFS_ACTIVE]?.icon || null,
        [DivisionStatus.COMPLETE]: STATUS_META[DivisionStatus.COMPLETE]?.icon || null
    });
    const STATUS_ORDER = Array.isArray(
        typeof window !== 'undefined' && window.PAPPALIIGA_DIVISION_STATUS_ORDER
    )
        ? window.PAPPALIIGA_DIVISION_STATUS_ORDER
        : [
              DivisionStatus.NOT_STARTED,
              DivisionStatus.REGULAR_ACTIVE,
              DivisionStatus.PLAYOFFS_ACTIVE,
              DivisionStatus.COMPLETE
          ];
    const FILTER_STATES = Object.freeze(['all', ...STATUS_ORDER]);
    const FILTER_ORDER = FILTER_STATES;
    const FILTER_LABELS = Object.freeze({
        all: 'Kaikki',
        [DivisionStatus.NOT_STARTED]: STATUS_LABELS[DivisionStatus.NOT_STARTED],
        [DivisionStatus.REGULAR_ACTIVE]: STATUS_LABELS[DivisionStatus.REGULAR_ACTIVE],
        [DivisionStatus.PLAYOFFS_ACTIVE]: STATUS_LABELS[DivisionStatus.PLAYOFFS_ACTIVE],
        [DivisionStatus.COMPLETE]: STATUS_LABELS[DivisionStatus.COMPLETE]
    });
    const STORAGE_KEY = 'pappaliiga:last-division';
    const isDevEnv = typeof window !== 'undefined' && ['localhost', '127.0.0.1'].includes(window.location.hostname);

    function getStoredDivisionId() {
        try {
            if (typeof window === 'undefined' || !window.localStorage) return null;
            return window.localStorage.getItem(STORAGE_KEY);
        } catch (error) {
            return null;
        }
    }

    function inferTierFromDivisionId(divisionId) {
        const numeric = Number(divisionId);
        if (numeric === 0) return 0;
        if (numeric >= 1 && numeric <= 5) return 1;
        if (numeric >= 6 && numeric <= 10) return 2;
        if (numeric >= 11 && numeric <= 15) return 3;
        if (numeric >= 16 && numeric <= 20) return 4;
        return 5;
    }

    function inferDivisionIndexFromName(rawName) {
        const text = String(rawName || '').trim();
        if (!text) return null;
        if (/mestaruussarja/i.test(text)) return 0;

        const divMatch = text.match(/(?:^|\s)(\d+)\s*divisioona(?:\b|\s|$)/i);
        if (divMatch && Number.isFinite(Number(divMatch[1]))) {
            return Number(divMatch[1]);
        }

        const trailingNumber = text.match(/(\d+)$/);
        if (trailingNumber && Number.isFinite(Number(trailingNumber[1]))) {
            return Number(trailingNumber[1]);
        }

        return null;
    }

    function inferDivisionIndex(division) {
        if (!division) return null;
        const candidates = [
            division.divisionNumber,
            division.division_num,
            division.divisionNum,
            division.division,
            division.number,
            division.rank
        ];

        for (const candidate of candidates) {
            const numeric = Number(candidate);
            if (Number.isFinite(numeric) && numeric >= 0) {
                return numeric;
            }
        }

        const fromName = inferDivisionIndexFromName(division.title || division.name);
        if (fromName != null) {
            return fromName;
        }

        return null;
    }

    function inferTierMetaFromDivisionNumber(divisionNumber) {
        const numeric = Number(divisionNumber);
        if (!Number.isFinite(numeric) || numeric <= 0) {
            if (numeric === 0) {
                return { id: 0, label: 'Mestaruussarja (Div 0)', range: 'Div 0', order: 0 };
            }
            return { id: 5, label: 'Tier 5 (Div 21+)', range: 'Div 21+', order: 5 };
        }
        if (numeric >= 1 && numeric <= 5) return { id: 1, label: 'Tier 1 (Div 1-5)', range: 'Div 1-5', order: 1 };
        if (numeric >= 6 && numeric <= 10) return { id: 2, label: 'Tier 2 (Div 6-10)', range: 'Div 6-10', order: 2 };
        if (numeric >= 11 && numeric <= 15) return { id: 3, label: 'Tier 3 (Div 11-15)', range: 'Div 11-15', order: 3 };
        if (numeric >= 16 && numeric <= 20) return { id: 4, label: 'Tier 4 (Div 16-20)', range: 'Div 16-20', order: 4 };
        return { id: 5, label: 'Tier 5 (Div 21+)', range: 'Div 21+', order: 5 };
    }

    function storeDivisionId(id) {
        try {
            if (typeof window !== 'undefined' && window.localStorage && id) {
                window.localStorage.setItem(STORAGE_KEY, id);
            }
        } catch (error) {
            // no-op
        }
    }

    function clampMatchCount(value) {
        const numeric = Number(value);
        if (!Number.isFinite(numeric) || numeric < 0) {
            return 0;
        }
        return Math.round(numeric);
    }

    function getProgressState(played, total) {
        const safePlayed = clampMatchCount(played);
        const safeTotal = clampMatchCount(total);
        if (safeTotal > 0 && safePlayed >= safeTotal) {
            return 'finished';
        }
        if (safePlayed > 0) {
            return 'active';
        }
        return 'not-started';
    }

    function getDivisionStatus(regularPlayed, regularTotal, playoffPlayed, playoffTotal) {
        const regularPlayedSafe = clampMatchCount(regularPlayed);
        const regularTotalSafe = clampMatchCount(regularTotal);
        const playoffPlayedSafe = clampMatchCount(playoffPlayed);
        const playoffTotalSafe = clampMatchCount(playoffTotal);
        const hasPlayoffs = playoffTotalSafe > 0;

        if (
            regularPlayedSafe === regularTotalSafe &&
            (!hasPlayoffs || playoffPlayedSafe === playoffTotalSafe)
        ) {
            return DivisionStatus.COMPLETE;
        }

        if (hasPlayoffs && playoffPlayedSafe > 0 && playoffPlayedSafe < playoffTotalSafe) {
            return DivisionStatus.PLAYOFFS_ACTIVE;
        }

        if (
            hasPlayoffs &&
            regularTotalSafe > 0 &&
            regularPlayedSafe === regularTotalSafe &&
            playoffPlayedSafe === 0
        ) {
            return DivisionStatus.PLAYOFFS_ACTIVE;
        }

        if (
            regularPlayedSafe > 0 &&
            regularTotalSafe > 0 &&
            regularPlayedSafe < regularTotalSafe &&
            playoffPlayedSafe === 0
        ) {
            return DivisionStatus.REGULAR_ACTIVE;
        }

        if (regularPlayedSafe === 0 && playoffPlayedSafe === 0) {
            return DivisionStatus.NOT_STARTED;
        }

        if (regularPlayedSafe > 0 && regularTotalSafe === 0) {
            return DivisionStatus.REGULAR_ACTIVE;
        }

        return DivisionStatus.NOT_STARTED;
    }

    function buildProgressCopy(played, total) {
        const safePlayed = clampMatchCount(played);
        const safeTotal = clampMatchCount(total);
        const hasTotal = safeTotal > 0;
        const playedValue = hasTotal ? Math.min(safePlayed, safeTotal) : safePlayed;
        const percent = hasTotal && safeTotal > 0 ? Math.round((playedValue / safeTotal) * 100) : 0;
        const remaining = hasTotal ? Math.max(safeTotal - playedValue, 0) : 0;

        const base = hasTotal
            ? `${playedValue} / ${safeTotal} ottelua Ottelut`
            : safePlayed > 0
              ? `${safePlayed} ottelua Ottelut`
              : 'Ei otteluita';

        return {
            label: hasTotal ? `${playedValue} / ${safeTotal} Ottelut` : base,
            tooltip: hasTotal ? `${base} · ${remaining} jäljellä` : base,
            percent,
            remaining
        };
    }

    function stateClass(value) {
        const normalized = value ? String(value).trim().toLowerCase() : '';
        if (!normalized) {
            return DivisionStatus.NOT_STARTED;
        }
        return normalized.replace(/[^a-z0-9]+/g, '-');
    }

    function inferTierMeta(card) {
        if (card?.tierMeta) {
            return card.tierMeta;
        }
        const divisionNumber = inferDivisionIndex(card);
        if (divisionNumber != null) {
            return inferTierMetaFromDivisionNumber(divisionNumber);
        }
        const value = Number(card?.tier);
        if (Number.isFinite(value) && value > 0) {
            if (value === 1) return { id: 1, label: 'Tier 1 (Div 1-5)', range: 'Div 1-5', order: 1 };
            if (value === 2) return { id: 2, label: 'Tier 2 (Div 6-10)', range: 'Div 6-10', order: 2 };
            if (value === 3) return { id: 3, label: 'Tier 3 (Div 11-15)', range: 'Div 11-15', order: 3 };
            if (value === 4) return { id: 4, label: 'Tier 4 (Div 16-20)', range: 'Div 16-20', order: 4 };
            return { id: 5, label: 'Tier 5 (Div 21+)', range: 'Div 21+', order: 5 };
        }
        if (value === 0) {
            return { id: 0, label: 'Mestaruussarja (Div 0)', range: 'Div 0', order: 0 };
        }
        return inferTierMetaFromDivisionNumber(inferTierFromDivisionId(card?.id ?? card?.divisionId ?? card?.division_id));
    }

    function buildDivisionNumberGroups(cards, targetGroupSize = 5) {
        const source = Array.isArray(cards) ? cards : [];
        const numbered = source
            .filter(card => Number.isFinite(Number(card?.divisionNumber)) && Number(card?.divisionNumber) >= 0)
            .sort((a, b) => Number(a.divisionNumber) - Number(b.divisionNumber));
        const unknown = source.filter(card => !Number.isFinite(Number(card?.divisionNumber)));

        const groups = [];

        const total = numbered.length;
        if (total > 0) {
            const safeTarget = Math.max(1, Number(targetGroupSize) || 5);
            const groupCount = Math.max(1, Math.ceil(total / safeTarget));
            const baseSize = Math.floor(total / groupCount);
            const remainder = total % groupCount;

            let cursor = 0;
            for (let index = 0; index < groupCount; index += 1) {
                const size = baseSize + (index < remainder ? 1 : 0);
                const chunk = numbered.slice(cursor, cursor + size);
                cursor += size;
                if (!chunk.length) continue;

                const minDivision = Number(chunk[0].divisionNumber);
                const maxDivision = Number(chunk[chunk.length - 1].divisionNumber);
                const rangeLabel = minDivision === maxDivision ? `Div ${minDivision}` : `Div ${minDivision}-${maxDivision}`;
                const label =
                    minDivision === 0 && maxDivision === 0
                        ? 'Mestaruussarja (Div 0)'
                        : minDivision === 0
                          ? `Mestaruussarja + Div 1-${maxDivision}`
                          : rangeLabel;

                groups.push({
                    id: `div-${minDivision}-${maxDivision}`,
                    label,
                    rangeLabel,
                    cards: chunk,
                    minDivision,
                    maxDivision
                });
            }
        }

        if (unknown.length) {
            groups.push({
                id: 'div-unknown',
                label: 'Tuntematon divisioona',
                rangeLabel: 'N/A',
                cards: unknown,
                minDivision: null,
                maxDivision: null
            });
        }

        return groups;
    }

    function buildGroupProgress(cards) {
        const source = Array.isArray(cards) ? cards : [];
        let regularPlayed = 0;
        let regularTotal = 0;
        let playoffPlayed = 0;
        let playoffTotal = 0;

        source.forEach(card => {
            const seasonPlayed = clampMatchCount(card?.season?.matchesPlayed ?? 0);
            const seasonTotal = clampMatchCount(card?.season?.matchesTotal ?? 0);
            const playoffPlayedValue = clampMatchCount(card?.playoffs?.matchesPlayed ?? 0);
            const playoffTotalValue = clampMatchCount(card?.playoffs?.matchesTotal ?? 0);

            regularPlayed += seasonPlayed;
            regularTotal += seasonTotal;
            playoffPlayed += playoffPlayedValue;
            playoffTotal += playoffTotalValue;
        });

        const overallPlayed = regularPlayed + playoffPlayed;
        const overallTotal = regularTotal + playoffTotal;

        return {
            regular: {
                played: regularPlayed,
                total: regularTotal,
                label: 'Runko',
                color: 'regular'
            },
            playoff: {
                played: playoffPlayed,
                total: playoffTotal,
                label: 'PO',
                color: 'playoff'
            },
            overall: {
                played: overallPlayed,
                total: overallTotal,
                label: 'Kausi',
                color: 'overall'
            }
        };
    }

    function cleanDivisionName(rawName) {
        if (!rawName) return '';
        // Remove season suffix like "S11", "S12", etc.
        return String(rawName).replace(/\s+S\d+$/i, '').trim();
    }

    function slugifyFallback(value) {
        if (!value) return '';
        const base = String(value);
        const normalized = typeof base.normalize === 'function' ? base.normalize('NFD') : base;
        return normalized
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9]+/g, '-')
            .replace(/^-+|-+$/g, '')
            .toLowerCase();
    }

    function resolveDivisionSlug(division, fallbackName) {
        const normalizer = typeof window !== 'undefined' ? window.divisionNormalizer : null;
        const resolved = normalizer?.getDivisionSlug ? normalizer.getDivisionSlug(division) : null;
        if (resolved) return resolved;
        const name = fallbackName || division?.name || '';
        return slugifyFallback(name) || null;
    }

    function resolveDivisionSeason(division) {
        if (!division) return null;
        const direct = division.seasonNumber ?? division.season_number;
        if (direct != null) return direct;
        const seasonValue = division.season;
        if (typeof seasonValue === 'number' || typeof seasonValue === 'string') {
            return seasonValue;
        }
        if (seasonValue && typeof seasonValue === 'object') {
            return (
                seasonValue.season ??
                seasonValue.season_number ??
                seasonValue.seasonNumber ??
                seasonValue.id ??
                null
            );
        }
        return null;
    }

    function buildDivisionHref(slug, divisionId, name, season, isPlayoffs) {
        const base = divisionId != null ? String(divisionId) : (slug || '');
        if (!base) return '/division';
        return `/division/${base}`;
    }

    function buildCardModel(division) {
        if (!division) {
            return null;
        }

        // Handle both camelCase and snake_case from API
        const divisionId = division.divisionId || division.division_id || division.id;
        const divisionNum = inferDivisionIndex({
            divisionNumber: division.division_num ?? division.divisionNum ?? division.divisionNumber,
            division_num: division.division_num,
            divisionNum: division.divisionNum,
            division: division.division,
            number: division.number,
            rank: division.rank,
            name: division.name,
            title: division.title
        });
        const tierMeta = inferTierMeta({
            ...division,
            id: divisionId,
            divisionNumber: divisionNum,
            division_num: divisionNum,
            divisionNum: divisionNum
        });

        // Season data
        const seasonMatchesPlayed = clampMatchCount(
            division.season?.matches_played ?? division.season?.matchesPlayed ?? 0
        );
        const seasonMatchesTotal = clampMatchCount(
            division.season?.matches_total ?? division.season?.matchesTotal ?? 0
        );
        const playoffsMatchesPlayed = clampMatchCount(
            division.playoffs?.matches_played ?? division.playoffs?.matchesPlayed ?? 0
        );
        const playoffsMatchesTotal = clampMatchCount(
            division.playoffs?.matches_total ?? division.playoffs?.matchesTotal ?? 0
        );
        let playoffTeams = Number(division.playoffs?.teams ?? 0);
        if (!Number.isFinite(playoffTeams) || playoffTeams < 0) {
            playoffTeams = 0;
        }
        const playoffChampionshipId =
            division.playoffs?.playoff_championship_id ??
            division.playoffs?.playoffChampionshipId ??
            null;
        const playoffsStatusRaw = String(division.playoffs?.status || 'waiting').toLowerCase();
        const playoffsWaiting = playoffsStatusRaw === 'waiting';
        const playoffsConfigured = Boolean(
            playoffsMatchesTotal > 0 ||
            playoffTeams > 0 ||
            playoffChampionshipId ||
            playoffsWaiting
        );
        const combinedStatus = getDivisionStatus(
            seasonMatchesPlayed,
            seasonMatchesTotal,
            playoffsMatchesPlayed,
            playoffsMatchesTotal
        );
        const seasonCopy = buildProgressCopy(seasonMatchesPlayed, seasonMatchesTotal);
        const playoffCopy = playoffsConfigured
            ? buildProgressCopy(playoffsMatchesPlayed, playoffsMatchesTotal)
            : { label: 'Ei playoffeja', tooltip: 'Ei playoffeja', percent: 0, remaining: 0 };
        const hrefId = resolveDivisionSlug(division, division.name) || divisionId;
        const playoffsHrefId =
            (typeof window !== 'undefined' && window.divisionNormalizer?.getPlayoffsHrefId
                ? window.divisionNormalizer.getPlayoffsHrefId(division)
                : null) ||
            null;
        // Clean the division name - remove season suffix
        const cleanName = cleanDivisionName(division.name);
        const title = cleanName || (divisionNum != null ? `Division ${divisionNum}` : 'Division');
        const seasonValue = resolveDivisionSeason(division);
        
        // Extract best player and MVP team info
        const bestPlayer = division.meta?.mvp_player || division.best_player || division.bestPlayer;
        const mvpTeam = division.meta?.winner_team || division.mvp_team || division.mvpTeam;
        const winners = division.winners || [];
        
        return {
            id: divisionId,
            divisionNumber: divisionNum,
            title,
            tierMeta,
            tier: tierMeta.id,
            state: combinedStatus,
            season: {
                teams: null,
                matchesPlayed: seasonMatchesPlayed,
                matchesTotal: seasonMatchesTotal,
                percent: seasonCopy.percent,
                progressState: getProgressState(seasonMatchesPlayed, seasonMatchesTotal),
                isFinished: seasonMatchesTotal > 0 && seasonMatchesPlayed >= seasonMatchesTotal,
                progressLabel: seasonCopy.label,
                progressTooltip: seasonCopy.tooltip,
                winner: division.season?.winner || division.meta?.winner_team || null
            },
            playoffs: {
                teams: playoffTeams,
                matchesPlayed: playoffsMatchesPlayed,
                matchesTotal: playoffsMatchesTotal,
                percent: playoffCopy.percent,
                status: playoffsStatusRaw,
                hasChampionship: playoffsConfigured,
                progressState: getProgressState(playoffsMatchesPlayed, playoffsMatchesTotal),
                isFinished:
                    playoffsConfigured && playoffsMatchesTotal > 0
                        ? playoffsMatchesPlayed >= playoffsMatchesTotal
                        : false,
                progressLabel: playoffCopy.label,
                progressTooltip: playoffCopy.tooltip,
                winner: division.playoffs?.winner_team || division.playoffs?.winner || null,
                href: playoffsConfigured && playoffsHrefId
                    ? buildDivisionHref(playoffsHrefId, playoffsHrefId, title, seasonValue, true)
                    : ''
            },
            bestPlayer: bestPlayer ? {
                name: bestPlayer.name || bestPlayer.nickname,
                kd: Number(bestPlayer.kd || 0).toFixed(2)
            } : null,
            mvpTeam: mvpTeam,
            winners: winners,
            slug: hrefId,
            href: buildDivisionHref(hrefId, divisionId, title, seasonValue, false),
            searchIndex: [division.name, division.id, division.divisionId].map(value => (value ? String(value).toLowerCase() : '')).join(' ')
        };
    }

    const SeasonBar = {
        name: 'SeasonBar',
        props: {
            seasonOptions: { type: Array, default: () => [] },
            selectedSeason: { type: [String, Number], default: '' },
            seasonLoading: { type: Boolean, default: false },
            filterState: { type: String, default: 'all' },
            searchQuery: { type: String, default: '' },
            showSeasonPicker: { type: Boolean, default: true }
        },
        emits: ['change-season', 'change-filter', 'change-search', 'reset-filters'],
        data() {
            return {
                filters: FILTER_ORDER
            };
        },
        computed: {
            statusMeta() {
                return STATUS_META;
            }
        },
        template: `
            <div class="division-season-bar" role="region" aria-label="Season controls">
                <div
                    v-if="showSeasonPicker"
                    class="division-season-bar__section"
                >
                    <label class="division-season-bar__label" for="season-filter">Season</label>
                    <select
                        id="season-filter"
                        class="division-season-bar__select"
                        :value="selectedSeason"
                        :disabled="seasonLoading || !seasonOptions.length"
                        @change="$emit('change-season', $event.target.value)"
                    >
                        <template v-if="seasonOptions.length">
                            <optgroup v-for="group in seasonOptions" :label="group.label" :key="group.id">
                                <option v-for="option in group.options" :value="option.key" :key="option.key">{{ option.label }}</option>
                            </optgroup>
                        </template>
                        <option v-else disabled>Ei kausia</option>
                    </select>
                </div>
                <div class="division-season-bar__section">
                    <span class="division-season-bar__label">Tila</span>
                    <div class="division-season-bar__filters">
                        <button
                            v-for="state in filters"
                            :key="state"
                            type="button"
                            class="season-filter-chip"
                            :class="{ 'season-filter-chip--active': filterState === state }"
                            :data-status="state !== 'all' ? state : null"
                            :aria-pressed="filterState === state"
                            @click="$emit('change-filter', state)"
                        >
                            <span
                                v-if="state !== 'all' && statusMeta[state]?.icon"
                                class="season-filter-chip__icon"
                                aria-hidden="true"
                            >
                                <svg
                                    :viewBox="statusMeta[state].icon.viewBox"
                                    role="presentation"
                                    focusable="false"
                                >
                                    <path
                                        v-for="(path, idx) in statusMeta[state].icon.paths"
                                        :key="idx"
                                        :d="path.d"
                                        fill="currentColor"
                                    ></path>
                                </svg>
                            </span>
                            <span class="season-filter-chip__label">{{ FILTER_LABELS[state] || state }}</span>
                        </button>
                    </div>
                </div>
                <label class="division-season-bar__section division-season-bar__search">
                    <span class="division-season-bar__label sr-only">Search divisions</span>
                    <input
                        type="search"
                        class="division-season-bar__input"
                        placeholder="Search divisions"
                        :value="searchQuery"
                        @input="$emit('change-search', $event.target.value)"
                    >
                </label>
                <div class="division-season-bar__section division-season-bar__reset">
                    <button type="button" class="season-filter-reset" @click="$emit('reset-filters')">Reset</button>
                </div>
            </div>
        `
    };

    const DivisionProgressBar = {
        name: 'DivisionProgressBar',
        props: {
            value: { type: Number, default: 0 },
            max: { type: Number, default: 100 },
            state: { type: String, default: 'not-started' },
            label: { type: String, default: '' },
            ariaLabel: { type: String, default: '' },
            animationDelay: { type: Number, default: 0 },
            tooltip: { type: String, default: '' },
            showPercent: { type: Boolean, default: false }
        },
        computed: {
            percent() {
                const safeMax = Number.isFinite(this.max) ? this.max : 0;
                const safeValue = Number.isFinite(this.value) ? this.value : 0;
                if (safeMax <= 0) return 0;
                return Math.min(100, Math.max(0, Math.round((safeValue / safeMax) * 100)));
            },
            stateClass() {
                return `division-progress--${stateClass(this.state)}`;
            },
            fillStyle() {
                return {
                    width: this.percent + '%',
                    '--shimmer-delay': `${this.animationDelay}s`
                };
            },
            tooltipText() {
                return this.tooltip || this.label;
            },
            displayLabel() {
                if (!this.showPercent) return this.label;
                if (!this.label) return `${this.percent}%`;
                return `${this.percent}% · ${this.label}`;
            }
        },
        template: `
            <div
                class="division-progress"
                :class="stateClass"
                role="progressbar"
                :aria-valuenow="percent"
                aria-valuemin="0"
                aria-valuemax="100"
                :aria-label="ariaLabel || label"
                :title="tooltipText"
                :data-tooltip="tooltipText"
            >
                <div class="division-progress__track">
                    <div class="division-progress__fill" :style="fillStyle"></div>
                    <span class="division-progress__label">{{ displayLabel }}</span>
                </div>
            </div>
        `
    };

    const DivisionCard = {
        name: 'DivisionCard',
        components: { DivisionProgressBar },
        props: {
            division: { type: Object, required: true }
        },
        emits: ['remember'],
        computed: {
            playoffsPendingStart() {
                // Only show "Odottaa playoffeja" when no championship has been set up yet.
                // Once a playoff championship exists (status === 'active' or 'finished'),
                // treat it as started even if no matches have been played yet.
                return Boolean(
                    this.division.playoffs?.hasChampionship &&
                    this.division.season?.isFinished &&
                    this.division.playoffs.matchesPlayed === 0 &&
                    !this.division.playoffs.isFinished &&
                    this.division.playoffs.status !== 'active' &&
                    this.division.playoffs.status !== 'finished'
                );
            },
            displayStatusState() {
                return this.playoffsPendingStart ? DivisionStatus.NOT_STARTED : this.division.state;
            },
            statusLabel() {
                if (this.playoffsPendingStart) {
                    return 'Odottaa playoffeja';
                }
                return STATUS_LABELS[this.displayStatusState] || STATUS_LABELS[DivisionStatus.NOT_STARTED];
            },
            statusIcon() {
                return STATUS_ICONS[this.displayStatusState] || null;
            },
            playoffsHasStarted() {
                if (!this.division.playoffs?.hasChampionship) {
                    return false;
                }
                return Boolean(
                    this.division.playoffs.matchesPlayed > 0 ||
                    this.division.playoffs.isFinished ||
                    this.division.playoffs.winner
                );
            },
            isDivisionComplete() {
                if (this.division.state === DivisionStatus.COMPLETE) {
                    return true;
                }
                if (this.division.playoffs?.hasChampionship) {
                    return Boolean(
                        this.division.playoffs.isFinished ||
                        (this.division.playoffs.matchesTotal > 0 &&
                            this.division.playoffs.matchesPlayed >= this.division.playoffs.matchesTotal)
                    );
                }
                return Boolean(
                    this.division.season.isFinished ||
                    (this.division.season.matchesTotal > 0 &&
                        this.division.season.matchesPlayed >= this.division.season.matchesTotal)
                );
            },
            progressStage() {
                if (this.isDivisionComplete) {
                    return 'complete';
                }
                if (this.playoffsHasStarted) {
                    return 'playoffs';
                }
                return 'regular';
            },
            progressModel() {
                if (this.progressStage === 'complete') {
                    return {
                        value: 100,
                        max: 100,
                        state: 'finished',
                        label: '100%',
                        tooltip: 'Divisioona valmis',
                        showPercent: false
                    };
                }
                if (this.progressStage === 'playoffs') {
                    return {
                        value: this.division.playoffs.matchesPlayed,
                        max: this.division.playoffs.matchesTotal || this.division.playoffs.matchesPlayed || 0,
                        state: this.division.playoffs.progressState,
                        label: this.division.playoffs.progressLabel,
                        tooltip: this.division.playoffs.progressTooltip,
                        showPercent: true
                    };
                }
                return {
                    value: this.division.season.matchesPlayed,
                    max: this.division.season.matchesTotal || this.division.season.matchesPlayed || 0,
                    state: this.division.season.progressState,
                    label: this.division.season.progressLabel,
                    tooltip: this.division.season.progressTooltip,
                    showPercent: true
                };
            },
            showPlayoffsCTA() {
                if (!this.division.playoffs?.hasChampionship) {
                    return false;
                }
                if (!this.division.playoffs.href) {
                    return false;
                }
                // Show button as soon as the playoff championship is set up (active/finished),
                // not only after the first match has been played.
                return (
                    this.playoffsHasStarted ||
                    this.division.playoffs.status === 'active' ||
                    this.division.playoffs.status === 'finished'
                );
            },
            seasonRows() {
                const rows = [];
                const hasBestPlayer = Boolean(this.division.bestPlayer);
                const hasMvpTeam = Boolean(this.division.mvpTeam);
                if (hasBestPlayer) {
                    rows.push({ key: 'bestPlayer', label: 'Paras pelaaja', value: `${this.division.bestPlayer.name} (K/D ${this.division.bestPlayer.kd})` });
                }
                if (hasMvpTeam) {
                    rows.push({ key: 'mvpTeam', label: 'MVP-joukkue', value: this.division.mvpTeam });
                }
                return rows;
            },
            showWinnerStrip() {
                const seasonWinner = this.division.season.winner;
                const playoffsWinner = this.division.playoffs.winner;
                if (!this.division.season.isFinished || !seasonWinner) {
                    return false;
                }
                if (!this.division.playoffs.hasChampionship) {
                    return true;
                }
                if (!this.division.playoffs.isFinished) {
                    return true;
                }
                return playoffsWinner === seasonWinner;
            }
        },
        methods: {
            handleCTA() {
                storeDivisionId(this.division.id);
                this.$emit('remember', this.division.id);
            },
            handlePlayoffsCTA() {
                storeDivisionId(this.division.id);
                this.$emit('remember', this.division.id);
            },
            stateClass
        },
        template: `
            <article class="division-card" role="listitem" :class="'division-card--' + stateClass(displayStatusState)">
                <header class="division-card__header division-card__header--centered">
                    <div class="division-card__title-row division-card__title-row--centered">
                        <h3
                            class="division-card__title division-card__title--hero title-accent titleUnderlineCard"
                            :title="division.title"
                        >
                            <span class="division-card__title-text">{{ division.title }}</span>
                        </h3>
                    </div>
                    <p v-if="showWinnerStrip" class="division-card__winner-banner division-card__winner-banner--centered">
                        Voittaja: {{ division.season.winner }}
                    </p>
                </header>
                <div class="division-card__body">
                    <section class="division-card__block division-card__block--regular">
                        <div class="division-card__stat-lines">
                            <p class="division-card__stat-line">Joukkueet: {{ division.season.teams != null ? division.season.teams : '–' }}</p>
                        </div>
                        <division-progress-bar
                            :value="progressModel.value"
                            :max="progressModel.max"
                            :state="progressModel.state"
                            :label="progressModel.label"
                            :tooltip="progressModel.tooltip"
                            :show-percent="progressModel.showPercent"
                            :aria-label="division.title + ' eteneminen'"
                            :animation-delay="(division.divisionNumber * 0.15) % 2"
                        ></division-progress-bar>
                        <div class="division-card__status-row division-card__status-row--centered">
                            <span
                                class="division-card__badge"
                                :class="'division-card__badge--' + stateClass(displayStatusState)"
                                :data-status="displayStatusState"
                            >
                                <span v-if="statusIcon" class="status-pill__icon" aria-hidden="true">
                                    <svg
                                        :viewBox="statusIcon.viewBox"
                                        role="presentation"
                                        focusable="false"
                                    >
                                        <path
                                            v-for="(path, idx) in statusIcon.paths"
                                            :key="idx"
                                            :d="path.d"
                                            fill="currentColor"
                                        ></path>
                                    </svg>
                                </span>
                                <span class="status-pill__label">{{ statusLabel }}</span>
                            </span>
                        </div>
                        <p v-if="division.playoffs.isFinished && division.playoffs.winner" class="division-card__note division-card__note--centered">
                            Playoff-voittaja: {{ division.playoffs.winner }}
                        </p>
                        <ul v-if="seasonRows.length" class="division-card__facts division-card__facts--centered" role="list">
                            <li v-for="row in seasonRows" :key="row.key">
                                <span class="division-card__fact-label">{{ row.label }}</span>
                                <span class="division-card__fact-value">{{ row.value }}</span>
                            </li>
                        </ul>
                    </section>
                    <div class="division-card__action-row division-card__action-row--split">
                        <a class="division-card__action division-card__action--primary" :href="division.href" @click="handleCTA">
                            Avaa divisioona
                        </a>
                        <a
                            v-if="showPlayoffsCTA"
                            class="division-card__action division-card__action--ghost"
                            :href="division.playoffs.href"
                            @click="handlePlayoffsCTA"
                        >
                            Näytä playoffit
                        </a>
                    </div>
                </div>
            </article>
        `
    };

    window.DivisionCardList = {
        name: 'DivisionCardList',
        components: { SeasonBar, DivisionCard, DivisionProgressBar, CircularProgress: window.CircularProgress },
        props: {
            divisions: { type: Array, default: () => [] },
            emptyMessage: { type: String, default: 'Ei divisioonia saatavilla' },
            filterState: { type: String, default: 'all' },
            searchQuery: { type: String, default: '' },
            seasonOptions: { type: Array, default: () => [] },
            selectedSeason: { type: [String, Number], default: '' },
            seasonLoading: { type: Boolean, default: false },
            offlineMessage: { type: String, default: '' },
            dataBadge: { type: String, default: '' },
            warningMessage: { type: String, default: '' },
            isLoading: { type: Boolean, default: false },
            showSeasonPicker: { type: Boolean, default: true },
            showControls: { type: Boolean, default: true },
            groupByDivision: { type: Boolean, default: false },
            collapsibleGroups: { type: Boolean, default: false },
            groupByTier: { type: Boolean, default: false },
            collapsibleTiers: { type: Boolean, default: false }
        },
        emits: ['change-season', 'change-filter', 'change-search', 'reset-filters'],
        data() {
            return {
                preferredDivisionId: getStoredDivisionId(),
                renderCount: 0,
                renderBatchSize: 8,
                sentinelObserver: null,
                teamCountOverrides: {},
                teamCountRequests: {},
                collapsedGroupIds: [],
                knownGroupIds: []
            };
        },
        computed: {
            groupingEnabled() {
                return Boolean(this.groupByDivision || this.groupByTier);
            },
            collapsibleEnabled() {
                return Boolean(this.collapsibleGroups || this.collapsibleTiers);
            },
            cardModels() {
                if (!Array.isArray(this.divisions)) {
                    return [];
                }
                const overrides = this.teamCountOverrides || {};
                const mapped = this.divisions.map(buildCardModel).filter(Boolean);
                mapped.forEach(card => {
                    const override = overrides[card.id];
                    if (Number.isFinite(override)) {
                        card.season.teams = override;
                    }
                });
                if (!mapped.length && this.divisions.length) {
                    if (isDevEnv) {
                        console.warn('[DivisionCardList] Falling back to raw division rendering. Normalized set empty.');
                    }
                    return this.divisions
                        .map((entry, index) => {
                            if (!entry) return null;
                            const safeId = entry.id || entry.division_id || entry.divisionId || entry.slug || `division-${index}`;
                            const rawSeason = entry.season && typeof entry.season === 'object' ? entry.season : {};
                            const rawPlayoffs = entry.playoffs && typeof entry.playoffs === 'object' ? entry.playoffs : {};
                            const fallbackSeason = {
                                teams: Number(rawSeason.teams ?? entry.teams ?? 0),
                                matches_played: Number(rawSeason.matches_played ?? rawSeason.matchesPlayed ?? entry.matches_played ?? entry.matchesPlayed ?? 0),
                                matches_total: Number(rawSeason.matches_total ?? rawSeason.matchesTotal ?? entry.matches_total ?? entry.matchesTotal ?? 0),
                                winner: rawSeason.winner || entry.winner || null
                            };
                            const fallbackPlayoffs = {
                                teams: Number(rawPlayoffs.teams ?? 0) || 0,
                                matches_played: Number(rawPlayoffs.matches_played ?? rawPlayoffs.matchesPlayed ?? 0),
                                matches_total: Number(rawPlayoffs.matches_total ?? rawPlayoffs.matchesTotal ?? 0) || 0,
                                winner: rawPlayoffs.winner || null
                            };
                            const fallbackDivisionId = (entry.divisionId ?? entry.division_id ?? Number(entry.id)) || index;
                            const fallbackTierSource = entry.divisionId ?? entry.division_id ?? entry.id;
                            const fallbackDivisionNum = inferDivisionIndex({
                                divisionNumber: entry.division_num ?? entry.divisionNum ?? entry.divisionNumber,
                                division_num: entry.division_num,
                                divisionNum: entry.divisionNum,
                                division: entry.division,
                                number: entry.number,
                                rank: entry.rank,
                                name: entry.name,
                                title: entry.title
                            });
                            return buildCardModel({
                                id: String(safeId),
                                divisionId: fallbackDivisionId,
                                name: entry.name || `Division ${(entry.division_id ?? entry.divisionId ?? index)}`,
                                tier: Number(entry.tier) || inferTierFromDivisionId(fallbackTierSource),
                                division_num: fallbackDivisionNum,
                                divisionNumber: fallbackDivisionNum,
                                season: fallbackSeason,
                                playoffs: fallbackPlayoffs,
                                slug: entry.slug || String(safeId),
                                seasonNumber: entry.seasonNumber ?? entry.season_number ?? null,
                                raw: entry
                            });
                        })
                        .filter(Boolean);
                }
                return mapped;
            },
            filterStateNormalized() {
                const state = String(this.filterState || 'all').toLowerCase();
                return FILTER_STATES.includes(state) ? state : 'all';
            },
            searchQueryNormalized() {
                return String(this.searchQuery || '').trim().toLowerCase();
            },
            filteredCards() {
                const filterState = this.filterStateNormalized;
                const search = this.searchQueryNormalized;
                const sorted = this.cardModels
                    .filter(card => filterState === 'all' || card.state === filterState)
                    .filter(card => {
                        if (!search) return true;
                        return card.searchIndex.includes(search);
                    })
                    .sort((a, b) => {
                        // Sort by stable inferred division index so tier/group order is deterministic.
                        const aNum = Number.isFinite(Number(a.divisionNumber)) ? Number(a.divisionNumber) : Number.MAX_SAFE_INTEGER;
                        const bNum = Number.isFinite(Number(b.divisionNumber)) ? Number(b.divisionNumber) : Number.MAX_SAFE_INTEGER;
                        if (aNum !== bNum) {
                            return aNum - bNum;
                        }
                        const aTitle = String(a.title || '');
                        const bTitle = String(b.title || '');
                        if (aTitle !== bTitle) {
                            return aTitle.localeCompare(bTitle, 'fi');
                        }
                        return aNum - bNum;
                    });
                return sorted;
            },
            visibleCards() {
                if (this.groupingEnabled) {
                    return this.filteredCards;
                }
                const limit = this.renderCount || this.renderBatchSize;
                return this.filteredCards.slice(0, limit);
            },
            hasMoreCards() {
                if (this.groupingEnabled) {
                    return false;
                }
                return this.visibleCards.length < this.filteredCards.length;
            },
            hasVisibleDivisions() {
                return this.filteredCards.length > 0;
            },
            visibleDivisionGroups() {
                if (!this.groupingEnabled) {
                    return [];
                }
                const source = Array.isArray(this.visibleCards) ? this.visibleCards : [];
                const allSource = Array.isArray(this.filteredCards) ? this.filteredCards : [];
                const visibleGroups = buildDivisionNumberGroups(source);
                const allGroups = buildDivisionNumberGroups(allSource);
                const totalsByRange = new Map(allGroups.map(group => [group.rangeLabel, group]));

                return visibleGroups.map(group => {
                    const totalGroup = totalsByRange.get(group.rangeLabel) || group;
                    const completed = (totalGroup.cards || []).filter(entry => entry?.state === DivisionStatus.COMPLETE).length;
                    const progress = buildGroupProgress(totalGroup.cards || group.cards);
                    return {
                        ...group,
                        totalCount: totalGroup.cards?.length || group.cards.length,
                        completedCount: completed,
                        progress
                    };
                });
            }
        },
        watch: {
            divisions: {
                immediate: true,
                handler() {
                    this.teamCountOverrides = {};
                    this.teamCountRequests = {};
                    this.syncGroupCollapseState();
                    this.resetVirtualWindow();
                }
            },
            filterState() {
                this.syncGroupCollapseState();
                this.resetVirtualWindow();
            },
            searchQuery() {
                this.syncGroupCollapseState();
                this.resetVirtualWindow();
            },
            cardModels() {},
            filteredCards(newValue) {
                if (!this.groupingEnabled) {
                    this.$nextTick(() => this.observeSentinel());
                }
            },
            visibleCards: {
                immediate: true,
                handler(newValue) {
                    this.ensureTeamCounts(newValue);
                }
            },
            visibleDivisionGroups: {
                immediate: true,
                handler() {
                    this.syncGroupCollapseState();
                }
            }
        },
        mounted() {
            this.initSentinelObserver();
            this.$nextTick(() => this.resetVirtualWindow());
        },
        beforeUnmount() {
            this.teardownSentinelObserver();
        },
        methods: {
            handleSeasonChange(value) {
                this.$emit('change-season', value);
            },
            handleFilterChange(value) {
                this.$emit('change-filter', value);
            },
            handleSearch(value) {
                this.$emit('change-search', value);
            },
            handleReset() {
                this.$emit('reset-filters');
            },
            syncGroupCollapseState() {
                if (!this.groupingEnabled || !this.collapsibleEnabled) {
                    this.collapsedGroupIds = [];
                    this.knownGroupIds = [];
                    return;
                }
                const validIds = (this.visibleDivisionGroups || []).map(group => group.id);
                if (!validIds.length) {
                    this.collapsedGroupIds = [];
                    this.knownGroupIds = [];
                    return;
                }
                const knownSet = new Set(this.knownGroupIds || []);
                const collapsedSet = new Set(
                    (this.collapsedGroupIds || []).filter(id => validIds.includes(id))
                );
                validIds.forEach(id => {
                    if (!knownSet.has(id)) {
                        collapsedSet.add(id);
                    }
                });
                this.collapsedGroupIds = validIds.filter(id => collapsedSet.has(id));
                this.knownGroupIds = [...validIds];
            },
            toggleGroup(groupId) {
                if (!this.collapsibleEnabled) {
                    return;
                }
                if (this.collapsedGroupIds.includes(groupId)) {
                    this.collapsedGroupIds = this.collapsedGroupIds.filter(id => id !== groupId);
                    return;
                }
                this.collapsedGroupIds = [...this.collapsedGroupIds, groupId];
            },
            isGroupCollapsed(groupId) {
                return this.collapsibleEnabled && this.collapsedGroupIds.includes(groupId);
            },
            ensureTeamCounts(cards) {
                if (typeof window === 'undefined' || !window.apiClient) {
                    return;
                }
                if (!Array.isArray(cards) || !cards.length) {
                    return;
                }
                cards.forEach(card => {
                    const divisionId = card?.id;
                    if (!divisionId) return;
                    if (this.teamCountOverrides[divisionId] !== undefined) return;
                    if (this.teamCountRequests[divisionId]) return;
                    this.teamCountRequests[divisionId] = true;
                    window.apiClient
                        .getDivisionTeamCount(divisionId)
                        .then(count => {
                            if (!Number.isFinite(count)) return;
                            this.teamCountOverrides[divisionId] = count;
                        })
                        .catch(error => {
                            if (isDevEnv) {
                                console.warn('[DivisionCardList] team count fetch failed', { divisionId, error });
                            }
                        })
                        .finally(() => {
                            delete this.teamCountRequests[divisionId];
                        });
                });
            },
            resetVirtualWindow() {
                if (this.groupingEnabled) {
                    this.renderCount = this.filteredCards.length;
                    return;
                }
                if (!Array.isArray(this.filteredCards) || !this.filteredCards.length) {
                    this.renderCount = this.renderBatchSize;
                    this.$nextTick(() => this.observeSentinel());
                    return;
                }
                this.renderCount = Math.min(this.renderBatchSize, this.filteredCards.length);
                this.$nextTick(() => this.observeSentinel());
            },
            increaseRenderCount() {
                if (!this.hasMoreCards) {
                    return;
                }
                const next = Math.min(this.renderCount + this.renderBatchSize, this.filteredCards.length);
                if (next !== this.renderCount) {
                    this.renderCount = next;
                }
            },
            initSentinelObserver() {
                if (this.groupingEnabled) {
                    this.sentinelObserver = null;
                    this.renderCount = this.filteredCards.length || this.renderBatchSize;
                    return;
                }
                if (typeof window === 'undefined' || !('IntersectionObserver' in window)) {
                    this.sentinelObserver = null;
                    this.renderCount = this.filteredCards.length || this.renderBatchSize;
                    return;
                }
                this.sentinelObserver = new IntersectionObserver(entries => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            this.increaseRenderCount();
                        }
                    });
                }, { root: null, rootMargin: '0px 0px 200px 0px', threshold: 0 });
            },
            observeSentinel() {
                if (!this.sentinelObserver) {
                    return;
                }
                const el = this.$refs?.sentinel;
                this.sentinelObserver.disconnect();
                if (el) {
                    this.sentinelObserver.observe(el);
                }
            },
            teardownSentinelObserver() {
                if (this.sentinelObserver) {
                    this.sentinelObserver.disconnect();
                    this.sentinelObserver = null;
                }
            },
            rememberDivision(id) {
                if (!id) return;
                this.preferredDivisionId = id;
                storeDivisionId(id);
            }
        },
        template: `
            <div class="division-hub">
                <season-bar
                    v-if="showControls"
                    :season-options="seasonOptions"
                    :selected-season="selectedSeason"
                    :season-loading="seasonLoading"
                    :filter-state="filterState"
                    :search-query="searchQuery"
                    :show-season-picker="showSeasonPicker"
                    @change-season="handleSeasonChange"
                    @change-filter="handleFilterChange"
                    @change-search="handleSearch"
                    @reset-filters="handleReset"
                ></season-bar>
                <div v-if="offlineMessage" class="offline-banner" role="status" aria-live="polite">{{ offlineMessage }}</div>
                <div v-if="dataBadge" class="dev-data-badge badge-small" role="status" aria-live="polite">{{ dataBadge }}</div>
                <div v-if="warningMessage" class="inline-toast" role="status" aria-live="polite">{{ warningMessage }}</div>
                <template v-if="isLoading">
                    <div class="division-hub__skeletons" role="status" aria-live="polite">
                        <article v-for="n in 3" :key="n" class="division-card division-card--skeleton"></article>
                    </div>
                </template>
                <template v-else-if="hasVisibleDivisions">
                    <template v-if="groupingEnabled">
                        <section
                            v-for="group in visibleDivisionGroups"
                            :key="'group-' + group.id"
                            class="tier-section"
                        >
                            <button
                                v-if="collapsibleEnabled"
                                type="button"
                                class="tier-section__toggle"
                                :aria-expanded="!isGroupCollapsed(group.id)"
                                @click="toggleGroup(group.id)"
                            >
                                <span class="tier-section__header">
                                    <span class="tier-section__title">{{ group.label }}</span>
                                    <span class="tier-section__subtitle">{{ group.totalCount }} divisioonaa · {{ group.completedCount }} valmiina</span>
                                    <span class="tier-section__pills" aria-hidden="true">
                                        <span class="tier-section__pill">Näkyvissä {{ group.cards.length }}</span>
                                        <span class="tier-section__pill">Valmiit {{ group.completedCount }}/{{ group.totalCount }}</span>
                                    </span>
                                </span>
                                <span
                                    v-if="isGroupCollapsed(group.id)"
                                    class="tier-section__quick-progress"
                                    aria-hidden="true"
                                >
                                    <circular-progress
                                        :value="group.progress.regular.played"
                                        :max="group.progress.regular.total"
                                        :label="group.progress.regular.label"
                                        :color="group.progress.regular.color"
                                        :size="52"
                                        :stroke-width="6"
                                    ></circular-progress>
                                    <circular-progress
                                        :value="group.progress.playoff.played"
                                        :max="group.progress.playoff.total"
                                        :label="group.progress.playoff.label"
                                        :color="group.progress.playoff.color"
                                        :size="52"
                                        :stroke-width="6"
                                    ></circular-progress>
                                    <circular-progress
                                        :value="group.progress.overall.played"
                                        :max="group.progress.overall.total"
                                        :label="group.progress.overall.label"
                                        :color="group.progress.overall.color"
                                        :size="52"
                                        :stroke-width="6"
                                    ></circular-progress>
                                </span>
                                <span class="tier-section__chevron" :class="{ 'is-open': !isGroupCollapsed(group.id) }" aria-hidden="true">
                                    <svg viewBox="0 0 24 24" role="presentation" focusable="false">
                                        <path d="M7 10l5 5 5-5z"></path>
                                    </svg>
                                </span>
                            </button>
                            <div v-else class="tier-section__header">
                                <span class="tier-section__title">{{ group.label }}</span>
                                <span class="tier-section__subtitle">{{ group.totalCount }} divisioonaa · {{ group.completedCount }} valmiina</span>
                            </div>
                            <div v-if="!isGroupCollapsed(group.id)" class="tier-section__body">
                                <div class="division-list" role="list">
                                    <division-card
                                        v-for="division in group.cards"
                                        :key="division.id"
                                        :division="division"
                                        @remember="rememberDivision"
                                    ></division-card>
                                </div>
                            </div>
                        </section>
                    </template>
                    <div v-else class="division-list" role="list">
                        <division-card
                            v-for="division in visibleCards"
                            :key="division.id"
                            :division="division"
                            @remember="rememberDivision"
                        ></division-card>
                    </div>
                    <div
                        v-if="hasMoreCards"
                        ref="sentinel"
                        class="division-list__sentinel"
                        aria-hidden="true"
                    ></div>
                </template>
                <p v-else class="division-hub__empty">{{ emptyMessage }}</p>
            </div>
        `
    };
})();


/* === /static/components/SparklineChart.js === */
window.SparklineChart = {
    name: 'SparklineChart',
    props: {
        points: {
            type: Array,
            default: () => []
        },
        width: {
            type: Number,
            default: 160
        },
        height: {
            type: Number,
            default: 60
        },
        strokeWidth: {
            type: Number,
            default: 3
        },
        positiveColor: {
            type: String,
            default: '#5ad4ff'
        },
        negativeColor: {
            type: String,
            default: '#7dd3fc'
        }
    },
    computed: {
        path() {
            if (!Array.isArray(this.points) || !this.points.length) {
                return '';
            }
            const step = this.points.length > 1 ? this.width / (this.points.length - 1) : this.width;
            return this.points
                .map((value, index) => {
                    const normalized = Math.max(-1, Math.min(1, Number(value)));
                    const x = index * step;
                    const y = this.height - (normalized + 1) * (this.height / 2);
                    return `${index === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${y.toFixed(2)}`;
                })
                .join(' ');
        }
    },
    template: `
        <svg
            v-if="path"
            :viewBox="'0 0 ' + width + ' ' + height"
            preserveAspectRatio="none"
            class="sparkline-chart"
        >
            <defs>
                <linearGradient :id="$attrs.id || 'sparklineGradient'" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" :stop-color="positiveColor" />
                    <stop offset="100%" :stop-color="negativeColor" />
                </linearGradient>
            </defs>
            <path :d="path" fill="none" :stroke="'url(#' + ($attrs.id || 'sparklineGradient') + ')'" :stroke-width="strokeWidth" />
        </svg>
    `
};



/* === /static/components/RadarChart.js === */
window.RadarChart = {
    name: 'RadarChart',
    props: {
        metrics: {
            type: Array,
            default: () => []
        },
        comparisons: {
            type: Array,
            default: () => []
        },
        radius: {
            type: Number,
            default: 90
        },
        levels: {
            type: Number,
            default: 4
        },
        autoScale: {
            type: Boolean,
            default: true
        }
    },
    data() {
        return {
            containerWidth: 0,
            containerHeight: 0,
            pointTooltip: {
                visible: false,
                x: 0,
                y: 0,
                title: '',
                value: ''
            }
        };
    },
    computed: {
        chartSize() {
            const size = Math.min(this.containerWidth || 0, this.containerHeight || 0);
            if (size > 0) return size;
            return Math.max(160, this.radius * 2 + 40);
        },
        chartCenter() {
            return this.chartSize / 2;
        },
        radiusValue() {
            if (this.autoScale) {
                return Math.max(24, this.chartSize * 0.42);
            }
            return Math.min(this.radius, this.chartSize * 0.45);
        },
        labelOffset() {
            return Math.max(10, this.chartSize * 0.08);
        },
        normalizedMetrics() {
            return (this.metrics || []).map(metric => {
                const staticMax = Number(metric.max);
                const value = Number(metric.value) || 0;
                let max = Number.isFinite(staticMax) && staticMax > 0 ? staticMax : 1;
                if (metric.dynamicMax) {
                    const comparisonValues = (this.comparisons || [])
                        .map(series => Number(series?.values?.[metric.key]))
                        .filter(Number.isFinite);
                    const highestValue = Math.max(value, ...comparisonValues, 0);
                    const headroom = Number(metric.dynamicHeadroom);
                    const growthFactor = Number.isFinite(headroom) && headroom > 1 ? headroom : 1.15;
                    const minMax = Number(metric.dynamicMinMax);
                    const dynamicFloor = Number.isFinite(minMax) && minMax > 0 ? minMax : 1;
                    // Use a sensible floor for low-count metrics, but still scale up for larger seasons.
                    max = Math.max(dynamicFloor, highestValue * growthFactor);
                }
                return {
                    key: String(metric.key || ''),
                    label: metric.label || '',
                    value,
                    max,
                    decimals: Number.isInteger(metric.decimals) ? metric.decimals : 1,
                    percent: Boolean(metric.percent),
                    ratio: max > 0 ? Math.max(0, Math.min(1, value / max)) : 0
                };
            });
        },
        normalizedComparisons() {
            if (!Array.isArray(this.comparisons) || !this.comparisons.length || !this.normalizedMetrics.length) {
                return [];
            }
            return this.comparisons.map((series, idx) => {
                const values = series?.values && typeof series.values === 'object' ? series.values : {};
                const points = this.normalizedMetrics.map(metric => {
                    const raw = Number(values[metric.key]);
                    const value = Number.isFinite(raw) ? raw : 0;
                    const ratio = metric.max > 0 ? Math.max(0, Math.min(1, value / metric.max)) : 0;
                    return {
                        key: metric.key,
                        value,
                        ratio
                    };
                });
                const color = series?.color || '#60a5fa';
                return {
                    key: String(series?.key || `comparison-${idx}`),
                    label: String(series?.label || `Comparison ${idx + 1}`),
                    color,
                    points
                };
            });
        },
        metricComparisonRows() {
            if (!this.normalizedMetrics.length) return [];
            const seriesByKey = new Map(this.normalizedComparisons.map(series => [series.key, series]));
            const divisionSeries = seriesByKey.get('division_median') || this.normalizedComparisons[0] || null;
            const seasonSeries = seriesByKey.get('season_median') || this.normalizedComparisons[1] || null;
            const buildPointMap = series => new Map((series?.points || []).map(item => [item.key, item.value]));
            const divisionMap = buildPointMap(divisionSeries);
            const seasonMap = buildPointMap(seasonSeries);
            const buildDiff = (base, compare, fmt) => {
                const diff = Number(base || 0) - Number(compare || 0);
                const sign = diff > 0 ? '+' : diff < 0 ? '-' : '';
                return {
                    label: `${sign}${fmt(Math.abs(diff))}`,
                    className: diff > 0 ? 'is-pos' : diff < 0 ? 'is-neg' : 'is-zero'
                };
            };

            return this.normalizedMetrics.map(metric => {
                const decimals = Number.isInteger(metric.decimals) ? metric.decimals : 1;
                const percent = Boolean(metric.percent);
                const fmt = value => {
                    const numeric = Number(value || 0);
                    if (percent) return `${numeric.toFixed(decimals)}%`;
                    return numeric.toFixed(decimals);
                };
                const divisionValue = Number(divisionMap.get(metric.key) || 0);
                const seasonValue = Number(seasonMap.get(metric.key) || 0);
                const divisionDiff = buildDiff(metric.value, divisionValue, fmt);
                const seasonDiff = buildDiff(metric.value, seasonValue, fmt);
                return {
                    key: metric.key,
                    label: metric.label,
                    playerLabel: fmt(metric.value),
                    divisionLabel: fmt(divisionValue),
                    seasonLabel: fmt(seasonValue),
                    divisionDiffLabel: divisionDiff.label,
                    divisionDiffClass: divisionDiff.className,
                    seasonDiffLabel: seasonDiff.label,
                    seasonDiffClass: seasonDiff.className
                };
            });
        },
        polygonPoints() {
            if (!this.normalizedMetrics.length) return '';
            const angleStep = (Math.PI * 2) / this.normalizedMetrics.length;
            return this.normalizedMetrics
                .map((metric, index) => {
                    const angle = angleStep * index - Math.PI / 2;
                    const r = this.radiusValue * metric.ratio;
                    const x = this.chartCenter + r * Math.cos(angle);
                    const y = this.chartCenter + r * Math.sin(angle);
                    return `${x.toFixed(2)},${y.toFixed(2)}`;
                })
                .join(' ');
        },
        gridLevels() {
            return Array.from({ length: this.levels }, (_, idx) => (idx + 1) / this.levels);
        }
    },
    template: `
        <div ref="container" class="radar-chart__wrap">
            <svg v-if="normalizedMetrics.length" :viewBox="'0 0 ' + chartSize + ' ' + chartSize" class="radar-chart">
                <g v-for="level in gridLevels" :key="'grid-' + level" class="radar-chart__grid">
                    <polygon :points="gridPolygon(level)" fill="none" stroke="rgba(150, 200, 255, 0.4)" stroke-width="1" />
                </g>
                <g v-for="series in normalizedComparisons" :key="series.key">
                    <polygon
                        class="radar-chart__comparison"
                        :points="comparisonPolygonPoints(series)"
                        :fill="withAlpha(series.color, 0.09)"
                        :stroke="withAlpha(series.color, 0.92)"
                        :stroke-dasharray="comparisonStrokeDash(series)"
                        stroke-width="2"
                    />
                    <circle
                        v-for="(point, pointIndex) in series.points"
                        :key="series.key + '-pt-' + pointIndex"
                        class="radar-chart__point radar-chart__point--comparison"
                        :cx="metricPoint(pointIndex, point.ratio).x"
                        :cy="metricPoint(pointIndex, point.ratio).y"
                        r="2.6"
                        :fill="series.color"
                        :stroke="withAlpha(series.color, 0.98)"
                        stroke-width="1"
                        @mouseenter="showPointTooltip($event, series.label, normalizedMetrics[pointIndex], point.value)"
                        @mousemove="movePointTooltip($event)"
                        @mouseleave="hidePointTooltip"
                    ></circle>
                </g>
                <polygon
                    class="radar-chart__shape"
                    :points="polygonPoints"
                    fill="rgba(90, 160, 255, 0.2)"
                    stroke="rgba(170, 220, 255, 0.95)"
                    stroke-width="2"
                />
                <circle
                    v-for="(metric, index) in normalizedMetrics"
                    :key="'player-pt-' + metric.key + '-' + index"
                    class="radar-chart__point radar-chart__point--player"
                    :cx="metricPoint(index, metric.ratio).x"
                    :cy="metricPoint(index, metric.ratio).y"
                    r="3.1"
                    fill="#60a5fa"
                    stroke="rgba(214, 235, 255, 0.95)"
                    stroke-width="1.2"
                    @mouseenter="showPointTooltip($event, 'Pelaaja', metric, metric.value)"
                    @mousemove="movePointTooltip($event)"
                    @mouseleave="hidePointTooltip"
                ></circle>
                <g v-for="(metric, index) in normalizedMetrics" :key="metric.label || index">
                    <line
                        class="radar-chart__axis"
                        :x1="chartCenter"
                        :y1="chartCenter"
                        :x2="axisPoint(index).x"
                        :y2="axisPoint(index).y"
                        stroke="rgba(150, 180, 255, 0.45)"
                        stroke-width="1"
                    />
                    <text
                        class="radar-chart__label"
                        :x="axisLabelPoint(index).x"
                        :y="axisLabelPoint(index).y"
                        dominant-baseline="middle"
                    >
                        {{ metric.label }}
                    </text>
                </g>
            </svg>
            <div v-if="normalizedComparisons.length" class="radar-chart__legend">
                <span class="radar-chart__legend-item">
                    <i class="radar-chart__legend-dot" style="background: #60a5fa;"></i>
                    Pelaaja
                </span>
                <span v-for="series in normalizedComparisons" :key="'legend-' + series.key" class="radar-chart__legend-item">
                    <i class="radar-chart__legend-dot" :style="{ background: series.color }"></i>
                    {{ series.label }}
                </span>
            </div>
            <div v-if="metricComparisonRows.length" class="radar-chart__metric-values">
                <div class="radar-chart__metric-table">
                    <div class="radar-chart__metric-head radar-chart__metric-grid">
                        <span class="radar-chart__metric-col radar-chart__metric-col--name">Metric</span>
                        <span class="radar-chart__metric-col">P</span>
                        <span class="radar-chart__metric-col">D</span>
                        <span class="radar-chart__metric-col">ΔD</span>
                        <span class="radar-chart__metric-col">S</span>
                        <span class="radar-chart__metric-col">ΔS</span>
                    </div>
                    <div
                        v-for="row in metricComparisonRows"
                        :key="'mv-' + row.key"
                        class="radar-chart__metric-line radar-chart__metric-grid"
                    >
                        <span class="radar-chart__metric-col radar-chart__metric-col--name">{{ row.label }}</span>
                        <span class="radar-chart__metric-col radar-chart__metric-col--player">{{ row.playerLabel }}</span>
                        <span class="radar-chart__metric-col radar-chart__metric-col--division">{{ row.divisionLabel }}</span>
                        <span class="radar-chart__metric-col radar-chart__metric-diff" :class="row.divisionDiffClass">{{ row.divisionDiffLabel }}</span>
                        <span class="radar-chart__metric-col radar-chart__metric-col--season">{{ row.seasonLabel }}</span>
                        <span class="radar-chart__metric-col radar-chart__metric-diff" :class="row.seasonDiffClass">{{ row.seasonDiffLabel }}</span>
                    </div>
                </div>
            </div>
            <div
                v-if="pointTooltip.visible"
                class="radar-chart__tooltip"
                :style="{ left: pointTooltip.x + 'px', top: pointTooltip.y + 'px' }"
            >
                <div class="radar-chart__tooltip-title">{{ pointTooltip.title }}</div>
                <div class="radar-chart__tooltip-value">{{ pointTooltip.value }}</div>
            </div>
        </div>
    `,
    methods: {
        withAlpha(color, alpha) {
            if (typeof color !== 'string') return color;
            const hex = color.trim();
            if (/^#([0-9a-fA-F]{6})$/.test(hex)) {
                const r = parseInt(hex.slice(1, 3), 16);
                const g = parseInt(hex.slice(3, 5), 16);
                const b = parseInt(hex.slice(5, 7), 16);
                return `rgba(${r}, ${g}, ${b}, ${alpha})`;
            }
            return color;
        },
        comparisonPolygonPoints(series) {
            if (!series || !Array.isArray(series.points) || !series.points.length) return '';
            const angleStep = (Math.PI * 2) / series.points.length;
            return series.points
                .map((metric, index) => {
                    const angle = angleStep * index - Math.PI / 2;
                    const r = this.radiusValue * metric.ratio;
                    const x = this.chartCenter + r * Math.cos(angle);
                    const y = this.chartCenter + r * Math.sin(angle);
                    return `${x.toFixed(2)},${y.toFixed(2)}`;
                })
                .join(' ');
        },
        comparisonStrokeDash(series) {
            const key = String(series?.key || '');
            if (key === 'division_median') return '0';
            if (key === 'season_median') return '6 4';
            return '3 3';
        },
        metricPoint(index, ratio) {
            const angle = (Math.PI * 2 * index) / this.normalizedMetrics.length - Math.PI / 2;
            const r = this.radiusValue * ratio;
            return {
                x: this.chartCenter + r * Math.cos(angle),
                y: this.chartCenter + r * Math.sin(angle)
            };
        },
        formatMetricValue(metric, value) {
            const decimals = Number.isInteger(metric?.decimals) ? metric.decimals : 1;
            const numeric = Number(value || 0);
            if (metric?.percent) {
                return `${numeric.toFixed(decimals)}%`;
            }
            return numeric.toFixed(decimals);
        },
        showPointTooltip(event, seriesLabel, metric, value) {
            if (!event) return;
            this.pointTooltip.visible = true;
            this.pointTooltip.title = `${seriesLabel} - ${metric?.label || ''}`;
            this.pointTooltip.value = this.formatMetricValue(metric, value);
            this.movePointTooltip(event);
        },
        movePointTooltip(event) {
            if (!event || !this.$refs.container) return;
            const rect = this.$refs.container.getBoundingClientRect();
            const rawX = (event.clientX - rect.left) + 10;
            const rawY = (event.clientY - rect.top) - 12;
            const maxX = Math.max(16, rect.width - 12);
            const maxY = Math.max(16, rect.height - 12);
            this.pointTooltip.x = Math.min(maxX, Math.max(12, rawX));
            this.pointTooltip.y = Math.min(maxY, Math.max(12, rawY));
        },
        hidePointTooltip() {
            this.pointTooltip.visible = false;
        },
        axisPoint(index) {
            const angle = (Math.PI * 2 * index) / this.normalizedMetrics.length - Math.PI / 2;
            return {
                x: this.chartCenter + this.radiusValue * Math.cos(angle),
                y: this.chartCenter + this.radiusValue * Math.sin(angle)
            };
        },
        axisLabelPoint(index) {
            const angle = (Math.PI * 2 * index) / this.normalizedMetrics.length - Math.PI / 2;
            const distance = this.radiusValue + this.labelOffset;
            const clamp = (value, min, max) => Math.min(Math.max(value, min), max);
            const padding = Math.max(6, this.chartSize * 0.03);
            return {
                x: clamp(this.chartCenter + distance * Math.cos(angle), padding, this.chartSize - padding),
                y: clamp(this.chartCenter + distance * Math.sin(angle), padding, this.chartSize - padding)
            };
        },
        gridPolygon(level) {
            if (!this.normalizedMetrics.length) return '';
            const angleStep = (Math.PI * 2) / this.normalizedMetrics.length;
            return this.normalizedMetrics
                .map((_, index) => {
                    const angle = angleStep * index - Math.PI / 2;
                    const r = this.radiusValue * level;
                    const x = this.chartCenter + r * Math.cos(angle);
                    const y = this.chartCenter + r * Math.sin(angle);
                    return `${x.toFixed(2)},${y.toFixed(2)}`;
                })
                .join(' ');
        },
        updateSize() {
            if (!this.$refs.container) return;
            const rect = this.$refs.container.getBoundingClientRect();
            this.containerWidth = rect.width;
            this.containerHeight = rect.height;
        }
    },
    mounted() {
        this.updateSize();
        if (typeof ResizeObserver !== 'undefined') {
            this._resizeObserver = new ResizeObserver(() => this.updateSize());
            this._resizeObserver.observe(this.$refs.container);
        } else {
            this._resizeHandler = () => this.updateSize();
            window.addEventListener('resize', this._resizeHandler);
        }
    },
    beforeUnmount() {
        if (this._resizeObserver) {
            this._resizeObserver.disconnect();
            this._resizeObserver = null;
        }
        if (this._resizeHandler) {
            window.removeEventListener('resize', this._resizeHandler);
            this._resizeHandler = null;
        }
    }
};



/* === /static/components/DivisionPlayersTable.js === */
(function () {
    const ALL_COLUMNS = [
        { key: '_rank',         label: '#',        group: null,       sortable: false, numeric: true,  align: 'right', width: '42px' },
        { key: 'nickname',      label: 'Pelaaja',  group: 'core',     sortable: true,  numeric: false, align: 'left',  width: '150px' },
        { key: 'team_name',     label: 'Joukkue',  group: 'core',     sortable: true,  numeric: false, align: 'left',  width: '130px' },
        { key: 'maps_played',   label: 'Kartat',   group: 'core',     sortable: true,  numeric: true,  width: '70px' },
        { key: 'kills',         label: 'Kills',    group: 'core',     sortable: true,  numeric: true,  width: '70px' },
        { key: 'assists',       label: 'Assists',  group: 'extended', sortable: true,  numeric: true,  width: '78px' },
        { key: 'deaths',        label: 'Deaths',   group: 'core',     sortable: true,  numeric: true,  width: '74px' },
        { key: 'kd',            label: 'K/D',      group: 'core',     sortable: true,  numeric: true,  decimals: 2, width: '72px' },
        { key: 'adr',           label: 'ADR',      group: 'core',     sortable: true,  numeric: true,  decimals: 1, width: '72px' },
        { key: 'kr',            label: 'K/R',      group: 'core',     sortable: true,  numeric: true,  decimals: 2, width: '72px' },
        { key: 'hs_pct',        label: 'HS%',      group: 'core',     sortable: true,  numeric: true,  decimals: 1, suffix: '%', width: '72px' },
        { key: 'mvps',          label: 'MVPs',     group: 'extended', sortable: true,  numeric: true,  width: '68px' },
        { key: 'utility_damage',label: 'Util DMG', group: 'extended', sortable: true,  numeric: true,  width: '88px' },
        { key: 'clutch_kills',  label: 'Clutch K', group: 'extended', sortable: true,  numeric: true,  width: '84px' },
        { key: 'sniper_kills',  label: 'Sniper K', group: 'extended', sortable: true,  numeric: true,  width: '84px' },
        { key: 'pistol_kills',  label: 'Pistol K', group: 'extended', sortable: true,  numeric: true,  width: '84px' },
        { key: 'damage',        label: 'Damage',   group: 'special',  sortable: true,  numeric: true,  width: '80px' },
        { key: 'rounds_played', label: 'Rounds',   group: 'special',  sortable: true,  numeric: true,  width: '78px' },
        { key: 'knife_kills',   label: 'Knife K',  group: 'special',  sortable: true,  numeric: true,  width: '76px' },
        { key: 'zeus_kills',    label: 'Zeus K',   group: 'special',  sortable: true,  numeric: true,  width: '74px' },
        { key: '_flash_pct',    label: 'Flash%',   group: 'special',  sortable: true,  numeric: true,  decimals: 1, suffix: '%', width: '74px' },
        { key: '_enemy_flash',  label: 'E/Flash',  group: 'special',  sortable: true,  numeric: true,  decimals: 2, width: '82px' },
        { key: '_cl1v1_pct',    label: '1v1 W%',   group: 'special',  sortable: true,  numeric: true,  decimals: 1, suffix: '%', width: '78px' },
        { key: '_cl1v2_pct',    label: '1v2 W%',   group: 'special',  sortable: true,  numeric: true,  decimals: 1, suffix: '%', width: '78px' },
    ];

    const FIXED_COLUMN_KEYS = ['_rank', 'nickname', 'team_name'];
    const DEFAULT_VISIBLE_STAT_KEYS = [
        'maps_played',
        'kills',
        'assists',
        'deaths',
        'kd',
        'adr',
        'kr',
        'hs_pct',
        'mvps',
        'utility_damage',
        'clutch_kills',
        'sniper_kills',
        'pistol_kills',
    ];

    function derivePlayer(p) {
        return {
            ...p,
            _flash_pct:   p.flash_count      ? (p.flash_successes / p.flash_count)      * 100 : 0,
            _enemy_flash: p.flash_count      ? p.enemies_flashed  / p.flash_count             : 0,
            _cl1v1_pct:   p.cl_1v1_attempts  ? (p.cl_1v1_wins     / p.cl_1v1_attempts) * 100 : 0,
            _cl1v2_pct:   p.cl_1v2_attempts  ? (p.cl_1v2_wins     / p.cl_1v2_attempts) * 100 : 0,
        };
    }

    window.DivisionPlayersTable = {
        name: 'DivisionPlayersTable',
        props: {
            players: { type: Array, default: () => [] },
        },
        data() {
            return {
                selectedPlayerIds: new Set(),
                playerDropdownOpen: false,
                columnDropdownOpen: false,
                dropdownSearch: '',
                columnSearch: '',
                sortKey: 'kd',
                sortDir: 'desc',
                selectedColumnKeys: new Set(DEFAULT_VISIBLE_STAT_KEYS),
                _outsideClickHandler: null,
            };
        },
        computed: {
            teamList() {
                const seen = new Map();
                for (const p of (this.players || [])) {
                    const id = String(p.team_id || '');
                    if (id && !seen.has(id)) {
                        seen.set(id, p.team_name || id);
                    }
                }
                return Array.from(seen.entries())
                    .map(([id, name]) => ({ id, name }))
                    .sort((a, b) => a.name.localeCompare(b.name, 'fi'));
            },
            playersByTeam() {
                const map = {};
                for (const p of (this.players || [])) {
                    const tid = String(p.team_id || '');
                    if (!map[tid]) map[tid] = [];
                    map[tid].push(p);
                }
                return map;
            },
            selectedCount() {
                return this.selectedPlayerIds.size;
            },
            totalCount() {
                return (this.players || []).length;
            },
            playerDropdownSummary() {
                const sel = this.selectedCount;
                const total = this.totalCount;
                if (sel === total) return `Kaikki ${total} pelaajaa`;
                return `${sel} / ${total} pelaajaa`;
            },
            allTeamsState() {
                if (this.selectedCount === 0) return 'none';
                if (this.selectedCount === this.totalCount) return 'all';
                return 'partial';
            },
            dropdownPlayers() {
                const needle = this.dropdownSearch.trim().toLowerCase();
                const list = (this.players || []).slice().sort((a, b) => {
                    const ta = (a.team_name || '').localeCompare(b.team_name || '', 'fi');
                    if (ta !== 0) return ta;
                    return (a.nickname || '').localeCompare(b.nickname || '', 'fi');
                });
                if (!needle) return list;
                return list.filter(p => (p.nickname || '').toLowerCase().includes(needle));
            },
            statColumns() {
                return ALL_COLUMNS.filter(col => !FIXED_COLUMN_KEYS.includes(col.key));
            },
            totalStatCount() {
                return this.statColumns.length;
            },
            selectedStatCount() {
                return this.selectedColumnKeys.size;
            },
            columnDropdownSummary() {
                const selected = this.selectedStatCount;
                const total = this.totalStatCount;
                if (selected === total) return `Kaikki ${total} statia`;
                return `${selected} / ${total} statia`;
            },
            dropdownColumns() {
                const needle = this.columnSearch.trim().toLowerCase();
                if (!needle) return this.statColumns;
                return this.statColumns.filter(col => String(col.label || '').toLowerCase().includes(needle));
            },
            sortedFilteredPlayers() {
                const active = (this.players || [])
                    .filter(p => this.selectedPlayerIds.has(String(p.player_id)))
                    .map(derivePlayer);

                const key = this.sortKey;
                const dir = this.sortDir;

                return active.slice().sort((a, b) => {
                    const av = a[key];
                    const bv = b[key];
                    if (av == null && bv == null) return 0;
                    if (av == null) return 1;
                    if (bv == null) return -1;
                    let cmp;
                    if (typeof av === 'number' && typeof bv === 'number') {
                        cmp = av - bv;
                    } else {
                        cmp = String(av).localeCompare(String(bv), 'fi');
                    }
                    return dir === 'desc' ? -cmp : cmp;
                });
            },
            visibleColumns() {
                return ALL_COLUMNS.filter(col => FIXED_COLUMN_KEYS.includes(col.key) || this.selectedColumnKeys.has(col.key));
            },
        },
        watch: {
            players: {
                immediate: false,
                handler() {
                    this.selectedPlayerIds = new Set();
                },
            },
        },
        methods: {
            teamSelectionState(teamId) {
                const players = this.playersByTeam[teamId] || [];
                if (!players.length) return 'none';
                const selected = players.filter(p => this.selectedPlayerIds.has(String(p.player_id))).length;
                if (selected === 0) return 'none';
                if (selected === players.length) return 'all';
                return 'partial';
            },
            teamStateIcon(state) {
                if (state === 'all') return '✓';
                if (state === 'partial') return '◑';
                return '';
            },
            toggleTeam(teamId) {
                const state = this.teamSelectionState(teamId);
                const players = this.playersByTeam[teamId] || [];
                const newSet = new Set(this.selectedPlayerIds);
                if (state === 'all' || state === 'partial') {
                    players.forEach(p => newSet.delete(String(p.player_id)));
                } else {
                    players.forEach(p => newSet.add(String(p.player_id)));
                }
                this.selectedPlayerIds = newSet;
            },
            toggleAllPlayers() {
                if (this.selectedCount === this.totalCount) {
                    this.selectedPlayerIds = new Set();
                } else {
                    this.selectedPlayerIds = new Set((this.players || []).map(p => String(p.player_id)));
                }
            },
            togglePlayer(playerId) {
                const id = String(playerId);
                const newSet = new Set(this.selectedPlayerIds);
                if (newSet.has(id)) {
                    newSet.delete(id);
                } else {
                    newSet.add(id);
                }
                this.selectedPlayerIds = newSet;
            },
            ensureSortKeyVisible(columnKeys) {
                if (FIXED_COLUMN_KEYS.includes(this.sortKey) || columnKeys.has(this.sortKey)) {
                    return;
                }
                const fallback = DEFAULT_VISIBLE_STAT_KEYS.find(key => columnKeys.has(key))
                    || this.statColumns.find(col => columnKeys.has(col.key))?.key
                    || 'nickname';
                this.sortKey = fallback;
                this.sortDir = fallback === 'nickname' ? 'asc' : 'desc';
            },
            toggleColumn(columnKey) {
                const key = String(columnKey);
                const newSet = new Set(this.selectedColumnKeys);
                if (newSet.has(key)) {
                    newSet.delete(key);
                } else {
                    newSet.add(key);
                }
                this.ensureSortKeyVisible(newSet);
                this.selectedColumnKeys = newSet;
            },
            toggleAllColumns() {
                const newSet = this.selectedStatCount === this.totalStatCount
                    ? new Set()
                    : new Set(this.statColumns.map(col => col.key));
                this.ensureSortKeyVisible(newSet);
                this.selectedColumnKeys = newSet;
            },
            handleSort(col) {
                if (!col.sortable) return;
                if (this.sortKey === col.key) {
                    this.sortDir = this.sortDir === 'desc' ? 'asc' : 'desc';
                } else {
                    this.sortKey = col.key;
                    this.sortDir = col.numeric !== false ? 'desc' : 'asc';
                }
            },
            sortIndicator(col) {
                if (!col.sortable || this.sortKey !== col.key) return '';
                return this.sortDir === 'desc' ? '▼' : '▲';
            },
            formatCell(player, col) {
                const val = player[col.key];
                if (val == null || (typeof val === 'number' && !Number.isFinite(val))) return '–';
                if (col.decimals != null) {
                    const formatted = Number(val).toFixed(col.decimals);
                    return col.suffix ? formatted + col.suffix : formatted;
                }
                return col.suffix ? String(val) + col.suffix : String(val);
            },
            playerRoute(player) {
                const playerId = player?.player_id || null;
                if (!playerId) return null;
                const championshipId =
                    this.$root?.$route?.params?.championshipId ||
                    this.$root?.$route?.query?.championship ||
                    null;
                return {
                    name: 'player',
                    params: { playerId: String(playerId) },
                    query: championshipId ? { championship: String(championshipId) } : {},
                };
            },
            openDropdown() {
                this.playerDropdownOpen = true;
                this.columnDropdownOpen = false;
                this.$nextTick(() => {
                    const input = this.$el?.querySelector('.dp-dropdown__search');
                    if (input) input.focus();
                });
            },
            closeDropdown() {
                this.playerDropdownOpen = false;
                this.dropdownSearch = '';
            },
            openColumnDropdown() {
                this.columnDropdownOpen = true;
                this.playerDropdownOpen = false;
                this.$nextTick(() => {
                    const input = this.$el?.querySelector('.dp-columns-dropdown .dp-dropdown__search');
                    if (input) input.focus();
                });
            },
            closeColumnDropdown() {
                this.columnDropdownOpen = false;
                this.columnSearch = '';
            },
            handleOutsideClick(e) {
                const playerContainer = this.$el?.querySelector('.dp-players-dropdown');
                const columnContainer = this.$el?.querySelector('.dp-columns-dropdown');
                if (playerContainer && !playerContainer.contains(e.target)) {
                    this.closeDropdown();
                }
                if (columnContainer && !columnContainer.contains(e.target)) {
                    this.closeColumnDropdown();
                }
            },
        },
        mounted() {
            this._outsideClickHandler = this.handleOutsideClick.bind(this);
            document.addEventListener('click', this._outsideClickHandler, { passive: true });
        },
        beforeUnmount() {
            if (this._outsideClickHandler) {
                document.removeEventListener('click', this._outsideClickHandler);
            }
        },
        template: `
            <div class="div-players-table">
                <!-- Team toggle chips -->
                <div class="div-players-teams">
                    <button
                        type="button"
                        class="div-players-team-chip"
                        :class="'is-' + allTeamsState"
                        @click="toggleAllPlayers"
                        title="Valitse tai poista kaikki pelaajat"
                    >
                        <span v-if="allTeamsState !== 'none'" class="team-chip-icon">{{ teamStateIcon(allTeamsState) }}</span>
                        Kaikki
                    </button>
                    <button
                        v-for="team in teamList"
                        :key="team.id"
                        type="button"
                        class="div-players-team-chip"
                        :class="'is-' + teamSelectionState(team.id)"
                        :title="team.name"
                        @click="toggleTeam(team.id)"
                    >
                        <span v-if="teamSelectionState(team.id) !== 'none'" class="team-chip-icon">{{ teamStateIcon(teamSelectionState(team.id)) }}</span>
                        {{ team.name }}
                    </button>
                </div>

                <!-- Controls row: player dropdown + column group toggles -->
                <div class="div-players-controls">
                    <div class="dp-dropdown dp-players-dropdown">
                        <button
                            type="button"
                            class="dp-dropdown__trigger chip"
                            @click.stop="playerDropdownOpen ? closeDropdown() : openDropdown()"
                            :aria-expanded="playerDropdownOpen"
                        >
                            {{ playerDropdownSummary }}
                            <span class="dp-dropdown__arrow">{{ playerDropdownOpen ? '▲' : '▾' }}</span>
                        </button>
                        <div v-if="playerDropdownOpen" class="dp-dropdown__panel glass-card" @click.stop>
                            <div class="dp-dropdown__header">
                                <input
                                    v-model="dropdownSearch"
                                    type="text"
                                    class="dp-dropdown__search"
                                    placeholder="Hae pelaajaa..."
                                    autocomplete="off"
                                />
                                <button type="button" class="dp-dropdown__select-all" @click="toggleAllPlayers">
                                    {{ selectedCount === totalCount ? 'Poista kaikki' : 'Valitse kaikki' }}
                                </button>
                            </div>
                            <div class="dp-dropdown__list">
                                <button
                                    v-for="player in dropdownPlayers"
                                    :key="player.player_id"
                                    type="button"
                                    class="dp-dropdown__item"
                                    :class="{ 'is-selected': selectedPlayerIds.has(String(player.player_id)) }"
                                    @click="togglePlayer(player.player_id)"
                                    :aria-pressed="selectedPlayerIds.has(String(player.player_id))"
                                    :title="(selectedPlayerIds.has(String(player.player_id)) ? 'Poista valinta: ' : 'Valitse: ') + player.nickname"
                                >
                                    <span class="dp-dropdown__check">{{ selectedPlayerIds.has(String(player.player_id)) ? '✓' : '' }}</span>
                                    <span class="dp-dropdown__name">{{ player.nickname }}</span>
                                    <span class="dp-dropdown__team">{{ player.team_name }}</span>
                                </button>
                                <p v-if="dropdownPlayers.length === 0" class="dp-dropdown__empty">Ei tuloksia</p>
                            </div>
                        </div>
                    </div>

                    <div class="dp-dropdown dp-columns-dropdown">
                        <button
                            type="button"
                            class="dp-dropdown__trigger chip"
                            @click.stop="columnDropdownOpen ? closeColumnDropdown() : openColumnDropdown()"
                            :aria-expanded="columnDropdownOpen"
                        >
                            {{ columnDropdownSummary }}
                            <span class="dp-dropdown__arrow">{{ columnDropdownOpen ? '▲' : '▾' }}</span>
                        </button>
                        <div v-if="columnDropdownOpen" class="dp-dropdown__panel dp-dropdown__panel--right glass-card" @click.stop>
                            <div class="dp-dropdown__header">
                                <input
                                    v-model="columnSearch"
                                    type="text"
                                    class="dp-dropdown__search"
                                    placeholder="Hae statia..."
                                    autocomplete="off"
                                />
                                <button type="button" class="dp-dropdown__select-all" @click="toggleAllColumns">
                                    {{ selectedStatCount === totalStatCount ? 'Poista kaikki' : 'Valitse kaikki' }}
                                </button>
                            </div>
                            <div class="dp-dropdown__list">
                                <button
                                    v-for="column in dropdownColumns"
                                    :key="column.key"
                                    type="button"
                                    class="dp-dropdown__item"
                                    :class="{ 'is-selected': selectedColumnKeys.has(column.key) }"
                                    @click="toggleColumn(column.key)"
                                    :aria-pressed="selectedColumnKeys.has(column.key)"
                                    :title="(selectedColumnKeys.has(column.key) ? 'Piilota: ' : 'Näytä: ') + column.label"
                                >
                                    <span class="dp-dropdown__check">{{ selectedColumnKeys.has(column.key) ? '✓' : '' }}</span>
                                    <span class="dp-dropdown__name">{{ column.label }}</span>
                                    <span class="dp-dropdown__team">{{ column.group === 'core' ? 'Ydin' : (column.group === 'extended' ? 'Lisä' : 'Erik.') }}</span>
                                </button>
                                <p v-if="dropdownColumns.length === 0" class="dp-dropdown__empty">Ei tuloksia</p>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Table -->
                <p v-if="sortedFilteredPlayers.length === 0" class="division-section__empty">
                    Ei pelaajia valittu.
                </p>
                <div v-else class="table-container">
                    <div class="table-wrapper">
                        <table class="table-sortable sticky-header">
                            <colgroup>
                                <col
                                    v-for="col in visibleColumns"
                                    :key="col.key"
                                    :style="col.width ? 'width:' + col.width : undefined"
                                />
                            </colgroup>
                            <thead>
                                <tr>
                                    <th
                                        v-for="col in visibleColumns"
                                        :key="col.key"
                                        :class="{ sortable: col.sortable, active: sortKey === col.key }"
                                        :style="{ textAlign: col.align || (col.numeric ? 'right' : 'left') }"
                                        @click="handleSort(col)"
                                        :title="col.sortable ? 'Lajittele: ' + col.label : col.label"
                                    >
                                        <span class="th-content">
                                            {{ col.label }}
                                            <span v-if="sortIndicator(col)" class="sort-indicator">{{ sortIndicator(col) }}</span>
                                        </span>
                                    </th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-for="(player, idx) in sortedFilteredPlayers" :key="player.player_id">
                                    <td
                                        v-for="col in visibleColumns"
                                        :key="col.key"
                                        :style="{ textAlign: col.align || (col.numeric ? 'right' : 'left') }"
                                    >
                                        <template v-if="col.key === '_rank'">{{ idx + 1 }}</template>
                                        <template v-else-if="col.key === 'nickname'">
                                            <router-link
                                                v-if="playerRoute(player)"
                                                :to="playerRoute(player)"
                                                class="player-link"
                                            >{{ player.nickname }}</router-link>
                                            <span v-else>{{ player.nickname }}</span>
                                        </template>
                                        <template v-else>{{ formatCell(player, col) }}</template>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        `,
    };
})();


