window.PlayerCompareModal = {
    name: 'PlayerCompareModal',
    props: {
        visible: { type: Boolean, default: false },
        basePlayer: { type: Object, default: null },
        basePlayerId: { type: [String, Number], default: null },
        season: { type: [String, Number], default: null },
        division: { type: [String, Number], default: null },
        comparePlayer: { type: Object, default: null },
        metrics: { type: Array, default: () => [] },
        loading: { type: Boolean, default: false },
        error: { type: String, default: null }
    },
    emits: ['close', 'submit'],
    data() {
        return {
            searchQuery: '',
            selectedCandidateId: '',
            candidates: [],
            loadingCandidates: false,
            candidatesError: null,
            debounceTimer: null
        };
    },
    computed: {
        normalizedBasePlayerId() {
            const value = this.basePlayerId ?? this.basePlayer?.player_id ?? this.basePlayer?.playerId ?? null;
            return value == null ? '' : String(value);
        },
        normalizedCandidates() {
            const baseId = this.normalizedBasePlayerId;
            return (Array.isArray(this.candidates) ? this.candidates : [])
                .filter(item => {
                    const pid = this.playerId(item);
                    if (!pid) return false;
                    return String(pid) !== String(baseId);
                })
                .map(item => ({
                    player_id: String(this.playerId(item)),
                    nickname: this.playerName(item),
                    avatar: this.proxyAvatar(this.playerAvatar(item))
                }));
        },
        filteredCandidates() {
            const list = this.normalizedCandidates;
            const needle = String(this.searchQuery || '').trim().toLowerCase();
            if (!needle) return list.slice(0, 50);
            return list
                .filter(item => {
                    const name = String(item.nickname || '').toLowerCase();
                    return name.includes(needle);
                })
                .slice(0, 100);
        },
        selectedCandidate() {
            if (!this.resolvedCandidateId) return null;
            return this.normalizedCandidates.find(item => String(item.player_id) === String(this.resolvedCandidateId)) || null;
        },
        resolvedCandidateId() {
            if (this.selectedCandidateId) return String(this.selectedCandidateId);
            const needle = String(this.searchQuery || '').trim().toLowerCase();
            if (!needle) return '';
            const exact = this.normalizedCandidates.find(item => String(item.nickname || '').trim().toLowerCase() === needle);
            if (!exact) return '';
            return String(exact.player_id || '');
        },
        submitDisabled() {
            if (this.loading || this.loadingCandidates) return true;
            if (!this.resolvedCandidateId) return true;
            return String(this.resolvedCandidateId) === String(this.normalizedBasePlayerId);
        }
    },
    watch: {
        visible(newVal) {
            if (newVal) {
                this.searchQuery = '';
                this.selectedCandidateId = '';
                this.candidatesError = null;
                this.loadCandidates();
            } else {
                this.clearDebounce();
            }
        },
        season() {
            if (this.visible) this.debouncedLoadCandidates();
        },
        division() {
            if (this.visible) this.debouncedLoadCandidates();
        }
    },
    methods: {
        clearDebounce() {
            if (this.debounceTimer) {
                clearTimeout(this.debounceTimer);
                this.debounceTimer = null;
            }
        },
        debouncedLoadCandidates() {
            this.clearDebounce();
            this.debounceTimer = setTimeout(() => {
                this.loadCandidates();
            }, 180);
        },
        async loadCandidates() {
            if (!window.apiClient || typeof window.apiClient.getPlayers !== 'function') {
                this.candidatesError = 'Pelaajahaku ei ole käytettävissä';
                this.candidates = [];
                return;
            }
            this.loadingCandidates = true;
            this.candidatesError = null;
            try {
                const params = {
                    season: null,
                    division: null,
                    limit: 10000
                };
                const rows = await window.apiClient.getPlayers(params);
                this.candidates = Array.isArray(rows)
                    ? [...rows].sort((a, b) => this.playerName(a).localeCompare(this.playerName(b), 'fi'))
                    : [];
            } catch (error) {
                this.candidatesError = error?.message || 'Pelaajalistan lataus epäonnistui';
                this.candidates = [];
            } finally {
                this.loadingCandidates = false;
            }
        },
        playerId(player) {
            return player?.player_id || player?.playerId || null;
        },
        playerName(player) {
            return player?.nickname || player?.name || 'Tuntematon pelaaja';
        },
        playerAvatar(player) {
            return player?.avatar || null;
        },
        proxyAvatar(url) {
            const fallback = window.PAPPALIIGA_DEFAULT_LOGO || '/static/pappaliiga-logo-white-bg.png';
            const src = String(url || '').trim();
            if (!src) return fallback;
            try {
                if (window.apiClient && typeof window.apiClient.proxyAvatar === 'function') {
                    return window.apiClient.proxyAvatar(src) || fallback;
                }
            } catch (_) {
                return fallback;
            }
            return src;
        },
        selectCandidate(player) {
            const pid = this.playerId(player);
            if (!pid) return;
            this.selectedCandidateId = String(pid);
            this.searchQuery = this.playerName(player);
        },
        handleClose() {
            this.$emit('close');
        },
        handleSubmit() {
            if (this.submitDisabled) return;
            this.$emit('submit', String(this.resolvedCandidateId).trim());
        },
        delta(metric) {
            const base = Number(metric?.base);
            const compare = Number(metric?.compare);
            if (!Number.isFinite(base) || !Number.isFinite(compare)) return null;
            return compare - base;
        },
        deltaClass(metric) {
            const value = this.delta(metric);
            if (value == null) return 'is-neutral';
            if (value > 0) return 'is-pos';
            if (value < 0) return 'is-neg';
            return 'is-neutral';
        },
        deltaLabel(metric) {
            const value = this.delta(metric);
            if (value == null) return '–';
            const sign = value > 0 ? '+' : value < 0 ? '-' : '±';
            const abs = Math.abs(value);
            const decimals = metric?.decimals ?? 1;
            if (metric?.percent) {
                return `${sign}${abs.toFixed(decimals)} %`;
            }
            return `${sign}${abs.toFixed(decimals)}`;
        },
        displayValue(metric, side) {
            const value = side === 'base' ? metric.base : metric.compare;
            if (value == null || Number.isNaN(value)) {
                return '–';
            }
            if (typeof metric.format === 'function') {
                return metric.format(value);
            }
            if (metric.percent) {
                return `${Number(value).toFixed(metric.decimals ?? 1)} %`;
            }
            const decimals = metric.decimals ?? (Number(value) >= 100 ? 0 : 1);
            return Number(value).toFixed(decimals);
        }
    },
    template: `
        <transition name="fade">
            <div v-if="visible" class="compare-modal" role="dialog" aria-modal="true">
                <div class="compare-modal__backdrop" @click="handleClose"></div>
                <div class="compare-modal__content glass-card">
                    <header class="compare-modal__header">
                        <h3 class="title-accent titleUnderlineSection">Vertaa pelaajaa</h3>
                        <button type="button" class="compare-modal__close" @click="handleClose">×</button>
                    </header>

                    <div class="compare-modal__body">

                        <form class="compare-modal__form" @submit.prevent="handleSubmit">
                            <label class="compare-modal__label">
                                Hae pelaajaa
                                <input
                                    v-model="searchQuery"
                                    type="text"
                                    placeholder="Kirjoita pelaajan nimi"
                                    @keydown.enter.prevent="handleSubmit"
                                />
                            </label>
                            <button type="submit" class="btn-primary compare-modal__submit" :disabled="submitDisabled" @click="handleSubmit">
                                Hae vertailu
                            </button>
                        </form>

                        <p v-if="selectedCandidate" class="compare-modal__selected">
                            Valittu: <strong>{{ selectedCandidate.nickname }}</strong>
                        </p>

                        <div v-if="loadingCandidates" class="compare-modal__hint">Ladataan pelaajia...</div>
                        <error-message v-else-if="candidatesError" :message="candidatesError"></error-message>
                        <div v-else class="compare-modal__candidates">
                            <button
                                v-for="candidate in filteredCandidates"
                                :key="candidate.player_id"
                                type="button"
                                class="compare-modal__candidate"
                                :class="{ 'is-active': String(selectedCandidateId) === String(candidate.player_id) }"
                                @click="selectCandidate(candidate)"
                            >
                                <img v-if="candidate.avatar" :src="candidate.avatar" :alt="candidate.nickname" loading="lazy" />
                                <span class="compare-modal__candidate-name">{{ candidate.nickname }}</span>
                            </button>
                            <p v-if="!filteredCandidates.length" class="compare-modal__hint">Ei osumia haulla.</p>
                        </div>

                        <loading-spinner v-if="loading" message="Pelaajaa verrataan..."></loading-spinner>
                        <error-message v-else-if="error" :message="error"></error-message>
                        <p v-else class="compare-modal__empty">Vertailu näytetään pelaajasivulla valinnan jälkeen.</p>
                    </div>
                </div>
            </div>
        </transition>
    `
};



/* === /static/components/PickBanFlow.js === */
window.PickBanFlow = {
    name: 'PickBanFlow',
    props: {
        entry: {
            type: Object,
            default: null
        },
        mapCatalog: {
            type: Array,
            default: () => []
        },
        matchMaps: {
            type: Array,
            default: () => []
        }
    },
    data() {
        return {
            imageErrors: {}
        };
    },
    computed: {
        steps() {
            return Array.isArray(this.entry?.steps) ? this.entry.steps : [];
        },
        formatLabel() {
            const format = this.entry?.format;
            if (!format) return '';
            return String(format).toUpperCase();
        },
        catalogLookup() {
            const lookup = {};
            this.mapCatalog.forEach(item => {
                const candidates = [
                    item?.map_id,
                    item?.pretty_name,
                    item?.map_name,
                    item?.name,
                    item?.mapName
                ];
                candidates.forEach(candidate => {
                    const key = this.mapKey(candidate);
                    if (!key) return;
                    if (!lookup[key]) lookup[key] = item;
                    if (key.startsWith('de_')) {
                        const shortKey = key.slice(3);
                        if (shortKey && !lookup[shortKey]) lookup[shortKey] = item;
                    } else {
                        const prefixed = `de_${key}`;
                        if (!lookup[prefixed]) lookup[prefixed] = item;
                    }
                });
            });
            return lookup;
        },
        mapImageLookup() {
            const imageUtils = window.MapImageUtils;
            if (!imageUtils || typeof imageUtils.buildMapImageLookup !== 'function') {
                return {};
            }
            const fromMatchMaps = imageUtils.buildMapImageLookup(this.matchMaps || [], {});
            const merged = imageUtils.buildMapImageLookup(this.mapCatalog || [], fromMatchMaps);
            const withAliases = { ...merged };
            Object.keys(merged).forEach(key => {
                if (!key) return;
                if (key.startsWith('de_')) {
                    const shortKey = key.slice(3);
                    if (shortKey && !withAliases[shortKey]) withAliases[shortKey] = merged[key];
                } else {
                    const prefixed = `de_${key}`;
                    if (!withAliases[prefixed]) withAliases[prefixed] = merged[key];
                }
            });
            return withAliases;
        }
    },
    methods: {
        championshipId() {
            return this.$route?.params?.championshipId || this.$route?.query?.championship || null;
        },
        teamRoute(teamId, teamName = '') {
            const championshipId = this.championshipId();
            if (!championshipId || !teamId) return null;
            return {
                name: 'team-detail',
                params: { championshipId: String(championshipId), teamId: String(teamId) }
            };
        },
        mapKey(name) {
            if (!name) return null;
            return String(name).trim().toLowerCase();
        },
        beautifyMapName(raw) {
            if (!raw) return 'Kartta';
            const value = String(raw).trim();
            const lower = value.toLowerCase();
            if (lower === 'forfeit') return 'Forfeit';
            const core = lower.startsWith('de_') ? lower.slice(3) : lower;
            const parts = core.split(/[_-]/).filter(Boolean);
            if (!parts.length) return value;
            return parts.map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
        },
        resolveMapImage(step) {
            if (!step) return null;
            const mapName = step?.mapName || step?.map_name || step?.map || '';
            const key = this.mapKey(mapName);
            if (!key) return null;
            if (this.imageErrors[key]) return null;

            // Prefer large image for veto cards.
            const directLarge = step?.image_lg || step?.imageLg || null;
            if (directLarge) {
                return window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                    ? window.apiClient.proxyAvatar(directLarge)
                    : directLarge;
            }

            const catalogEntry = this.catalogLookup[key];
            const catalogLarge = catalogEntry?.image_lg || catalogEntry?.imageLg || null;
            if (catalogLarge) {
                return window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                    ? window.apiClient.proxyAvatar(catalogLarge)
                    : catalogLarge;
            }

            const imageUtils = window.MapImageUtils;
            if (imageUtils && typeof imageUtils.resolveMapImage === 'function') {
                const resolved = imageUtils.resolveMapImage(
                    {
                        ...step,
                        map_name: mapName,
                        mapName
                    },
                    {
                        mapCatalog: this.mapCatalog,
                        mapImageLookup: this.mapImageLookup,
                        apiClient: window.apiClient
                    }
                );
                if (resolved) return resolved;
            }

            const entry = this.catalogLookup[key];
            const url = entry?.image_sm || entry?.imageSm || null;
            if (!url) return null;
            return window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                ? window.apiClient.proxyAvatar(url)
                : url;
        },
        onImageError(mapName) {
            const key = this.mapKey(mapName);
            if (!key) return;
            this.imageErrors = { ...this.imageErrors, [key]: true };
        }
    },
    template: `
        <div class="pick-ban-flow">
            <div class="veto-panel-header">
                <div class="veto-panel-heading">
                    <h4 class="veto-panel-title titleUnderlineCard">Pick/Ban</h4>
                </div>
            </div>
            <div v-if="steps.length" class="veto-steps-shell">
                <div class="veto-steps">
                    <div v-for="step in steps" :key="step.step + step.mapName" class="veto-step" :class="'veto-step--' + step.action">
                        <div class="veto-step__top">
                            <div class="veto-step__order">#{{ step.step }}</div>
                            <div class="veto-step__title">{{ step.label }}</div>
                        </div>
                        <div class="veto-step__body">
                            <div class="veto-step__thumb">
                                <img v-if="resolveMapImage(step)" :src="resolveMapImage(step)" @error="onImageError(step.mapName)" alt="" />
                                <div v-else class="map-thumb--placeholder">No image</div>
                            </div>
                            <div class="veto-step__meta">
                                <div class="veto-step__map">{{ beautifyMapName(step.mapName) }}</div>
                                <div v-if="step.action !== 'overflow' && step.action !== 'decider'" class="veto-step__actor">
                                    <router-link
                                        v-if="teamRoute(step.teamId, step.teamName)"
                                        :to="teamRoute(step.teamId, step.teamName)"
                                        class="team-link"
                                    >{{ step.teamName || 'Järjestelmä' }}</router-link>
                                    <span v-else>{{ step.teamName || 'Järjestelmä' }}</span>
                                </div>
                                <div v-else-if="step.action === 'decider'" class="veto-step__actor veto-step__actor--muted">{{ step.teamName || 'Ratkeaa vetoissa' }}</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div v-else class="pick-ban-flow__empty">No veto data available</div>
        </div>
    `
};


/* === /static/components/PlayerStatsTable.js === */
window.PlayerStatsTable = {
    name: 'PlayerStatsTable',
    props: {
        teamPlayers: {
            type: Array,
            default: () => []
        },
        teamId: {
            type: [String, Number],
            required: true
        },
        playerStats: {
            type: Array,
            default: () => []
        },
        mapIndex: {
            type: Number,
            default: 0
        },
        teamName: {
            type: String,
            default: 'Team'
        }
    },
    computed: {
        statsForTeam() {
            return this.playerStats.filter(entry =>
                String(entry?.teamId || entry?.team_id || '') === String(this.teamId)
                && Number(entry?.roundIndex ?? entry?.round_index ?? -1) === Number(this.mapIndex ?? -1)
            );
        },
        playersWithStats() {
            return this.teamPlayers.map(player => {
                const playerEntry = this.statsForTeam.find(s =>
                    String(s?.playerId || s?.player_id || '') === String(player?.playerId || player?.player_id || '')
                );
                return {
                    ...player,
                    stats: playerEntry?.stats || player?.stats || {}
                };
            });
        },
        mapAllPlayers() {
            return this.playerStats.filter(entry =>
                Number(entry?.roundIndex ?? entry?.round_index ?? -1) === Number(this.mapIndex ?? -1)
                && !entry?.is_forfeit_map
            );
        },
        mapAverages() {
            const players = this.mapAllPlayers;
            if (players.length < 2) return {};
            const compute = (values) => {
                const nums = values.filter(v => Number.isFinite(v) && v >= 0);
                if (nums.length < 2) return null;
                const mean = nums.reduce((a, b) => a + b, 0) / nums.length;
                const stddev = Math.sqrt(nums.reduce((a, b) => a + (b - mean) ** 2, 0) / nums.length);
                return { mean, stddev };
            };
            const result = {};
            for (const key of ['K/D Ratio', 'ADR', 'Utility Damage', 'Headshots %']) {
                result[key] = compute(players.map(p => Number(p?.stats?.[key] ?? 0)));
            }
            result['__entry_pct'] = compute(
                players
                    .map(p => { const c = Number(p?.stats?.['Entry Count'] ?? 0); return c > 0 ? Number(p?.stats?.['Entry Wins'] ?? 0) / c : null; })
                    .filter(v => v !== null)
            );
            result['__flash_pct'] = compute(
                players
                    .map(p => { const c = Number(p?.stats?.['Flash Count'] ?? 0); return c > 0 ? Number(p?.stats?.['Flash Successes'] ?? 0) / c : null; })
                    .filter(v => v !== null)
            );
            return result;
        },
        hasPlayers() {
            return this.playersWithStats.length > 0;
        }
    },
    methods: {
        getStatValue(stat, key, defaultVal = 0) {
            const source = stat?.stats && typeof stat.stats === 'object' ? stat.stats : stat;
            return source?.[key] ?? defaultVal;
        },
        calculatePercentage(numerator, denominator) {
            if (!denominator || denominator === 0) return 0;
            return ((numerator / denominator) * 100).toFixed(0);
        },
        formatValue(value, decimals = 0) {
            const num = Number(value);
            if (!Number.isFinite(num)) return '-';
            return decimals > 0 ? num.toFixed(decimals) : Math.round(num);
        },
        rawPct(wins, total) {
            const t = Number(total);
            return t > 0 ? Number(wins) / t : -1;
        },
        getStatColorClass(value, statKey) {
            const avg = this.mapAverages[statKey];
            if (!avg) return '';
            const num = Number(value);
            if (!Number.isFinite(num) || num < 0) return '';
            const threshold = avg.stddev * 0.75;
            if (num >= avg.mean + threshold) return 'stat-positive';
            if (num <= avg.mean - threshold) return 'stat-negative';
            return '';
        },
        playerRoute(player) {
            const playerId = player?.playerId || player?.player_id || null;
            if (!playerId) return null;
            const championshipId = this.$root?.$route?.params?.championshipId || this.$root?.$route?.query?.championship || null;
            return {
                name: 'player',
                params: { playerId: String(playerId) },
                query: championshipId ? { championship: String(championshipId) } : {}
            };
        }
    },
    template: `
        <div class="player-stats-table-wrapper">
            <div v-if="hasPlayers" class="player-stats-table-container">
                <table class="player-stats-table">
                    <thead>
                        <tr class="player-stats-table__header">
                            <th class="player-stats-table__th player-stats-table__th--nickname">Pelaaja</th>
                            <th class="player-stats-table__th player-stats-table__th--kda">K-D-A (K/D)</th>
                            <th class="player-stats-table__th player-stats-table__th--adr">ADR</th>
                            <th class="player-stats-table__th player-stats-table__th--utility-damage player-stats-table__th--desktop">UtilDmg</th>
                            <th class="player-stats-table__th player-stats-table__th--entries player-stats-table__th--desktop">Entries</th>
                            <th class="player-stats-table__th player-stats-table__th--flashes player-stats-table__th--desktop">Flashes</th>
                            <th class="player-stats-table__th player-stats-table__th--hs-pct player-stats-table__th--desktop">HS%</th>
                            <th class="player-stats-table__th player-stats-table__th--first-kills player-stats-table__th--hidden-mobile player-stats-table__th--hidden-tablet">FK</th>
                            <th class="player-stats-table__th player-stats-table__th--multikill player-stats-table__th--hidden-mobile player-stats-table__th--hidden-tablet">2K</th>
                            <th class="player-stats-table__th player-stats-table__th--multikill player-stats-table__th--hidden-mobile player-stats-table__th--hidden-tablet">3K</th>
                            <th class="player-stats-table__th player-stats-table__th--multikill player-stats-table__th--hidden-mobile player-stats-table__th--hidden-tablet">4K</th>
                            <th class="player-stats-table__th player-stats-table__th--multikill player-stats-table__th--hidden-mobile player-stats-table__th--hidden-tablet">5K</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="player in playersWithStats" :key="player.playerId || player.player_id" class="player-stats-table__row">
                            <td class="player-stats-table__td player-stats-table__td--nickname">
                                <router-link v-if="playerRoute(player)" :to="playerRoute(player)" class="player-link player-stats-table__name-content">
                                    {{ player.nickname || player.playerId || player.player_id }}
                                </router-link>
                                <span v-else class="player-stats-table__name-content">{{ player.nickname || player.playerId || player.player_id }}</span>
                            </td>
                            <td class="player-stats-table__td player-stats-table__td--kda">
                                <span class="stat-fraction">
                                    {{ formatValue(getStatValue(player.stats, 'Kills')) }}-{{ formatValue(getStatValue(player.stats, 'Deaths')) }}-{{ formatValue(getStatValue(player.stats, 'Assists')) }}
                                </span>
                                <span class="stat-percentage" :class="getStatColorClass(getStatValue(player.stats, 'K/D Ratio'), 'K/D Ratio')">({{ formatValue(getStatValue(player.stats, 'K/D Ratio'), 2) }})</span>
                            </td>
                            <td class="player-stats-table__td player-stats-table__td--adr" :class="getStatColorClass(getStatValue(player.stats, 'ADR'), 'ADR')">{{ formatValue(getStatValue(player.stats, 'ADR'), 1) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--utility-damage player-stats-table__td--desktop" :class="getStatColorClass(getStatValue(player.stats, 'Utility Damage'), 'Utility Damage')">{{ formatValue(getStatValue(player.stats, 'Utility Damage')) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--entries player-stats-table__td--desktop">
                                <span class="stat-fraction">
                                    {{ formatValue(getStatValue(player.stats, 'Entry Wins')) }}/{{ formatValue(getStatValue(player.stats, 'Entry Count')) }}
                                </span>
                                <span class="stat-percentage" :class="getStatColorClass(rawPct(getStatValue(player.stats, 'Entry Wins'), getStatValue(player.stats, 'Entry Count')), '__entry_pct')">({{ calculatePercentage(getStatValue(player.stats, 'Entry Wins'), getStatValue(player.stats, 'Entry Count')) }}%)</span>
                            </td>
                            <td class="player-stats-table__td player-stats-table__td--flashes player-stats-table__td--desktop">
                                <span class="stat-fraction">
                                    {{ formatValue(getStatValue(player.stats, 'Flash Successes')) }}/{{ formatValue(getStatValue(player.stats, 'Flash Count')) }}
                                </span>
                                <span class="stat-percentage" :class="getStatColorClass(rawPct(getStatValue(player.stats, 'Flash Successes'), getStatValue(player.stats, 'Flash Count')), '__flash_pct')">({{ calculatePercentage(getStatValue(player.stats, 'Flash Successes'), getStatValue(player.stats, 'Flash Count')) }}%)</span>
                            </td>
                            <td class="player-stats-table__td player-stats-table__td--hs-pct player-stats-table__td--desktop" :class="getStatColorClass(getStatValue(player.stats, 'Headshots %'), 'Headshots %')">{{ formatValue(getStatValue(player.stats, 'Headshots %')) }}%</td>
                            <td class="player-stats-table__td player-stats-table__td--first-kills player-stats-table__td--hidden-mobile player-stats-table__td--hidden-tablet">{{ formatValue(getStatValue(player.stats, 'First Kills')) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--multikill player-stats-table__td--hidden-mobile player-stats-table__td--hidden-tablet">{{ formatValue(getStatValue(player.stats, 'Double Kills')) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--multikill player-stats-table__td--hidden-mobile player-stats-table__td--hidden-tablet">{{ formatValue(getStatValue(player.stats, 'Triple Kills')) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--multikill player-stats-table__td--hidden-mobile player-stats-table__td--hidden-tablet">{{ formatValue(getStatValue(player.stats, 'Quadro Kills')) }}</td>
                            <td class="player-stats-table__td player-stats-table__td--multikill player-stats-table__td--hidden-mobile player-stats-table__td--hidden-tablet">{{ formatValue(getStatValue(player.stats, 'Penta Kills')) }}</td>
                        </tr>
                    </tbody>
                </table>
            </div>
            <div v-else class="player-stats-table__empty">Ei pelaajatilastoja</div>
        </div>
    `
};


/* === /static/components/MatchExpandedDetails.js === */
window.MatchExpandedDetails = {
    name: 'MatchExpandedDetails',
    components: {
        get PickBanFlow() { return window.PickBanFlow; },
        get PlayerStatsTable() { return window.PlayerStatsTable; }
    },
    props: {
        summary: {
            type: Object,
            required: true
        },
        details: {
            type: Object,
            default: null
        },
        vetoEntry: {
            type: Object,
            default: null
        },
        playerStats: {
            type: Array,
            default: () => []
        },
        mapCatalog: {
            type: Array,
            default: () => []
        },
        loading: {
            type: Boolean,
            default: false
        }
    },
    data() {
        return {
            imageErrors: {}
        };
    },
    computed: {
        matchDetails() {
            return this.details || this.summary || {};
        },
        teamId() {
            return this.summary?.me?.team_id || this.matchDetails?.team1Id || this.matchDetails?.team1_id || null;
        },
        opponentId() {
            return this.summary?.opponent?.team_id || this.matchDetails?.team2Id || this.matchDetails?.team2_id || null;
        },
        teamName() {
            return this.summary?.me?.team_name || this.matchDetails?.team1Name || this.matchDetails?.team1_name || 'Oma joukkue';
        },
        opponentName() {
            return this.summary?.opponentName || this.summary?.team2Name || this.matchDetails?.team2Name || this.matchDetails?.team2_name || 'Vastustaja';
        },
        formatLabel() {
            if (this.vetoEntry?.format) {
                return String(this.vetoEntry.format).toUpperCase();
            }
            const bestOf = Number(this.summary?.bestOf || this.matchDetails?.bestOf || 0);
            return bestOf ? `BO${bestOf}` : '';
        },
        dateLabel() {
            const ts = this.summary?.ts || this.matchDetails?.ts || null;
            return ts ? this.formatDate(ts) : '';
        },
        scoreLabel() {
            const teamScore = this.summary?.teamScore;
            const oppScore = this.summary?.oppScore;
            if (teamScore == null || oppScore == null) return '';
            return `${teamScore}-${oppScore}`;
        },
        mapEntries() {
            const maps = Array.isArray(this.matchDetails?.maps) ? this.matchDetails.maps : [];
            return maps.filter(map => map && (map.map || map.map_name));
        },
        catalogLookup() {
            const lookup = {};
            this.mapCatalog.forEach(item => {
                const key = this.mapKey(item?.map_id || item?.pretty_name);
                if (!key) return;
                lookup[key] = item;
            });
            return lookup;
        },
        vetoLookup() {
            const lookup = {};
            const steps = Array.isArray(this.vetoEntry?.steps) ? this.vetoEntry.steps : [];
            steps.forEach(step => {
                const key = this.mapKey(step?.mapName || step?.map_name || step?.map);
                if (!key || lookup[key]) return;
                lookup[key] = step;
            });
            return lookup;
        }
    },
    methods: {
        championshipId() {
            return this.$route?.params?.championshipId || this.$route?.query?.championship || null;
        },
        playerRoute(player) {
            const playerId = player?.playerId || player?.player_id || null;
            if (!playerId) return null;
            const championshipId = this.championshipId();
            return {
                name: 'player',
                params: { playerId: String(playerId) },
                query: championshipId ? { championship: String(championshipId) } : {}
            };
        },
        teamRoute(teamId) {
            const championshipId = this.championshipId();
            if (!championshipId || !teamId) return null;
            return {
                name: 'team-detail',
                params: { championshipId: String(championshipId), teamId: String(teamId) }
            };
        },
        mapKey(name) {
            if (!name) return null;
            return String(name).trim().toLowerCase();
        },
        formatDate(ts) {
            if (!ts) return '';
            const d = new Date(ts * 1000);
            return d.toLocaleDateString('fi-FI', { year: 'numeric', month: 'short', day: 'numeric' });
        },
        formatNumber(value, decimals = 0) {
            const num = Number(value);
            if (!Number.isFinite(num)) return '0';
            return num.toFixed(decimals);
        },
        formatSigned(value) {
            const num = Number(value) || 0;
            return `${num >= 0 ? '+' : ''}${Math.round(num)}`;
        },
        mapsWon() {
            return this.mapEntries.filter(map => Number(this.mapScoreFor(map) || 0) > Number(this.mapScoreAgainst(map) || 0)).length;
        },
        mapsLost() {
            return this.mapEntries.filter(map => Number(this.mapScoreFor(map) || 0) < Number(this.mapScoreAgainst(map) || 0)).length;
        },
        matchOutcomeClass() {
            const teamScore = Number(this.summary?.teamScore ?? this.mapsWon());
            const oppScore = Number(this.summary?.oppScore ?? this.mapsLost());
            if (!Number.isFinite(teamScore) || !Number.isFinite(oppScore) || teamScore === oppScore) return 'match-overview__result--neutral';
            return teamScore > oppScore ? 'match-overview__result--win' : 'match-overview__result--loss';
        },
        matchOutcomeLabel() {
            const teamScore = Number(this.summary?.teamScore ?? this.mapsWon());
            const oppScore = Number(this.summary?.oppScore ?? this.mapsLost());
            if (!Number.isFinite(teamScore) || !Number.isFinite(oppScore) || teamScore === oppScore) return 'Tasapeli';
            return teamScore > oppScore ? 'Voitto' : 'Tappio';
        },
        teamAvatar(side = 'team1') {
            const suffix = side === 'team2' ? '2' : '1';
            return this.summary?.[`team${suffix}_avatar`]
                || this.summary?.[`team${suffix}Avatar`]
                || this.summary?.[`t${suffix}_avatar`]
                || this.summary?.[`t${suffix}Avatar`]
                || this.matchDetails?.[`team${suffix}_avatar`]
                || this.matchDetails?.[`team${suffix}Avatar`]
                || this.matchDetails?.[`t${suffix}_avatar`]
                || this.matchDetails?.[`t${suffix}Avatar`]
                || this.summary?.[side]?.avatar
                || this.summary?.[side]?.logo
                || this.matchDetails?.[side]?.avatar
                || this.matchDetails?.[side]?.logo
                || null;
        },
        avatarUrl(src) {
            const fallback = window.PAPPALIIGA_DEFAULT_LOGO;
            if (!src) return fallback;
            try {
                const proxied = window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                    ? window.apiClient.proxyAvatar(src)
                    : src;
                return proxied || fallback;
            } catch (error) {
                return fallback;
            }
        },
        beautifyMapName(raw) {
            if (!raw) return 'Kartta';
            const value = String(raw).trim();
            const lower = value.toLowerCase();
            if (lower === 'forfeit') return 'Forfeit';
            const core = lower.startsWith('de_') ? lower.slice(3) : lower;
            const parts = core.split(/[_-]/).filter(Boolean);
            if (!parts.length) return value;
            return parts.map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
        },
        resolveMapImage(map) {
            const direct = map?.image_lg || map?.image_sm || map?.imageLg || map?.imageSm;
            if (direct) {
                try {
                    return window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                        ? window.apiClient.proxyAvatar(direct)
                        : direct;
                } catch (error) {
                    return direct;
                }
            }

            const mapName = this.mapName(map);
            const key = this.mapKey(mapName);
            if (!key) return null;
            if (this.imageErrors[key]) return null;
            const entry = this.catalogLookup[key];
            const url = entry?.image_lg || entry?.image_sm || null;
            if (!url) return null;
            try {
                return window.apiClient && typeof window.apiClient.proxyAvatar === 'function'
                    ? window.apiClient.proxyAvatar(url)
                    : url;
            } catch (error) {
                return url;
            }
        },
        mapRoundIndex(map) {
            return map?.round_index ?? map?.roundIndex ?? 0;
        },
        mapScoreFor(map) {
            return map?.rf ?? map?.score_team1 ?? map?.scoreFor ?? 0;
        },
        mapScoreAgainst(map) {
            return map?.ra ?? map?.score_team2 ?? map?.scoreAgainst ?? 0;
        },
        mapRoundDiffAbs(map) {
            const left = Number(this.mapScoreFor(map) ?? 0);
            const right = Number(this.mapScoreAgainst(map) ?? 0);
            if (!Number.isFinite(left) || !Number.isFinite(right)) return 0;
            return Math.abs(Math.round(left - right));
        },
        mapScoreClass(map, side = 'left') {
            const left = Number(this.mapScoreFor(map) ?? 0);
            const right = Number(this.mapScoreAgainst(map) ?? 0);
            if (!Number.isFinite(left) || !Number.isFinite(right) || left === right) return '';
            const leftWins = left > right;
            if (side === 'left') {
                return leftWins ? 'match-map-score__value--win' : 'match-map-score__value--loss';
            }
            return leftWins ? 'match-map-score__value--loss' : 'match-map-score__value--win';
        },
        mapName(map) {
            return map?.map || map?.map_name || map?.mapName || '';
        },
        vetoStepForMap(map) {
            return this.vetoLookup[this.mapKey(this.mapName(map))] || null;
        },
        vetoChipLabel(map) {
            const step = this.vetoStepForMap(map);
            if (!step) return 'Played';
            const action = String(step.action || '').trim();
            return action ? action.toUpperCase() : 'Played';
        },
        vetoChipSubline(map) {
            const step = this.vetoStepForMap(map);
            if (!step?.teamName) return 'Ottelukartta';
            return step.teamName;
        },
        mapOutcomeLabel(map) {
            const left = Number(this.mapScoreFor(map) || 0);
            const right = Number(this.mapScoreAgainst(map) || 0);
            if (!Number.isFinite(left) || !Number.isFinite(right) || left === right) return 'Tasainen';
            return left > right ? 'Voitto' : 'Tappio';
        },
        mapOutcomeClass(map) {
            const left = Number(this.mapScoreFor(map) || 0);
            const right = Number(this.mapScoreAgainst(map) || 0);
            if (!Number.isFinite(left) || !Number.isFinite(right) || left === right) return 'match-map-card--neutral';
            return left > right ? 'match-map-card--win' : 'match-map-card--loss';
        },
        mapSequenceLabel(map, index) {
            const roundIndex = Number(this.mapRoundIndex(map));
            if (Number.isFinite(roundIndex) && roundIndex > 0) {
                return `Kartta ${roundIndex}`;
            }
            return `Kartta ${index + 1}`;
        },
        onImageError(mapName) {
            const key = this.mapKey(mapName);
            if (!key) return;
            this.imageErrors = { ...this.imageErrors, [key]: true };
        },
        playersForTeam(roundIndex, teamId) {
            if (!teamId) return [];
            return this.playerStats.filter(entry =>
                String(entry?.teamId || entry?.team_id || '') === String(teamId)
                && Number(entry?.roundIndex ?? entry?.round_index ?? -1) === Number(roundIndex ?? -1)
            );
        },
        playersAvailable(roundIndex) {
            return this.playerStats.some(entry => Number(entry?.roundIndex ?? entry?.round_index ?? -1) === Number(roundIndex ?? -1));
        }
    },
    template: `
        <div class="match-details-panel">
            <section class="match-overview glass-card">
                <div class="match-overview__header">
                    <div class="match-overview__copy">
                        <h4 class="match-overview__title titleUnderlineSection title-duration-fast">Ottelun kulku</h4>
                    </div>
                </div>

                <div class="match-overview__scoreboard">
                    <div class="match-overview__team match-overview__team--left">
                        <img class="match-overview__team-logo" :src="avatarUrl(teamAvatar('team1'))" :alt="teamName + ' logo'" loading="lazy" />
                        <router-link v-if="teamRoute(teamId)" :to="teamRoute(teamId)" class="match-overview__team-name team-link">{{ teamName }}</router-link>
                        <span v-else class="match-overview__team-name">{{ teamName }}</span>
                    </div>

                    <div class="match-overview__score-shell">
                        <div class="match-overview__score mono-num">{{ scoreLabel || (mapsWon() + '-' + mapsLost()) }}</div>
                        <div v-if="dateLabel" class="match-overview__date">{{ dateLabel }}</div>
                    </div>

                    <div class="match-overview__team match-overview__team--right">
                        <router-link v-if="teamRoute(opponentId)" :to="teamRoute(opponentId)" class="match-overview__team-name team-link">{{ opponentName }}</router-link>
                        <span v-else class="match-overview__team-name">{{ opponentName }}</span>
                        <img class="match-overview__team-logo" :src="avatarUrl(teamAvatar('team2'))" :alt="opponentName + ' logo'" loading="lazy" />
                    </div>
                </div>
            </section>

            <pick-ban-flow :entry="vetoEntry" :map-catalog="mapCatalog" :match-maps="mapEntries"></pick-ban-flow>

            <div class="match-maps">
                <div class="section-heading section-heading--split match-maps__heading">
                    <div class="section-heading__main">
                        <h4 class="titleUnderlineCard">Kartat</h4>
                        <span class="section-sub section-subtext">Ottelukarttakohtaiset tilastot ja pelaajat</span>
                    </div>
                </div>

                <div v-if="loading" class="match-details-skeleton">
                    <div class="skeleton-line"></div>
                    <div class="skeleton-line"></div>
                </div>

                <div v-if="mapEntries.length" class="match-maps-grid">
                    <article
                        v-for="(map, index) in mapEntries"
                        :key="mapRoundIndex(map) || mapName(map)"
                        class="match-map-card glass-card"
                        :class="mapOutcomeClass(map)"
                    >
                        <div class="match-map-card__hero">
                            <div class="match-map-card__topline">
                                <span class="match-map-card__index">{{ mapSequenceLabel(map, index) }}</span>
                                <div class="match-map-card__badges">
                                    <span
                                        v-if="vetoStepForMap(map)?.action && !['played', 'pick'].includes(String(vetoStepForMap(map).action).toLowerCase())"
                                        class="match-map-card__badge"
                                        :class="'match-map-card__badge--' + (vetoStepForMap(map)?.action || 'muted')"
                                    >{{ vetoChipLabel(map) }}</span>
                                </div>
                            </div>

                            <div class="match-map-header">
                                <div class="match-map-thumb">
                                    <img
                                        v-if="resolveMapImage(map)"
                                        :src="resolveMapImage(map)"
                                        @error="onImageError(mapName(map))"
                                        alt=""
                                    />
                                    <div v-else class="map-thumb map-thumb--placeholder">No image</div>
                                </div>
                                <div class="match-map-meta">
                                    <div class="match-map-name">{{ beautifyMapName(mapName(map)) }}</div>
                                    <div class="match-map-score">
                                        <span class="match-map-score__team-wrap">
                                            <img class="match-map-score__logo" :src="avatarUrl(teamAvatar('team1'))" :alt="teamName + ' logo'" loading="lazy" />
                                            <router-link v-if="teamRoute(teamId)" :to="teamRoute(teamId)" class="match-map-score__team team-link">{{ teamName }}</router-link>
                                            <span v-else class="match-map-score__team">{{ teamName }}</span>
                                        </span>
                                        <span class="match-map-score__rounds mono-num">
                                            <span class="match-map-score__line">
                                                <span :class="['match-map-score__value', mapScoreClass(map, 'left')]">{{ mapScoreFor(map) }}</span>
                                                <span class="match-map-score__sep"> - </span>
                                                <span :class="['match-map-score__value', mapScoreClass(map, 'right')]">{{ mapScoreAgainst(map) }}</span>
                                            </span>
                                            <span class="match-map-score__rd">RD {{ mapRoundDiffAbs(map) }}</span>
                                        </span>
                                        <span class="match-map-score__team-wrap">
                                            <router-link v-if="teamRoute(opponentId)" :to="teamRoute(opponentId)" class="match-map-score__team team-link">{{ opponentName }}</router-link>
                                            <span v-else class="match-map-score__team">{{ opponentName }}</span>
                                            <img class="match-map-score__logo" :src="avatarUrl(teamAvatar('team2'))" :alt="opponentName + ' logo'" loading="lazy" />
                                        </span>
                                    </div>

                                    <div class="match-map-metrics match-map-metrics--inline">
                                        <div class="metric-grid metric-grid--compare">
                                            <span class="metric-value metric-value--left mono-num">{{ formatNumber(map.left?.adr, 1) }}</span>
                                            <span class="metric-label metric-label--center">ADR</span>
                                            <span class="metric-value metric-value--right mono-num">{{ formatNumber(map.right?.adr, 1) }}</span>

                                            <span class="metric-value metric-value--left mono-num">{{ formatNumber(map.left?.kd, 2) }}</span>
                                            <span class="metric-label metric-label--center">avgKD</span>
                                            <span class="metric-value metric-value--right mono-num">{{ formatNumber(map.right?.kd, 2) }}</span>

                                            <span class="metric-value metric-value--left mono-num">{{ formatNumber(map.left?.dmg, 0) }}</span>
                                            <span class="metric-label metric-label--center">Damage</span>
                                            <span class="metric-value metric-value--right mono-num">{{ formatNumber(map.right?.dmg, 0) }}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div class="match-map-players">
                            <div v-if="playersAvailable(mapRoundIndex(map))" class="map-players-stats">
                                <div class="match-map-players__heading">Pelaajatilastot</div>
                                <section class="map-players-stats__team match-team-panel">
                                    <player-stats-table
                                        :team-players="playersForTeam(mapRoundIndex(map), teamId)"
                                        :team-id="teamId"
                                        :player-stats="playerStats"
                                        :map-index="mapRoundIndex(map)"
                                        :team-name="teamName"
                                    ></player-stats-table>
                                </section>

                                <section class="map-players-stats__team match-team-panel">
                                    <player-stats-table
                                        :team-players="playersForTeam(mapRoundIndex(map), opponentId)"
                                        :team-id="opponentId"
                                        :player-stats="playerStats"
                                        :map-index="mapRoundIndex(map)"
                                        :team-name="opponentName"
                                    ></player-stats-table>
                                </section>
                            </div>
                            <div v-else-if="!loading" class="match-map-empty">No player stats available</div>
                        </div>
                    </article>
                </div>
                <div v-else class="match-map-empty">No map stats available</div>
            </div>
        </div>
    `
};


/* === /static/components/PlayoffBracket.js === */
﻿/* PlayoffBracket — Faceit-style bracket columns for a playoff championship. */
window.PlayoffBracket = {
    name: 'PlayoffBracket',
    components: {
        get MatchExpandedDetails() { return window.MatchExpandedDetails; }
    },
    props: {
        bracket: { type: Object, default: null },
        mapCatalog: { type: Array, default: () => [] },
        isExpandedFn: { type: Function, default: () => false },
        toggleExpandFn: { type: Function, default: () => {} },
        matchSummaryFn: { type: Function, default: () => ({}) },
        matchDetailsFn: { type: Function, default: () => ({}) },
        matchVetoFn: { type: Function, default: () => null },
        matchPlayerStatsFn: { type: Function, default: () => [] },
        matchBundleBusyFn: { type: Function, default: () => false },
        resolveAvatarFn: { type: Function, default: (u) => u },
        teamRouteFn: { type: Function, default: () => null },
        faceitUrlFn: { type: Function, default: () => null },
        replay2LinksFn: { type: Function, default: () => [] },
        replay2PlayerUrlFn: { type: Function, default: () => null },
        demoAvailabilityLoadingFn: { type: Function, default: () => false },
    },
    data() {
        return {
            openMatchId: null,
            openMatch: null,
        };
    },
    computed: {
        rounds() {
            const rawRounds = Array.isArray(this.bracket?.rounds) ? this.bracket.rounds : [];
            return this._normalizeRounds(rawRounds);
        },
    },
    mounted() {
        this.$nextTick(() => { this._layout(); });
    },
    updated() {
        this.$nextTick(() => { this._layout(); });
    },
    beforeUnmount() {
        if (this._ro) { this._ro.disconnect(); this._ro = null; }
    },
    methods: {
        matchId(m) { return String(m?.match_id || m?.matchId || ''); },
        team1Name(m) { return m?.team1_name || m?.team1Name || null; },
        team2Name(m) { return m?.team2_name || m?.team2Name || null; },
        team1Id(m) { return m?.team1_id || m?.team1Id || null; },
        team2Id(m) { return m?.team2_id || m?.team2Id || null; },
        team1Avatar(m) { return m?.team1_avatar || m?.team1Avatar || null; },
        team2Avatar(m) { return m?.team2_avatar || m?.team2Avatar || null; },
        winnerId(m) { return m?.winner_team_id || m?.winnerTeamId || null; },
        team1Score(m) { return Number(m?.team1_score ?? m?.team1Score ?? 0); },
        team2Score(m) { return Number(m?.team2_score ?? m?.team2Score ?? 0); },
        isFinished(m) {
            const fa = Number(m?.finished_at ?? m?.finishedAt ?? 0);
            return fa > 0 || !!m?.is_forfeit || (this.team1Score(m) + this.team2Score(m)) > 0;
        },
        isOngoing(m) {
            const s = String(m?.status || '').toLowerCase();
            return s === 'ongoing' || s === 'voting' || s === 'running';
        },
        scheduledDate(m) {
            const ts = Number(m?.scheduled_at ?? m?.scheduledAt ?? m?.started_at ?? m?.startedAt ?? 0);
            if (!ts) return null;
            const d = new Date(ts * 1000);
            return d.toLocaleDateString('fi-FI', { day: 'numeric', month: 'numeric' }) +
                ' · ' + d.toLocaleTimeString('fi-FI', { hour: '2-digit', minute: '2-digit' });
        },
        cardStateClass(m) {
            if (this.isOngoing(m)) return 'bk-card--ongoing';
            if (this.isFinished(m)) return 'bk-card--finished';
            return 'bk-card--scheduled';
        },
        teamWon(m, side) {
            const wid = this.winnerId(m);
            if (!wid) return false;
            return wid === (side === 'team1' ? this.team1Id(m) : this.team2Id(m));
        },
        teamLost(m, side) {
            return this.isFinished(m) && !!this.winnerId(m) && !this.teamWon(m, side);
        },
        faceitUrl(m) { return this.faceitUrlFn(m); },
        replay2Links(m) { return m ? this.replay2LinksFn(m) : []; },
        replay2PlayerUrl(mid, mapId) { return this.replay2PlayerUrlFn(mid, mapId); },
        globalMatchNum(roundIdx, matchIdx) {
            let base = 0;
            for (let ri = 0; ri < roundIdx; ri++) {
                base += (this.rounds[ri]?.match_count_expected || 1);
            }
            return base + matchIdx + 1;
        },
        tbdCount(round) {
            const exp = round.match_count_expected || 1;
            return Math.max(0, exp - (round.matches?.length || 0));
        },
        openPanel(match) {
            const mid = this.matchId(match);
            if (this.openMatchId === mid) {
                this.openMatchId = null;
                this.openMatch = null;
                return;
            }
            this.openMatchId = mid;
            this.openMatch = match;
            // Trigger data loading via parent delegate
            this.toggleExpandFn(match);
            this.$nextTick(() => {
                const panel = this.$refs.detailPanel;
                if (panel) panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
            });
        },
        closePanel() {
            this.openMatchId = null;
            this.openMatch = null;
        },
        openMatchLabel() {
            if (!this.openMatch) return '';
            const n1 = this.team1Name(this.openMatch) || 'TBD';
            const n2 = this.team2Name(this.openMatch) || 'TBD';
            return `${n1} vs ${n2}`;
        },
        _normalizeRounds(rawRounds) {
            if (!Array.isArray(rawRounds) || !rawRounds.length) return [];
            const normalized = rawRounds.map((round) => ({
                ...round,
                matches: Array.isArray(round?.matches) ? [...round.matches] : [],
            }));
            for (let ri = normalized.length - 2; ri >= 0; ri--) {
                const srcMatches = normalized[ri]?.matches || [];
                const dstMatches = normalized[ri + 1]?.matches || [];
                if (srcMatches.length < 2 || !dstMatches.length) continue;
                const decorated = srcMatches.map((match, srcIdx) => {
                    const candidates = [
                        this.winnerId(match),
                        this.team1Id(match),
                        this.team2Id(match),
                    ].filter(Boolean).map(String);
                    let targetRoundIdx = Number.POSITIVE_INFINITY;
                    let targetSide = Number.POSITIVE_INFINITY;
                    for (let dIdx = 0; dIdx < dstMatches.length; dIdx++) {
                        const dst = dstMatches[dIdx];
                        const dstTeams = new Set([
                            this.team1Id(dst),
                            this.team2Id(dst),
                        ].filter(Boolean).map(String));
                        if (candidates.some((id) => dstTeams.has(id))) {
                            targetRoundIdx = dIdx;
                            const dstT1 = String(this.team1Id(dst) || '');
                            const dstT2 = String(this.team2Id(dst) || '');
                            if (dstT1 && candidates.includes(dstT1)) targetSide = 0;
                            else if (dstT2 && candidates.includes(dstT2)) targetSide = 1;
                            break;
                        }
                    }
                    return { match, srcIdx, targetRoundIdx, targetSide };
                });
                decorated.sort((a, b) => (a.targetRoundIdx - b.targetRoundIdx) || (a.targetSide - b.targetSide) || (a.srcIdx - b.srcIdx));
                normalized[ri].matches = decorated.map((x) => x.match);
            }
            for (let ri = 1; ri < normalized.length; ri++) {
                const prevMatches = normalized[ri - 1]?.matches || [];
                const curMatches = normalized[ri]?.matches || [];
                if (!prevMatches.length || !curMatches.length) continue;
                normalized[ri].matches = curMatches.map((dstMatch, ci) => {
                    const srcA = prevMatches[ci * 2];
                    const srcB = prevMatches[ci * 2 + 1];
                    if (!srcA || !srcB) return dstMatch;
                    const topIds = new Set([
                        this.winnerId(srcA),
                        this.team1Id(srcA),
                        this.team2Id(srcA),
                    ].filter(Boolean).map(String));
                    const bottomIds = new Set([
                        this.winnerId(srcB),
                        this.team1Id(srcB),
                        this.team2Id(srcB),
                    ].filter(Boolean).map(String));
                    if (!topIds.size || !bottomIds.size) return dstMatch;
                    const t1 = String(this.team1Id(dstMatch) || '');
                    const t2 = String(this.team2Id(dstMatch) || '');
                    if (!t1 || !t2) return dstMatch;
                    const directScore = (topIds.has(t1) ? 1 : 0) + (bottomIds.has(t2) ? 1 : 0);
                    const swappedScore = (topIds.has(t2) ? 1 : 0) + (bottomIds.has(t1) ? 1 : 0);
                    if (swappedScore <= directScore) return dstMatch;
                    return {
                        ...dstMatch,
                        team1_id: this.team2Id(dstMatch),
                        team2_id: this.team1Id(dstMatch),
                        team1_name: this.team2Name(dstMatch),
                        team2_name: this.team1Name(dstMatch),
                        team1_avatar: this.team2Avatar(dstMatch),
                        team2_avatar: this.team1Avatar(dstMatch),
                        team1_score: this.team2Score(dstMatch),
                        team2_score: this.team1Score(dstMatch),
                        team1Id: this.team2Id(dstMatch),
                        team2Id: this.team1Id(dstMatch),
                        team1Name: this.team2Name(dstMatch),
                        team2Name: this.team1Name(dstMatch),
                        team1Avatar: this.team2Avatar(dstMatch),
                        team2Avatar: this.team1Avatar(dstMatch),
                        team1Score: this.team2Score(dstMatch),
                        team2Score: this.team1Score(dstMatch),
                    };
                });
            }
            return normalized;
        },
        _layout() {
            const el = this.$refs.bracketEl;
            if (!el) return;
            // Measure the tallest card in round 1 to set SLOT_H
            const cols = Array.from(el.querySelectorAll(':scope > .bracket-col'));
            if (!cols.length) return;
            const firstMc = cols[0].querySelector('.bk-matches');
            if (!firstMc) return;
            const totalSlots = parseInt(firstMc.dataset.slotCount) || 1;
            // Measure max card height in first column + padding
            const firstCards = Array.from(firstMc.querySelectorAll(':scope > .bk-card'));
            let maxH = 0;
            firstCards.forEach(c => { const h = c.getBoundingClientRect().height; if (h > maxH) maxH = h; });
            const SLOT_H = Math.max(140, maxH + 24); // 24px gap between cards
            const totalH = totalSlots * SLOT_H;
            cols.forEach((col) => {
                const mc = col.querySelector('.bk-matches');
                if (!mc) return;
                const slotCount = parseInt(mc.dataset.slotCount) || 1;
                const slotsPerCard = totalSlots / slotCount;
                mc.style.position = 'relative';
                mc.style.height = totalH + 'px';
                const cards = Array.from(mc.querySelectorAll(':scope > .bk-card'));
                cards.forEach((card, j) => {
                    const cardH = card.getBoundingClientRect().height || 100;
                    const centerY = (j + 0.5) * slotsPerCard * SLOT_H;
                    card.style.position = 'absolute';
                    card.style.top = Math.round(centerY - cardH / 2) + 'px';
                    card.style.left = '0';
                    card.style.right = '0';
                    card.style.width = '100%';
                });
            });
            this._drawConnectors();
        },
        _drawConnectors() {
            const el = this.$refs.bracketEl;
            if (!el) return;
            el.querySelectorAll('.bk-connectors').forEach(s => s.remove());
            const cols = Array.from(el.querySelectorAll(':scope > .bracket-col'));
            if (cols.length < 2) return;
            const cRect = el.getBoundingClientRect();
            const scrollL = el.scrollLeft;
            const scrollT = el.scrollTop;
            const absRect = (domEl) => {
                const r = domEl.getBoundingClientRect();
                return {
                    left:  r.left  - cRect.left + scrollL,
                    right: r.right - cRect.left + scrollL,
                    midY:  (r.top + r.bottom) / 2 - cRect.top + scrollT,
                };
            };
            const svgNS = 'http://www.w3.org/2000/svg';
            const svg = document.createElementNS(svgNS, 'svg');
            svg.classList.add('bk-connectors');
            svg.setAttribute('width', el.scrollWidth);
            svg.setAttribute('height', el.scrollHeight);
            svg.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;overflow:visible;z-index:0;';
            el.insertBefore(svg, el.firstChild);
            const line = (d) => {
                const p = document.createElementNS(svgNS, 'path');
                p.setAttribute('d', d);
                p.setAttribute('stroke', 'rgba(255,255,255,0.13)');
                p.setAttribute('stroke-width', '1.5');
                p.setAttribute('fill', 'none');
                p.setAttribute('stroke-linecap', 'round');
                svg.appendChild(p);
            };
            // Y of the winner row in a source card (or card center if match not finished)
            const srcY = (card) => {
                const won = card.querySelector('.bk-team--won');
                return won ? absRect(won).midY : absRect(card).midY;
            };
            for (let ri = 0; ri < cols.length - 1; ri++) {
                const curCards  = Array.from(cols[ri].querySelectorAll('.bk-card'));
                const nextCards = Array.from(cols[ri + 1].querySelectorAll('.bk-card'));
                if (!curCards.length || !nextCards.length) continue;
                for (let ci = 0; ci < nextCards.length; ci++) {
                    const srcA = curCards[ci * 2];
                    const srcB = curCards[ci * 2 + 1];
                    const dst  = nextCards[ci];
                    if (!srcA || !dst) continue;
                    const xA  = absRect(srcA).right;
                    const yA  = srcY(srcA);
                    const tX  = absRect(dst).left;
                    // Land on each specific team row in the destination card
                    const dstTeams = Array.from(dst.querySelectorAll('.bk-team'));
                    const usedDstIndexes = new Set();
                    const resolveDstIndex = (srcCard, fallbackIndex) => {
                        const wid = String(srcCard?.dataset?.winnerId || '');
                        if (wid) {
                            const matched = dstTeams.findIndex((teamRow) => String(teamRow?.dataset?.teamId || '') === wid);
                            if (matched >= 0 && !usedDstIndexes.has(matched)) {
                                usedDstIndexes.add(matched);
                                return matched;
                            }
                        }
                        const safeFallback = (fallbackIndex === 0 || fallbackIndex === 1) ? fallbackIndex : 0;
                        if (!usedDstIndexes.has(safeFallback)) {
                            usedDstIndexes.add(safeFallback);
                            return safeFallback;
                        }
                        const alt = safeFallback === 0 ? 1 : 0;
                        if (!usedDstIndexes.has(alt)) {
                            usedDstIndexes.add(alt);
                            return alt;
                        }
                        return safeFallback;
                    };
                    const dstAIndex = resolveDstIndex(srcA, 0);
                    const dstYA = dstTeams[dstAIndex] ? absRect(dstTeams[dstAIndex]).midY : absRect(dst).midY;
                    const cpX = (xA + tX) / 2;
                    // Bezier from source winner row → destination team1 row
                    line(`M ${xA} ${yA} C ${cpX} ${yA} ${cpX} ${dstYA} ${tX} ${dstYA}`);
                    if (srcB) {
                        const xB  = absRect(srcB).right;
                        const yB  = srcY(srcB);
                        const dstBIndex = resolveDstIndex(srcB, 1);
                        const dstYB = dstTeams[dstBIndex] ? absRect(dstTeams[dstBIndex]).midY : absRect(dst).midY;
                        const cpX2 = (xB + tX) / 2;
                        // Bezier from source winner row → destination team2 row
                        line(`M ${xB} ${yB} C ${cpX2} ${yB} ${cpX2} ${dstYB} ${tX} ${dstYB}`);
                    }
                }
            }
        },
    },
    template: `
        <div v-if="rounds.length" class="playoff-bracket-wrapper">

            <!-- ── Bracket ── -->
            <div class="playoff-bracket" ref="bracketEl">
                <div
                    v-for="(round, ri) in rounds"
                    :key="round.round_number ?? 'r'+ri"
                    class="bracket-col"
                >
                    <div class="bk-round-hdr">
                        <span class="bk-round-hdr__title">{{ round.label }}</span>
                        <span class="bk-round-hdr__meta">
                            {{ round.match_count_expected || round.matches.length }} {{ (round.match_count_expected || round.matches.length) === 1 ? 'ottelu' : 'ottelua' }}<template v-if="round.best_of">&nbsp;&middot; Best of {{ round.best_of }}</template>
                        </span>
                    </div>

                    <div class="bk-matches" :data-slot-count="round.match_count_expected || round.matches.length">

                        <!-- Real match cards -->
                        <div
                            v-for="(match, mi) in round.matches"
                            :key="matchId(match)"
                            class="bk-card"
                            :data-winner-id="winnerId(match) || ''"
                            :class="[cardStateClass(match), { 'bk-card--open': openMatchId === matchId(match) }]"
                        >
                            <div class="bk-card__hdr">
                                <span class="bk-card__num">MATCH {{ globalMatchNum(ri, mi) }}</span>
                                <span v-if="isOngoing(match)" class="bk-badge bk-badge--live">KÄYNNISSÄ</span>
                                <span v-else-if="scheduledDate(match)" class="bk-card__date">{{ scheduledDate(match) }}</span>
                            </div>

                            <div class="bk-team" :data-team-id="team1Id(match) || ''" :class="{ 'bk-team--won': teamWon(match,'team1'), 'bk-team--lost': teamLost(match,'team1') }">
                                <img v-if="resolveAvatarFn(team1Avatar(match))" :src="resolveAvatarFn(team1Avatar(match))" :alt="team1Name(match)" class="bk-team__logo" loading="lazy" decoding="async" />
                                <span v-else class="bk-team__logo bk-team__logo--ph"></span>
                                <router-link v-if="team1Name(match) && teamRouteFn(team1Id(match))" :to="teamRouteFn(team1Id(match))" class="bk-team__name">{{ team1Name(match) }}</router-link>
                                <span v-else class="bk-team__name" :class="{ 'bk-team__name--tbd': !team1Name(match) }">{{ team1Name(match) || 'TBD' }}</span>
                                <span class="bk-team__score" :class="{ 'bk-team__score--win': teamWon(match,'team1') }">{{ isFinished(match) ? team1Score(match) : '' }}</span>
                                <span v-if="teamWon(match,'team1')" class="bk-win-bar"></span>
                            </div>

                            <div class="bk-team-divider"></div>

                            <div class="bk-team" :data-team-id="team2Id(match) || ''" :class="{ 'bk-team--won': teamWon(match,'team2'), 'bk-team--lost': teamLost(match,'team2') }">
                                <img v-if="resolveAvatarFn(team2Avatar(match))" :src="resolveAvatarFn(team2Avatar(match))" :alt="team2Name(match)" class="bk-team__logo" loading="lazy" decoding="async" />
                                <span v-else class="bk-team__logo bk-team__logo--ph"></span>
                                <router-link v-if="team2Name(match) && teamRouteFn(team2Id(match))" :to="teamRouteFn(team2Id(match))" class="bk-team__name">{{ team2Name(match) }}</router-link>
                                <span v-else class="bk-team__name" :class="{ 'bk-team__name--tbd': !team2Name(match) }">{{ team2Name(match) || 'TBD' }}</span>
                                <span class="bk-team__score" :class="{ 'bk-team__score--win': teamWon(match,'team2') }">{{ isFinished(match) ? team2Score(match) : '' }}</span>
                                <span v-if="teamWon(match,'team2')" class="bk-win-bar"></span>
                            </div>

                            <div class="bk-card__footer">
                                <div class="bk-card__links">
                                    <a v-if="faceitUrl(match)" :href="faceitUrl(match)" target="_blank" rel="noopener" class="chip chip--link chip--sm">Faceit</a>
                                    <a v-for="link in replay2Links(match)" :key="'r2-'+matchId(match)+'-'+link.mapId" :href="replay2PlayerUrl(link.matchId, link.mapId)" target="_blank" rel="noopener" :class="['chip','chip--link','chip--sm',['queued','parsing'].includes(link.status)?'chip--warn':'']">2D {{ link.mapId }}</a>
                                    <span v-if="demoAvailabilityLoadingFn(match)" class="cell-muted" style="font-size:.72rem">Tark…</span>
                                </div>
                                <button v-if="isFinished(match)" type="button" class="expand-button bk-expand-btn" :class="{ 'expand-button--open': openMatchId === matchId(match) }" aria-label="Tilastot" @click.stop="openPanel(match)"><span class="chevron">›</span></button>
                            </div>
                        </div>

                        <!-- TBD placeholder slots -->
                        <div v-for="n in tbdCount(round)" :key="'tbd-'+ri+'-'+n" class="bk-card bk-card--tbd">
                            <div class="bk-card__hdr">
                                <span class="bk-card__num">MATCH {{ globalMatchNum(ri, round.matches.length + n - 1) }}</span>
                            </div>
                            <div class="bk-team bk-team--tbd">
                                <span class="bk-team__logo bk-team__logo--ph"></span>
                                <span class="bk-team__name bk-team__name--tbd">TBD</span>
                            </div>
                            <div class="bk-team-divider"></div>
                            <div class="bk-team bk-team--tbd">
                                <span class="bk-team__logo bk-team__logo--ph"></span>
                                <span class="bk-team__name bk-team__name--tbd">TBD</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- ── Detail panel below bracket ── -->
            <div v-if="openMatchId && openMatch" class="bk-detail-panel" ref="detailPanel">
                <div class="bk-detail-panel__hdr">
                    <div class="bk-detail-panel__title">
                        <span class="bk-detail-panel__vs">{{ openMatchLabel() }}</span>
                        <span v-if="scheduledDate(openMatch)" class="bk-detail-panel__date">{{ scheduledDate(openMatch) }}</span>
                    </div>
                    <div class="bk-detail-panel__links">
                        <a v-if="faceitUrl(openMatch)" :href="faceitUrl(openMatch)" target="_blank" rel="noopener" class="chip chip--link chip--sm">Faceit</a>
                        <a v-for="link in replay2Links(openMatch)" :key="'dp-r2-'+link.mapId" :href="replay2PlayerUrl(link.matchId, link.mapId)" target="_blank" rel="noopener" :class="['chip','chip--link','chip--sm',['queued','parsing'].includes(link.status)?'chip--warn':'']">2D {{ link.mapId }}</a>
                        <span v-if="demoAvailabilityLoadingFn(openMatch)" class="cell-muted" style="font-size:.75rem">Tark…</span>
                    </div>
                    <button type="button" class="bk-detail-panel__close" aria-label="Sulje" @click="closePanel()">✕</button>
                </div>
                <div class="match-expand-content">
                    <match-expanded-details
                        :summary="matchSummaryFn(openMatch)"
                        :details="matchDetailsFn(openMatch)"
                        :veto-entry="matchVetoFn(openMatch)"
                        :player-stats="matchPlayerStatsFn(openMatch)"
                        :map-catalog="mapCatalog"
                        :loading="matchBundleBusyFn(openMatchId)"
                    ></match-expanded-details>
                </div>
            </div>

        </div>
        <p v-else class="division-section__empty">Bracket-tietoja ei saatavilla.</p>
    `
};


/* === /static/components/UpcomingMatchesList.js === */
(function () {
    const DEFAULT_TEAM_LOGO = window.PAPPALIIGA_DEFAULT_LOGO;
    const MIN_VALID_MATCH_EPOCH_MS = Date.UTC(2001, 0, 1);

    function isLikelyPlaceholderMatchTsMs(value) {
        if (!Number.isFinite(value) || value <= 0) return true;
        return value < MIN_VALID_MATCH_EPOCH_MS;
    }

    function coerceEpochMs(value) {
        if (value === null || value === undefined || value === 0) return null;
        const numeric = Number(value);
        if (Number.isFinite(numeric) && numeric > 0) {
            const ms = Math.abs(numeric) < 1_000_000_000_000 ? numeric * 1000 : numeric;
            return isLikelyPlaceholderMatchTsMs(ms) ? null : ms;
        }
        const parsed = Date.parse(String(value));
        if (!Number.isFinite(parsed) || parsed <= 0) return null;
        return isLikelyPlaceholderMatchTsMs(parsed) ? null : parsed;
    }

    function getScheduledTs(raw) {
        if (!raw || typeof raw !== 'object') return null;
        const scheduledRaw = raw.scheduled_ts
            ?? raw.scheduledTs
            ?? raw.scheduled_at
            ?? raw.scheduledAt
            ?? raw.scheduled
            ?? raw.start_ts
            ?? raw.startTs
            ?? raw.start_at
            ?? raw.startAt
            ?? raw.date
            ?? raw.datetime
            ?? raw.ts
            ?? null;
        return coerceEpochMs(scheduledRaw);
    }

    function normalizeTeam(raw, fallbackLabel) {
        if (!raw || typeof raw !== 'object') {
            return { id: null, name: fallbackLabel, avatar: DEFAULT_TEAM_LOGO };
        }
        const id = raw.id ?? raw.team_id ?? raw.teamId ?? null;
        const name = raw.name ?? raw.team_name ?? raw.teamName ?? fallbackLabel;
        const avatar = raw.avatar ?? raw.logo ?? raw.team_logo ?? raw.teamLogo ?? DEFAULT_TEAM_LOGO;
        return { id, name, avatar };
    }

    function normalizeUpcomingMatch(raw) {
        if (!raw || typeof raw !== 'object') return null;
        const matchId = raw.match_id ?? raw.matchId ?? null;
        const championshipId = raw.championship_id ?? raw.championshipId ?? null;
        const divisionName = raw.division_name ?? raw.divisionName ?? raw.name ?? null;
        const divisionSlug = raw.division_slug ?? raw.divisionSlug ?? null;
        const divisionNum = raw.division_num ?? raw.divisionNum ?? null;
        const season = raw.season ?? raw.season_id ?? raw.seasonId ?? null;
        const isPlayoffs = Boolean(raw.is_playoffs ?? raw.isPlayoffs ?? raw.is_playoff ?? raw.isPlayoff);
        const status = raw.status ?? null;
        const scheduledTs = getScheduledTs(raw);
        const team1 = normalizeTeam(
            raw.team1 || {
                team_id: raw.team1_id ?? raw.team1Id ?? null,
                team_name: raw.team1_name ?? raw.team1Name ?? null,
                avatar: raw.team1_avatar ?? raw.team1Avatar ?? raw.t1_avatar ?? raw.t1Avatar
            },
            'Joukkue 1'
        );
        const team2 = normalizeTeam(
            raw.team2 || {
                team_id: raw.team2_id ?? raw.team2Id ?? null,
                team_name: raw.team2_name ?? raw.team2Name ?? null,
                avatar: raw.team2_avatar ?? raw.team2Avatar ?? raw.t2_avatar ?? raw.t2Avatar
            },
            'Joukkue 2'
        );
        const faceitUrl = raw.faceit_url ?? raw.faceitUrl ?? '';

        return {
            matchId,
            championshipId,
            divisionName,
            divisionSlug,
            divisionNum,
            season,
            isPlayoffs,
            status,
            scheduledTs,
            team1,
            team2,
            faceitUrl
        };
    }

    function formatDateTime(ts) {
        if (!ts) return 'Aika tarkentuu';
        try {
            return new Date(ts).toLocaleString('fi-FI', {
                weekday: 'short',
                day: 'numeric',
                month: 'short',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
        } catch (error) {
            return 'Aika tarkentuu';
        }
    }

    const existingMatchTimeUtils = (typeof window !== 'undefined' && window.matchTimeUtils && typeof window.matchTimeUtils === 'object')
        ? window.matchTimeUtils
        : {};
    window.matchTimeUtils = Object.freeze({
        ...existingMatchTimeUtils,
        coerceEpochMs,
        getScheduledTs,
        formatDateTime
    });

    window.UpcomingMatchesList = {
        name: 'UpcomingMatchesList',
        components: {
            get LoadingSpinner() { return window.LoadingSpinner; },
            get ErrorMessage() { return window.ErrorMessage; }
        },
        props: {
            title: { type: String, default: 'Tulevat ottelut' },
            subtitle: { type: String, default: '' },
            items: { type: Array, default: () => [] },
            loading: { type: Boolean, default: false },
            error: { type: String, default: '' },
            emptyMessage: { type: String, default: 'Ei tulevia otteluita.' },
            showDivision: { type: Boolean, default: false },
            showFaceit: { type: Boolean, default: true },
            showHeader: { type: Boolean, default: true },
            compact: { type: Boolean, default: false },
            groupByDayDivision: { type: Boolean, default: false },
            showWeekSeparators: { type: Boolean, default: true },
            separatorGranularity: { type: String, default: 'week' }
        },
        computed: {
            normalizedItems() {
                if (!Array.isArray(this.items)) return [];
                return this.items
                    .map(normalizeUpcomingMatch)
                    .filter(Boolean)
                    .sort((a, b) => {
                        const at = a.scheduledTs ?? Number.POSITIVE_INFINITY;
                        const bt = b.scheduledTs ?? Number.POSITIVE_INFINITY;
                        if (at !== bt) return at - bt;
                        return String(a.matchId || '').localeCompare(String(b.matchId || ''));
                    });
            },
            dayDivisionGroups() {
                if (!this.groupByDayDivision) return [];
                const dayMap = new Map();
                for (const match of this.normalizedItems) {
                    const dayKey = this.dayBucket(match.scheduledTs);
                    if (!dayMap.has(dayKey)) {
                        dayMap.set(dayKey, {
                            key: dayKey,
                            ts: match.scheduledTs ?? Number.POSITIVE_INFINITY,
                            label: this.dayLabel(match.scheduledTs),
                            divisionMap: new Map()
                        });
                    }
                    const dayGroup = dayMap.get(dayKey);
                    const divisionKey = this.divisionGroupKey(match);
                    if (!dayGroup.divisionMap.has(divisionKey)) {
                        dayGroup.divisionMap.set(divisionKey, {
                            key: divisionKey,
                            label: this.divisionLabel(match),
                            sortOrder: this.divisionSortOrder(match),
                            matches: []
                        });
                    }
                    dayGroup.divisionMap.get(divisionKey).matches.push(match);
                }
                return Array.from(dayMap.values())
                    .sort((a, b) => a.ts - b.ts)
                    .map(day => ({
                        key: day.key,
                        label: day.label,
                        divisions: Array.from(day.divisionMap.values()).sort((a, b) => {
                            if (a.sortOrder !== b.sortOrder) return a.sortOrder - b.sortOrder;
                            return String(a.label || '').localeCompare(String(b.label || ''), 'fi');
                        })
                    }));
            }
        },
        methods: {
            formatDateTime,
            dayBucket(ts) {
                if (!ts || !Number.isFinite(Number(ts))) return 'unknown-day';
                const date = new Date(Number(ts));
                if (Number.isNaN(date.getTime())) return 'unknown-day';
                const year = date.getFullYear();
                const month = String(date.getMonth() + 1).padStart(2, '0');
                const day = String(date.getDate()).padStart(2, '0');
                return `${year}-${month}-${day}`;
            },
            dayLabel(ts) {
                if (!ts || !Number.isFinite(Number(ts))) return 'Päivä avoin';
                const date = new Date(Number(ts));
                if (Number.isNaN(date.getTime())) return 'Päivä avoin';
                try {
                    return date.toLocaleDateString('fi-FI', {
                        weekday: 'long',
                        day: 'numeric',
                        month: 'long'
                    });
                } catch (error) {
                    return this.dayBucket(ts);
                }
            },
            weekBucket(ts) {
                if (!ts || !Number.isFinite(Number(ts))) return 'unknown';
                const date = new Date(Number(ts));
                if (Number.isNaN(date.getTime())) return 'unknown';
                const day = date.getDay();
                const mondayOffset = (day + 6) % 7;
                const monday = new Date(date);
                monday.setHours(0, 0, 0, 0);
                monday.setDate(monday.getDate() - mondayOffset);
                return monday.toISOString().slice(0, 10);
            },
            weekNumber(ts) {
                if (!ts || !Number.isFinite(Number(ts))) return null;
                const date = new Date(Number(ts));
                if (Number.isNaN(date.getTime())) return null;
                const utcDate = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
                const dayNum = utcDate.getUTCDay() || 7;
                utcDate.setUTCDate(utcDate.getUTCDate() + 4 - dayNum);
                const yearStart = new Date(Date.UTC(utcDate.getUTCFullYear(), 0, 1));
                const weekNo = Math.ceil((((utcDate - yearStart) / 86400000) + 1) / 7);
                return Number.isFinite(weekNo) ? weekNo : null;
            },
            weekLabel(ts) {
                const weekNo = this.weekNumber(ts);
                if (!weekNo) return 'Ajankohta avoin';
                return `Viikko ${weekNo}`;
            },
            separatorBucket(ts) {
                return this.separatorGranularity === 'day' ? this.dayBucket(ts) : this.weekBucket(ts);
            },
            separatorLabel(ts) {
                return this.separatorGranularity === 'day' ? this.dayLabel(ts) : this.weekLabel(ts);
            },
            hasWeekChange(index, match) {
                if (index === 0) return true;
                const previous = this.normalizedItems[index - 1];
                return this.separatorBucket(previous?.scheduledTs) !== this.separatorBucket(match?.scheduledTs);
            },
            resolveAvatar(src) {
                if (!src) return DEFAULT_TEAM_LOGO;
                try {
                    if (window.apiClient && typeof window.apiClient.proxyAvatar === 'function') {
                        const resolved = window.apiClient.proxyAvatar(src);
                        return resolved || DEFAULT_TEAM_LOGO;
                    }
                    return src || DEFAULT_TEAM_LOGO;
                } catch (error) {
                    return src || DEFAULT_TEAM_LOGO;
                }
            },
            divisionLabel(item) {
                if (!item) return '';
                const base = item.divisionName || (item.divisionNum != null ? `Divisioona ${item.divisionNum}` : 'Divisioona');
                return item.isPlayoffs ? `${base} (Playoffs)` : base;
            },
            divisionGroupKey(item) {
                if (!item) return 'division-unknown';
                return String(
                    item.championshipId ??
                    item.divisionSlug ??
                    item.divisionNum ??
                    item.divisionName ??
                    'division-unknown'
                );
            },
            divisionSortOrder(item) {
                if (!item || typeof item !== 'object') return Number.POSITIVE_INFINITY;
                const direct = Number(item.divisionNum);
                if (Number.isFinite(direct)) return direct;
                const label = this.divisionLabel(item);
                const match = String(label).match(/(\d+)/);
                if (match) {
                    const parsed = Number(match[1]);
                    if (Number.isFinite(parsed)) return parsed;
                }
                return Number.POSITIVE_INFINITY;
            },
            divisionRoute(item) {
                if (!item?.championshipId) return null;
                return {
                    name: 'division',
                    params: { championshipId: item.championshipId }
                };
            },
            divisionGroupRoute(divisionGroup) {
                if (!divisionGroup || !Array.isArray(divisionGroup.matches) || !divisionGroup.matches.length) return null;
                return this.divisionRoute(divisionGroup.matches[0]);
            },
            teamRoute(item, team) {
                if (!item?.championshipId || !team?.id) return null;
                return {
                    name: 'team-detail',
                    params: { championshipId: item.championshipId, teamId: team.id }
                };
            }
        },
        template: `
            <section :class="['upcoming-matches', 'glass-card', compact ? 'upcoming-matches--compact' : '']">
                <header v-if="showHeader" class="upcoming-matches__header">
                    <div>
                        <h2 class="title-accent titleUnderlineSection">{{ title }}</h2>
                        <p v-if="subtitle" class="upcoming-matches__subtitle">{{ subtitle }}</p>
                    </div>
                </header>

                <loading-spinner
                    v-if="loading"
                    message="Tulevia otteluita haetaan..."
                ></loading-spinner>
                <error-message
                    v-else-if="error"
                    :message="error"
                ></error-message>

                <div v-else>
                    <p v-if="!normalizedItems.length" class="upcoming-matches__empty">{{ emptyMessage }}</p>
                    <div v-else-if="groupByDayDivision" class="upcoming-matches__groups">
                        <section v-for="dayGroup in dayDivisionGroups" :key="dayGroup.key" class="upcoming-day-group">
                            <div class="upcoming-matches__week-separator upcoming-matches__week-separator--day">
                                <span>{{ dayGroup.label }}</span>
                            </div>
                            <div v-for="division in dayGroup.divisions" :key="dayGroup.key + '-' + division.key" class="upcoming-division-group">
                                <div class="upcoming-matches__week-separator upcoming-matches__week-separator--division">
                                    <router-link
                                        v-if="divisionGroupRoute(division)"
                                        :to="divisionGroupRoute(division)"
                                        class="upcoming-matches__group-link"
                                    >{{ division.label }}</router-link>
                                    <span v-else class="upcoming-matches__group-label">{{ division.label }}</span>
                                </div>
                                <ul class="upcoming-matches__list upcoming-matches__list--grouped">
                                    <li v-for="(match, index) in division.matches" :key="'match-' + (match.matchId || (dayGroup.key + '-' + division.key + '-' + index))" class="upcoming-match-card">
                                        <div class="upcoming-match-card__teams">
                                            <div class="upcoming-match-card__team upcoming-match-card__team--left">
                                                <img :src="resolveAvatar(match.team1.avatar)" :alt="match.team1.name" class="upcoming-match-card__logo">
                                                <router-link
                                                    v-if="teamRoute(match, match.team1)"
                                                    :to="teamRoute(match, match.team1)"
                                                    class="upcoming-match-card__team-name"
                                                >{{ match.team1.name }}</router-link>
                                                <span v-else class="upcoming-match-card__team-name">{{ match.team1.name }}</span>
                                            </div>
                                            <span class="upcoming-match-card__vs">vs</span>
                                            <div class="upcoming-match-card__team upcoming-match-card__team--right">
                                                <img :src="resolveAvatar(match.team2.avatar)" :alt="match.team2.name" class="upcoming-match-card__logo">
                                                <router-link
                                                    v-if="teamRoute(match, match.team2)"
                                                    :to="teamRoute(match, match.team2)"
                                                    class="upcoming-match-card__team-name"
                                                >{{ match.team2.name }}</router-link>
                                                <span v-else class="upcoming-match-card__team-name">{{ match.team2.name }}</span>
                                            </div>
                                        </div>
                                        <div class="upcoming-match-card__actions">
                                            <div class="upcoming-match-card__date">{{ formatDateTime(match.scheduledTs) }}</div>
                                            <a
                                                v-if="showFaceit && match.faceitUrl"
                                                class="upcoming-match-card__link btn-secondary"
                                                :href="match.faceitUrl"
                                                target="_blank"
                                                rel="noopener"
                                            >Faceit Lobby</a>
                                        </div>
                                    </li>
                                </ul>
                            </div>
                        </section>
                    </div>
                    <ul v-else class="upcoming-matches__list">
                        <template v-for="(match, index) in normalizedItems">
                            <li
                                v-if="showWeekSeparators && hasWeekChange(index, match)"
                                :key="'separator-' + separatorBucket(match.scheduledTs) + '-' + index"
                                class="upcoming-matches__week-separator"
                            >
                                <span>{{ separatorLabel(match.scheduledTs) }}</span>
                            </li>
                            <li :key="'match-' + (match.matchId || index)" class="upcoming-match-card">
                            <div class="upcoming-match-card__teams">
                                <div class="upcoming-match-card__team upcoming-match-card__team--left">
                                    <img :src="resolveAvatar(match.team1.avatar)" :alt="match.team1.name" class="upcoming-match-card__logo">
                                    <router-link
                                        v-if="teamRoute(match, match.team1)"
                                        :to="teamRoute(match, match.team1)"
                                        class="upcoming-match-card__team-name"
                                    >{{ match.team1.name }}</router-link>
                                    <span v-else class="upcoming-match-card__team-name">{{ match.team1.name }}</span>
                                </div>
                                <span class="upcoming-match-card__vs">vs</span>
                                <div class="upcoming-match-card__team upcoming-match-card__team--right">
                                    <img :src="resolveAvatar(match.team2.avatar)" :alt="match.team2.name" class="upcoming-match-card__logo">
                                    <router-link
                                        v-if="teamRoute(match, match.team2)"
                                        :to="teamRoute(match, match.team2)"
                                        class="upcoming-match-card__team-name"
                                    >{{ match.team2.name }}</router-link>
                                    <span v-else class="upcoming-match-card__team-name">{{ match.team2.name }}</span>
                                </div>
                            </div>

                            <div v-if="showDivision" class="upcoming-match-card__division">
                                <router-link v-if="divisionRoute(match)" :to="divisionRoute(match)" class="upcoming-match-card__division-link">
                                    {{ divisionLabel(match) }}
                                </router-link>
                                <span v-else class="upcoming-match-card__division-link">{{ divisionLabel(match) }}</span>
                            </div>

                            <div class="upcoming-match-card__actions">
                                <div class="upcoming-match-card__date">{{ formatDateTime(match.scheduledTs) }}</div>
                                <a
                                    v-if="showFaceit && match.faceitUrl"
                                    class="upcoming-match-card__link btn-secondary"
                                    :href="match.faceitUrl"
                                    target="_blank"
                                    rel="noopener"
                                >Faceit Lobby</a>
                            </div>
                            </li>
                        </template>
                    </ul>
                </div>
            </section>
        `
    };
})();


