// Seasons View - List all seasons and their divisions
window.SeasonsView = {
    name: 'SeasonsView',
    components: {
        get LoadingSpinner() { return window.LoadingSpinner; },
        get ErrorMessage() { return window.ErrorMessage; }
    },
    template: `
        <div class="seasons-view">
            <h1 class="title-accent titleUnderlinePage">Kaikki Kaudet</h1>
            
            <loading-spinner v-if="loading" message="Kausia ladataan..."></loading-spinner>
            <error-message v-else-if="error" :message="error" @retry="loadSeasons"></error-message>
            
            <div v-else class="seasons-grid home-section">
                <p v-if="!seasons.length" class="season-meta">Ei kausia saatavilla.</p>
                <template v-else>
                    <div
                        v-for="(season, idx) in seasons"
                        :key="season.season || season.id || idx"
                        class="season-card home-section"
                    >
                        <h2 class="section-title title-accent titleUnderlineCard">
                            {{ getSeasonLabel(season) }}
                        </h2>
                        <p class="season-meta">{{ getDivisionCount(season) }} divisioonaa</p>
                        
                        <div class="divisions-list">
                            <div 
                                v-for="(div, idx) in getDivisionList(season)" 
                                :key="div.id || idx"
                                class="division-row"
                            >
                                <router-link 
                                    :to="getDivisionHref(div)"
                                    class="division-link division-link--regular"
                                >
                                    {{ div.name }}
                                </router-link>
                                <router-link 
                                    v-if="div.hasPlayoffsStarted"
                                    :to="getPlayoffsHref(div)"
                                    class="division-link division-link--playoffs"
                                >
                                    PO
                                </router-link>
                            </div>
                        </div>
                    </div>
                </template>
            </div>
        </div>
    `,
    data() {
        return {
            loading: true,
            error: null,
            seasons: [],
            seasonsLoadToken: 0
        };
    },
    async mounted() {
        await this.loadSeasons();
    },
    methods: {
        async loadSeasons() {
            const requestToken = ++this.seasonsLoadToken;
            this.loading = true;
            this.error = null;
            
            try {
                const seasons = await window.apiClient.getSeasons({
                    force: true,
                    noCache: true,
                    persistCache: false
                });
                const normalized = await Promise.all(
                    (Array.isArray(seasons) ? seasons : []).map(async season => {
                        const seasonId = season.season ?? season.id ?? season.season_id ?? season.seasonId;
                        let divisions = [];

                        if (seasonId != null) {
                            try {
                                const response = await window.apiClient.getDivisions(seasonId, {
                                    force: true,
                                    noCache: true,
                                    persistCache: false
                                });
                                const fullList = response?.data ?? response ?? [];
                                const hasPlayoffsStarted =
                                    typeof window !== 'undefined' && window.divisionNormalizer?.hasPlayoffsStarted
                                        ? window.divisionNormalizer.hasPlayoffsStarted
                                        : null;

                                // Process regular divisions and embed playoff info
                                if (Array.isArray(fullList)) {
                                    divisions = fullList
                                        .filter(div => !div.is_playoff && !div.isPlayoff)
                                        .map(div => {
                                            const divName = (div.name || '').replace(/\s+S\d+$/i, '');
                                            const playoffData = div.playoffs || {};
                                            const fallbackStarted = (playoffData.matches_played || playoffData.matchesPlayed || 0) > 0;
                                            const hasPlayoffsStartedValue = hasPlayoffsStarted
                                                ? hasPlayoffsStarted(div)
                                                : fallbackStarted;

                                            return {
                                                id: div.divisionId || div.division_id || div.id,
                                                name: divName,
                                                tier: div.tier || div.division_num || 0,
                                                status: div.status,
                                                season: seasonId,
                                                hasPlayoffsStarted: hasPlayoffsStartedValue,
                                                raw: div
                                            };
                                        })
                                        .sort((a, b) => (a.tier || 0) - (b.tier || 0));
                                }
                            } catch (err) {
                                console.warn(`Failed to fetch divisions for season ${seasonId}:`, err);
                                divisions = [];
                            }
                        }

                        const divisionsCount = typeof season.divisions_count === 'number'
                            ? season.divisions_count
                            : divisions.length;

                        return {
                            ...season,
                            season: season.season ?? seasonId,
                            divisions,
                            divisions_count: divisionsCount
                        };
                    })
                );
                if (requestToken !== this.seasonsLoadToken) {
                    return;
                }
                this.seasons = normalized;
            } catch (err) {
                if (requestToken !== this.seasonsLoadToken) {
                    return;
                }
                this.error = err.message || 'Kausien lataus epäonnistui';
            } finally {
                if (requestToken !== this.seasonsLoadToken) {
                    return;
                }
                this.loading = false;
            }
        },
        getSeasonLabel(season) {
            return season.name || season.season || season.id || '—';
        },
        getDivisionList(season) {
            return Array.isArray(season.divisions) ? season.divisions : [];
        },
        getDivisionCount(season) {
            if (typeof season.divisions_count === 'number') {
                return season.divisions_count;
            }
            return this.getDivisionList(season).length;
        },
        resolveDivisionSlug(division) {
            const normalizer = typeof window !== 'undefined' ? window.divisionNormalizer : null;
            const slug = normalizer?.getDivisionSlug ? normalizer.getDivisionSlug(division) : null;
            return slug || division?.slug || division?.id || null;
        },
        getDivisionTitle(division) {
            const normalizer = typeof window !== 'undefined' ? window.divisionNormalizer : null;
            if (normalizer?.cleanDivisionName) {
                const clean = normalizer.cleanDivisionName(division?.name || '');
                if (clean) return clean;
            }
            return division?.name || '';
        },
        buildDivisionRoute(division, options = {}) {
            const divisionId = division?.divisionId || division?.division_id || division?.id;
            const slug = this.resolveDivisionSlug(division) || divisionId;
            const routeId = divisionId != null ? String(divisionId) : (slug != null ? String(slug) : '');
            if (!routeId) return '/division';
            return {
                name: 'division',
                params: { championshipId: routeId }
            };
        },
        getDivisionHref(division) {
            return this.buildDivisionRoute(division, { playoffs: false });
        },
        getPlayoffsHref(division) {
            const hrefId =
                (typeof window !== 'undefined' && window.divisionNormalizer?.getPlayoffsHrefId
                    ? window.divisionNormalizer.getPlayoffsHrefId(division)
                    : null) ||
                null;
            if (!hrefId) return '/division';
            return {
                name: 'division',
                params: { championshipId: String(hrefId) }
            };
        }
    }
};


/* === /static/views/TeamsView.js === */
window.TeamsView = {
    name: 'TeamsView',
    components: {
        get LoadingSpinner() { return window.LoadingSpinner; },
        get ErrorMessage() { return window.ErrorMessage; }
    },
    data() {
        return {
            loading: true,
            error: null,
            seasons: [],
            selectedSeasonId: '',
            teams: [],
            search: ''
        };
    },
    computed: {
        selectedSeasonLabel() {
            if (!this.selectedSeasonId) {
                return 'Kaikki kaudet';
            }
            const row = this.seasons.find(season => String(this.getSeasonId(season)) === String(this.selectedSeasonId));
            if (!row) {
                return `Kausi ${this.selectedSeasonId}`;
            }
            return this.getSeasonLabel(row);
        },
        filteredTeams() {
            const needle = String(this.search || '').trim().toLowerCase();
            if (!needle) {
                return this.teams;
            }
            return this.teams.filter(team => {
                const name = String(this.getTeamName(team)).toLowerCase();
                return name.includes(needle);
            });
        }
    },
    async mounted() {
        await this.loadAll();
    },
    watch: {
        selectedSeasonId() {
            this.loadTeams();
        }
    },
    methods: {
        async loadAll() {
            this.loading = true;
            this.error = null;
            try {
                const bundle = await window.apiClient.getSeasonsTeams({ limit: 5000 });
                const rawSeasons = Array.isArray(bundle.seasons) ? [...bundle.seasons] : [];
                this.seasons = rawSeasons.sort((a, b) => Number(this.getSeasonId(b) || 0) - Number(this.getSeasonId(a) || 0));
                this.teams = Array.isArray(bundle.teams)
                    ? [...bundle.teams].sort((a, b) => this.getTeamName(a).localeCompare(this.getTeamName(b), 'fi'))
                    : [];
            } catch (error) {
                this.error = error?.message || 'Tietojen lataus epäonnistui';
            } finally {
                this.loading = false;
            }
        },
        async loadTeams() {
            this.loading = true;
            this.error = null;
            try {
                const params = { limit: 5000 };
                if (this.selectedSeasonId) {
                    params.season = this.selectedSeasonId;
                }
                const rows = await window.apiClient.getTeams(params);
                this.teams = Array.isArray(rows)
                    ? [...rows].sort((a, b) => this.getTeamName(a).localeCompare(this.getTeamName(b), 'fi'))
                    : [];
            } catch (error) {
                this.error = error?.message || 'Joukkueiden lataus epäonnistui';
            } finally {
                this.loading = false;
            }
        },
        getTeamName(team) {
            return (
                team?.display_name ||
                team?.displayName ||
                team?.team_name ||
                team?.teamName ||
                team?.name ||
                'Tuntematon joukkue'
            );
        },
        getTeamId(team) {
            return team?.team_id || team?.teamId || null;
        },
        getPreferredChampionshipId(team) {
            const teamChampionshipId = team?.championship_id || team?.championshipId || null;
            if (teamChampionshipId != null && teamChampionshipId !== '') {
                return String(teamChampionshipId);
            }
            return null;
        },
        getTeamRoute(team) {
            const teamId = this.getTeamId(team);
            if (!teamId) {
                return { name: 'teams' };
            }
            const championshipId = this.getPreferredChampionshipId(team);
            if (championshipId) {
                return {
                    name: 'team-detail',
                    params: {
                        championshipId,
                        teamId: String(teamId)
                    }
                };
            }
            return {
                name: 'team',
                params: { teamId: String(teamId) }
            };
        },
        getTeamAvatar(team) {
            const fallback = window.PAPPALIIGA_DEFAULT_LOGO || '';
            const src = team?.avatar || fallback;
            try {
                if (window.apiClient && typeof window.apiClient.proxyAvatar === 'function') {
                    return window.apiClient.proxyAvatar(src) || fallback;
                }
                return src;
            } catch (error) {
                return src;
            }
        },
        getSeasonId(season) {
            return season?.id ?? season?.season ?? season?.season_id ?? season?.seasonId ?? null;
        },
        getSeasonLabel(season) {
            return season?.label || season?.name || `Kausi ${this.getSeasonId(season)}`;
        }
    },
    template: `
        <section class="teams-view">
            <header class="teams-view__header">
                <h1 class="title-accent titleUnderlinePage">Joukkueet</h1>
                <p class="teams-view__meta">{{ filteredTeams.length }} / {{ teams.length }} joukkuetta · {{ selectedSeasonLabel }}</p>
                <div class="teams-view__filters">
                    <select v-model="selectedSeasonId" class="teams-view__season">
                        <option value="">Kaikki kaudet</option>
                        <option
                            v-for="season in seasons"
                            :key="getSeasonId(season)"
                            :value="String(getSeasonId(season))"
                        >
                            {{ getSeasonLabel(season) }}
                        </option>
                    </select>
                    <input
                        v-model="search"
                        type="search"
                        class="teams-view__search"
                        placeholder="Hae joukkuetta..."
                        autocomplete="off"
                    />
                </div>
            </header>

            <loading-spinner
                v-if="loading"
                message="Joukkueita ladataan..."
            ></loading-spinner>
            <error-message
                v-else-if="error"
                :message="error"
                @retry="loadTeams"
            ></error-message>
            <div v-else class="teams-list-grid">
                <router-link
                    v-for="team in filteredTeams"
                    :key="getTeamId(team)"
                    :to="getTeamRoute(team)"
                    class="teams-list-card"
                >
                    <img
                        :src="getTeamAvatar(team)"
                        :alt="getTeamName(team)"
                        class="teams-list-card__avatar"
                        loading="lazy"
                    />
                    <span class="teams-list-card__name">{{ getTeamName(team) }}</span>
                </router-link>
            </div>
        </section>
    `
};


